"use strict";(self.webpackChunkvipzhicheng_com=self.webpackChunkvipzhicheng_com||[]).push([["5372"],{78179:function(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/2025/04/24/2025\u5E74\u6BCF\u4E2AJavaScript\u5F00\u53D1\u4EBA\u5458\u90FD\u5E94\u8BE5\u77E5\u9053\u7684\u4E00\u4E9B\u7279\u6027","metadata":{"permalink":"/transblog/2025/04/24/2025\u5E74\u6BCF\u4E2AJavaScript\u5F00\u53D1\u4EBA\u5458\u90FD\u5E94\u8BE5\u77E5\u9053\u7684\u4E00\u4E9B\u7279\u6027","source":"@site/blog-translated/2025/04-24-2025\u5E74\u6BCF\u4E2AJavaScript\u5F00\u53D1\u4EBA\u5458\u90FD\u5E94\u8BE5\u77E5\u9053\u7684\u4E00\u4E9B\u7279\u6027.md","title":"2025\u5E74\u6BCF\u4E2AJavaScript\u5F00\u53D1\u4EBA\u5458\u90FD\u5E94\u8BE5\u77E5\u9053\u7684\u4E00\u4E9B\u7279\u6027","description":"- \u539F\u6587\u94FE\u63A5\uFF1Ahttps://waspdev.com/articles/2025-04-06/features-that-every-js-developer-must-know-in-2025#somefeaturesthateveryjavascriptdevelopershouldknowin_2025","date":"2025-04-24T10:00:00.000Z","tags":[{"inline":true,"label":"JavaScript","permalink":"/transblog/tags/java-script"}],"readingTime":25.99,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"2025\u5E74\u6BCF\u4E2AJavaScript\u5F00\u53D1\u4EBA\u5458\u90FD\u5E94\u8BE5\u77E5\u9053\u7684\u4E00\u4E9B\u7279\u6027","date":"2025-04-24T10:00:00.000Z","tags":["JavaScript"]},"unlisted":false,"nextItem":{"title":"require() ESM in Node.js","permalink":"/transblog/2025/04/19/require-esm-in-node-js"}},"content":"> - \u539F\u6587\u94FE\u63A5\uFF1Ahttps://waspdev.com/articles/2025-04-06/features-that-every-js-developer-must-know-in-2025#some_features_that_every_javascript_developer_should_know_in_2025\\n> - \u673A\u5668\u7FFB\u8BD1\uFF1A Gemini 2.5 Pro Preview\\n> - \u63D0\u793A\u8BCD\uFF1A \xa0 \u4F60\u662F\u8D44\u6DF1\u524D\u7AEF\u4E13\u5BB6\uFF0C\u7FFB\u8BD1\u4EE5\u4E0B\u6587\u6863\uFF0C\u5E76\u4E14\u7ED3\u5408\u4F60\u7684\u524D\u7AEF\u5F00\u53D1\u4E13\u4E1A\u77E5\u8BC6\u8865\u5145\u76F8\u5173\u7684\u77E5\u8BC6\u70B9\u8BF4\u660E\uFF0C\u5BF9\u6587\u7AE0\u5185\u5BB9\u8FDB\u884C\u7ED3\u6784\u5316\uFF0C\u4EE5 Markdown \u683C\u5F0F\u8FD4\u56DE\uFF0C\u6587\u5B57\u98CE\u683C\u662F\u6280\u672F\u535A\u5BA2\uFF0C\u8981\u901A\u4FD7\u6613\u61C2\u3002\\n> - \u7FFB\u8BD1\u7406\u7531\uFF1A\u8FD9\u7BC7\u6587\u7AE0\u4ECB\u7ECD\u4E86\u4E00\u4E9B JS \u65B0\u7279\u6027\uFF0C\u76EE\u524D\u5DF2\u7ECF\u53EF\u4EE5\u5728\u5B9E\u9645\u5DE5\u4F5C\u4E2D\u4F7F\u7528\u4E86\uFF0C\u8BFB\u5B8C\u5F88\u6709\u6536\u83B7\uFF0C\u786E\u5B9E\u4E00\u4E9B\u5E38\u89C1\u7684\u9700\u6C42\uFF0C\u6211\u4EEC\u5E38\u7528\u7684\u5199\u6CD5\u672A\u5FC5\u662F\u6700\u4F73\u5B9E\u8DF5\uFF0C\u6216\u8005\u968F\u7740\u65F6\u95F4\u7684\u63A8\u79FB\u4E0D\u65AD\u6709\u66F4\u597D\u7684\u65B9\u6CD5\u51FA\u73B0\u3002\\n\\n\u54C8\u55BD\uFF0C\u5404\u4F4D\u594B\u6597\u5728\u4E00\u7EBF\u7684\u524D\u7AEF\u5C0F\u4F19\u4F34\u4EEC\uFF01JavaScript \u8FD9\u95E8\u8BED\u8A00\u4E00\u76F4\u5728\u9AD8\u901F\u8FDB\u5316\uFF0C\u65B0\u7279\u6027\u5C42\u51FA\u4E0D\u7A77\u3002\u8FD9\u4E5F\u610F\u5473\u7740\uFF0C\u6211\u4EEC\u8FC7\u53BB\u7684\u4E00\u4E9B\u7F16\u7801\u4E60\u60EF\u53EF\u80FD\u5DF2\u7ECF\u6084\u6084\u8FC7\u65F6\uFF0C\u751A\u81F3\u5728\u6548\u7387\u4E0A\u6253\u4E86\u6298\u6263\u3002\u4ECA\u5929\uFF0C\u6211\u4EEC\u5C31\u6765\u76D8\u70B9\u4E00\u4E9B\uFF08\u4E0D\u8BBA\u65B0\u65E7\uFF09\u4F46\u5F88\u591A\u5F00\u53D1\u8005\u53EF\u80FD\u8FD8\u6CA1\u7559\u610F\u5230\u7684\u3001\u975E\u5E38\u5B9E\u7528\u7684 JS \u7279\u6027\uFF0C\u4E00\u8D77\u7ED9\u81EA\u5DF1\u7684\u6280\u80FD\u5E93\u5145\u5145\u7535\uFF01\uD83D\uDD0B\\n\\n\x3c!--truncate--\x3e\\n\\n## 1. Iterator Helpers (\u8FED\u4EE3\u5668\u52A9\u624B)\uFF1A\u544A\u522B\u4F4E\u6548\u7684\u6570\u7EC4\u94FE\u5F0F\u64CD\u4F5C\\n\\n\u4F60\u6709\u6CA1\u6709\u5199\u8FC7\u7C7B\u4F3C\u8FD9\u6837\u7684\u4EE3\u7801\uFF1A`arr.slice(10, 20).filter(el => el < 10).map(el => el + 5)`\uFF1F\u8FD9\u79CD\u5728\u540C\u4E00\u4E2A\u6570\u7EC4\u4E0A\u8FDE\u7EED\u8FDB\u884C\u591A\u6B21\u8F6C\u6362\u7684\u64CD\u4F5C\uFF0C\u770B\u8D77\u6765\u5F88\u9177\uFF0C\u4F46\u5176\u5B9E\u6548\u7387\u4E0D\u9AD8\u3002\u4E3A\u5565\uFF1F\u56E0\u4E3A\u6BCF\u4E00\u6B21 `slice`, `filter`, `map` \u64CD\u4F5C\uFF0C\u90FD\u4F1A\u521B\u5EFA\u4E00\u4E2A\u5168\u65B0\u7684\u4E2D\u95F4\u6570\u7EC4\u3002\u60F3\u8C61\u4E00\u4E0B\uFF0C\u5982\u679C `arr` \u662F\u4E00\u4E2A\u5305\u542B\u51E0\u5341\u4E07\u751A\u81F3\u4E0A\u767E\u4E07\u5143\u7D20\u7684\u5DE8\u578B\u6570\u7EC4\uFF0C\u90A3\u5185\u5B58\u5F00\u9500\u548C\u6027\u80FD\u635F\u8017\u53EF\u5C31\u76F8\u5F53\u53EF\u89C2\u4E86\uFF01\uD83D\uDE31\\n\\n\u4E3A\u4E86\u89E3\u51B3\u8FD9\u4E2A\u95EE\u9898\uFF0CJavaScript \u6700\u8FD1\u5F15\u5165\u4E86\u4E00\u7CFB\u5217 **\u8FED\u4EE3\u5668\u52A9\u624B\uFF08Iterator Helpers\uFF09** \u65B9\u6CD5\u3002\u5B83\u4EEC\u7684\u4F5C\u7528\u548C\u6211\u4EEC\u719F\u6089\u7684\u6570\u7EC4\u8F6C\u6362\u65B9\u6CD5\uFF08`map`, `filter` \u7B49\uFF09\u7C7B\u4F3C\uFF0C\u4F46\u5173\u952E\u533A\u522B\u5728\u4E8E\uFF1A**\u5B83\u4EEC\u4E0D\u4F1A\u6BCF\u6B21\u90FD\u521B\u5EFA\u4E34\u65F6\u6570\u7EC4\uFF0C\u800C\u662F\u521B\u5EFA\u65B0\u7684\u8FED\u4EE3\u5668\uFF0C\u8FD9\u4E9B\u8FED\u4EE3\u5668\u57FA\u4E8E\u524D\u4E00\u4E2A\u8FED\u4EE3\u5668\u8FDB\u884C\u64CD\u4F5C\uFF0C\u76F4\u5230\u6700\u540E\u624D\u53EF\u80FD\u751F\u6210\u7ED3\u679C**\u3002\u8FD9\u662F\u4E00\u79CD\u66F4\u201C\u61D2\u60F0\u201D\uFF08Lazy Evaluation\uFF09\u4E14\u5185\u5B58\u53CB\u597D\u7684\u65B9\u5F0F\u3002\\n\\n\u6765\u770B\u770B\u8FD9\u4E9B\u5F97\u529B\u52A9\u624B\u4EEC\uFF1A\\n\\n1.  **`Iterator.prototype.drop(n)`**: \u8DF3\u8FC7\u8FED\u4EE3\u5668\u5F00\u5934\u7684 `n` \u4E2A\u5143\u7D20\uFF0C\u8FD4\u56DE\u4E00\u4E2A\u65B0\u7684\u8FED\u4EE3\u5668\u52A9\u624B\u5BF9\u8C61\u3002\u6709\u70B9\u50CF\u6570\u7EC4\u7684 `Array.prototype.slice(n)`\u3002\\n2.  **`Iterator.prototype.take(n)`**: \u6700\u591A\u83B7\u53D6\u8FED\u4EE3\u5668\u5F00\u5934\u7684 `n` \u4E2A\u5143\u7D20\uFF0C\u8FD4\u56DE\u4E00\u4E2A\u65B0\u7684\u8FED\u4EE3\u5668\u52A9\u624B\u5BF9\u8C61\u3002\u7C7B\u4F3C\u4E8E\u6570\u7EC4\u7684 `Array.prototype.slice(0, n)`\u3002\\n3.  **`Iterator.prototype.some(callback)`**: \u548C `Array.prototype.some()` \u7C7B\u4F3C\uFF0C\u6D4B\u8BD5\u8FED\u4EE3\u5668\u4E2D\u662F\u5426\u81F3\u5C11\u6709\u4E00\u4E2A\u5143\u7D20\u6EE1\u8DB3 `callback` \u51FD\u6570\u7684\u6D4B\u8BD5\u3002\\n4.  **`Iterator.prototype.every(callback)`**: \u548C `Array.prototype.every()` \u7C7B\u4F3C\uFF0C\u6D4B\u8BD5\u8FED\u4EE3\u5668\u4E2D\u662F\u5426\u6240\u6709\u5143\u7D20\u90FD\u6EE1\u8DB3 `callback` \u51FD\u6570\u7684\u6D4B\u8BD5\u3002\\n5.  **`Iterator.prototype.filter(callback)`**: \u548C `Array.prototype.filter()` \u7C7B\u4F3C\uFF0C\u8FD4\u56DE\u4E00\u4E2A\u5305\u542B\u901A\u8FC7 `callback` \u6D4B\u8BD5\u7684\u5143\u7D20\u7684\u65B0\u8FED\u4EE3\u5668\u3002\\n6.  **`Iterator.prototype.find(callback)`**: \u548C `Array.prototype.find()` \u7C7B\u4F3C\uFF0C\u8FD4\u56DE\u8FED\u4EE3\u5668\u4E2D\u7B2C\u4E00\u4E2A\u6EE1\u8DB3 `callback` \u6D4B\u8BD5\u7684\u5143\u7D20\u3002\\n7.  **`Iterator.prototype.flatMap(callback)`**: \u548C `Array.prototype.flatMap()` \u7C7B\u4F3C\uFF0C\u5148\u6620\u5C04\u6BCF\u4E2A\u5143\u7D20\uFF0C\u7136\u540E\u5C06\u7ED3\u679C\u5C55\u5E73\u4E00\u5C42\uFF0C\u8FD4\u56DE\u4E00\u4E2A\u65B0\u8FED\u4EE3\u5668\u3002\\n8.  **`Iterator.prototype.forEach(callback)`**: \u548C `Array.prototype.forEach()` \u7C7B\u4F3C\uFF0C\u4E3A\u8FED\u4EE3\u5668\u4E2D\u7684\u6BCF\u4E2A\u5143\u7D20\u6267\u884C\u4E00\u6B21 `callback` \u51FD\u6570\u3002\\n9.  **`Iterator.prototype.map(callback)`**: \u548C `Array.prototype.map()` \u7C7B\u4F3C\uFF0C\u8FD4\u56DE\u4E00\u4E2A\u5305\u542B\u7ECF `callback` \u8F6C\u6362\u540E\u7684\u5143\u7D20\u7684\u65B0\u8FED\u4EE3\u5668\u3002\\n10. **`Iterator.prototype.reduce(callback, initialValue)`**: \u548C `Array.prototype.reduce()` \u7C7B\u4F3C\uFF0C\u5BF9\u8FED\u4EE3\u5668\u4E2D\u7684\u6BCF\u4E2A\u5143\u7D20\u6267\u884C \\"reducer\\" \u51FD\u6570\uFF0C\u5C06\u5176\u7D2F\u79EF\u6210\u5355\u4E2A\u503C\u3002\\n11. **`Iterator.prototype.toArray()`**: \u8FD9\u662F\u7EC8\u7ED3\u64CD\u4F5C\u4E4B\u4E00\uFF0C\u5B83\u904D\u5386\u6574\u4E2A\u8FED\u4EE3\u5668\u94FE\uFF0C\u5E76\u5C06\u6700\u7EC8\u4EA7\u751F\u7684\u6240\u6709\u503C\u6536\u96C6\u5230\u4E00\u4E2A\u65B0\u7684\u6570\u7EC4\u4E2D\u3002\\n\\n**\u5982\u4F55\u521B\u5EFA\u8FED\u4EE3\u5668\uFF1F**\\n\\n- \u5F88\u591A\u5185\u7F6E\u5BF9\u8C61\uFF08\u5982 `Array`, `Map`, `Set`, `NodeList` \u7B49\uFF09\u90FD\u6709 `values()` \u65B9\u6CD5\u53EF\u4EE5\u83B7\u53D6\u8FED\u4EE3\u5668\u3002\\n- \u53EF\u4EE5\u4F7F\u7528\u9759\u6001\u65B9\u6CD5 `Iterator.from()` \u5C06\u4E00\u4E2A\u53EF\u8FED\u4EE3\u5BF9\u8C61\uFF08\u6BD4\u5982\u4E00\u4E2A\u5B9E\u73B0\u4E86 `Symbol.iterator` \u7684\u5BF9\u8C61\uFF09\u8F6C\u6362\u6210\u8FED\u4EE3\u5668\u52A9\u624B\u5BF9\u8C61\u3002\\n\\n**\u56DE\u5230\u5F00\u5934\u7684\u4F8B\u5B50\uFF0C\u7528\u8FED\u4EE3\u5668\u52A9\u624B\u4F18\u5316\u540E\u5C31\u662F\u8FD9\u6837\uFF1A**\\n\\n```javascript\\n// \u5047\u8BBE arr \u662F\u4E00\u4E2A\u5927\u6570\u7EC4\\nconst result = arr\\n  .values() // 1. \u83B7\u53D6\u6570\u7EC4\u8FED\u4EE3\u5668\\n  .drop(10) // 2. \u8DF3\u8FC7\u524D10\u4E2A (\u8FD4\u56DE\u65B0\u8FED\u4EE3\u5668)\\n  .take(10) // 3. \u6700\u591A\u53D610\u4E2A (\u8FD4\u56DE\u65B0\u8FED\u4EE3\u5668)\\n  .filter((el) => el < 10) // 4. \u8FC7\u6EE4 (\u8FD4\u56DE\u65B0\u8FED\u4EE3\u5668)\\n  .map((el) => el + 5) // 5. \u6620\u5C04 (\u8FD4\u56DE\u65B0\u8FED\u4EE3\u5668)\\n  .toArray(); // 6. \u6700\u540E\u751F\u6210\u6570\u7EC4\\n\\n// \u6574\u4E2A\u8FC7\u7A0B\u53EA\u5728\u6700\u540E toArray() \u65F6\u521B\u5EFA\u4E86\u4E00\u4E2A\u65B0\u6570\u7EC4\uFF0C\u4E2D\u95F4\u6B65\u9AA4\u51E0\u4E4E\u6CA1\u6709\u989D\u5916\u5185\u5B58\u5206\u914D\uFF01\\n```\\n\\n## 2. Array.prototype.at()\uFF1A\u4F18\u96C5\u5730\u8BBF\u95EE\u6570\u7EC4\u672B\u5C3E\u5143\u7D20\\n\\n\u60F3\u83B7\u53D6\u6570\u7EC4\u7684\u7B2C `n` \u4E2A\u5143\u7D20\uFF0C\u6211\u4EEC\u901A\u5E38\u7528 `arr[n]`\u3002\u4F46\u5982\u679C\u60F3\u83B7\u53D6\u5012\u6570\u7B2C\u4E00\u4E2A\u3001\u5012\u6570\u7B2C\u4E8C\u4E2A\u5143\u7D20\u5462\uFF1F\u4EE5\u524D\u6211\u4EEC\u5F97\u5199 `arr[arr.length - 1]`\u3001`arr[arr.length - 2]`\uFF0C\u4EE3\u7801\u663E\u5F97\u6709\u70B9\u5570\u55E6\u7B28\u62D9\u3002\\n\\n\u73B0\u5728\u6709\u4E86 `Array.prototype.at()`\uFF0C\u4E8B\u60C5\u53D8\u5F97\u7B80\u5355\u591A\u4E86\uFF01\\n\\n- \u5B83\u63A5\u53D7\u4E00\u4E2A\u6574\u6570\u4F5C\u4E3A\u53C2\u6570\uFF0C\u8868\u793A\u8981\u8BBF\u95EE\u7684\u5143\u7D20\u7684\u7D22\u5F15\u3002\\n- **\u6700\u9177\u7684\u662F\uFF1A\u5B83\u652F\u6301\u8D1F\u6570\u7D22\u5F15\uFF01** `-1` \u8868\u793A\u6700\u540E\u4E00\u4E2A\u5143\u7D20\uFF0C`-2` \u8868\u793A\u5012\u6570\u7B2C\u4E8C\u4E2A\uFF0C\u4EE5\u6B64\u7C7B\u63A8\u3002\\n\\n```javascript\\nconst colors = [\\"red\\", \\"green\\", \\"blue\\"];\\n\\nconsole.log(colors.at(1)); // \'green\' (\u6B63\u6570\u7D22\u5F15\uFF0C\u548C colors[1] \u4E00\u6837)\\nconsole.log(colors.at(-1)); // \'blue\'  (\u5012\u6570\u7B2C\u4E00\u4E2A)\\nconsole.log(colors.at(-2)); // \'green\' (\u5012\u6570\u7B2C\u4E8C\u4E2A)\\nconsole.log(colors.at(5)); // undefined (\u7D22\u5F15\u8D8A\u754C)\\nconsole.log(colors.at(-5)); // undefined (\u7D22\u5F15\u8D8A\u754C)\\n\\n// \u544A\u522B\u7E41\u7410\u7684 arr[arr.length - n]\\nconsole.log(colors[colors.length - 1]); // \'blue\' (\u65E7\u65B9\u6CD5)\\nconsole.log(colors.at(-1)); // \'blue\' (\u65B0\u65B9\u6CD5\uFF0C\u66F4\u7B80\u6D01\uFF01)\\n```\\n\\n\u8FD9\u4E2A\u65B9\u6CD5\u4E0D\u4EC5\u9002\u7528\u4E8E\u6570\u7EC4\uFF0C\u4E5F\u9002\u7528\u4E8E\u5B57\u7B26\u4E32 (`String.prototype.at()`) \u548C TypedArrays\u3002\u4EE3\u7801\u66F4\u7B80\u6D01\uFF0C\u53EF\u8BFB\u6027\u4E5F\u66F4\u9AD8\u4E86\uFF01\\n\\n## 3. Promise.withResolvers()\uFF1A\u8F7B\u677E\u638C\u63A7 Promise \u7684\u72B6\u6001\\n\\n\u5728\u67D0\u4E9B\u590D\u6742\u7684\u5F02\u6B65\u573A\u666F\u4E0B\uFF0C\u6211\u4EEC\u53EF\u80FD\u9700\u8981\u5148\u521B\u5EFA\u4E00\u4E2A Promise\uFF0C\u7136\u540E\u5728\u7A0D\u540E\u7684\u67D0\u4E2A\u65F6\u523B\u3001\u4ECE\u5916\u90E8\u63A7\u5236\u5B83\u7684\u72B6\u6001\uFF08resolve \u6216 reject\uFF09\u3002\u4EE5\u524D\uFF0C\u6211\u4EEC\u901A\u5E38\u8FD9\u6837\u505A\uFF1A\\n\\n```javascript\\nlet resolveCallback, rejectCallback;\\n\\nconst promise = new Promise((resolve, reject) => {\\n  // \u628A resolve \u548C reject \u51FD\u6570\u66B4\u9732\u51FA\u6765\\n  resolveCallback = resolve;\\n  rejectCallback = reject;\\n});\\n\\n// ... \u5728\u4EE3\u7801\u7684\u5176\u4ED6\u5730\u65B9 ...\\nfunction someAsyncOperation() {\\n  // \u5F02\u6B65\u64CD\u4F5C\u6210\u529F\\n  if (success) {\\n    resolveCallback(\\"\u64CD\u4F5C\u6210\u529F\u7684\u6570\u636E\\");\\n  } else {\\n    // \u5F02\u6B65\u64CD\u4F5C\u5931\u8D25\\n    rejectCallback(new Error(\\"\u64CD\u4F5C\u5931\u8D25\\"));\\n  }\\n}\\n\\n// \u4F7F\u7528 promise\\npromise.then((data) => console.log(data)).catch((err) => console.error(err));\\n```\\n\\n\u662F\u4E0D\u662F\u611F\u89C9\u6709\u70B9\u7ED5\uFF1F\u4EE3\u7801\u4E0D\u591F\u7D27\u51D1\u3002\u597D\u6D88\u606F\u662F\uFF0C\u73B0\u5728\u6709\u4E86 `Promise.withResolvers()` \u8FD9\u4E2A\u9759\u6001\u65B9\u6CD5\uFF0C\u53EF\u4EE5\u66F4\u4F18\u96C5\u5730\u5B9E\u73B0\u540C\u6837\u7684\u6548\u679C\uFF1A\\n\\n```javascript\\n// \u4E00\u884C\u4EE3\u7801\u641E\u5B9A\uFF01\\nconst { promise, resolve, reject } = Promise.withResolvers();\\n\\n// ... \u5728\u4EE3\u7801\u7684\u5176\u4ED6\u5730\u65B9 ...\\nfunction someAsyncOperation() {\\n  if (success) {\\n    resolve(\\"\u64CD\u4F5C\u6210\u529F\u7684\u6570\u636E\\"); // \u76F4\u63A5\u4F7F\u7528\u89E3\u6784\u51FA\u6765\u7684 resolve\\n  } else {\\n    reject(new Error(\\"\u64CD\u4F5C\u5931\u8D25\\")); // \u76F4\u63A5\u4F7F\u7528\u89E3\u6784\u51FA\u6765\u7684 reject\\n  }\\n}\\n\\n// \u4F7F\u7528 promise\\npromise.then((data) => console.log(data)).catch((err) => console.error(err));\\n```\\n\\n`Promise.withResolvers()` \u76F4\u63A5\u8FD4\u56DE\u4E00\u4E2A\u5305\u542B `promise`\u3001`resolve` \u51FD\u6570\u548C `reject` \u51FD\u6570\u7684\u5BF9\u8C61\uFF0C\u4EE3\u7801\u77AC\u95F4\u6E05\u723D\u4E86\u5F88\u591A\uFF01\u8FD9\u4E2A\u7279\u6027\u5BF9\u4E8E\u5B9E\u73B0\u4E00\u4E9B\u9700\u8981\u5916\u90E8\u4FE1\u53F7\u6765\u5B8C\u6210\u7684\u5F02\u6B65\u6D41\u7A0B\uFF08\u6BD4\u5982\u7B49\u5F85\u67D0\u4E2A\u4E8B\u4EF6\u89E6\u53D1\uFF09\u7279\u522B\u6709\u7528\u3002\\n\\n## 4. String.prototype.replace() / replaceAll() \u7684\u56DE\u8C03\u51FD\u6570\uFF1A\u5F3A\u5927\u7684\u52A8\u6001\u66FF\u6362\\n\\n`replace()` \u548C `replaceAll()` \u7528\u6765\u66FF\u6362\u5B57\u7B26\u4E32\u4E2D\u7684\u5B50\u4E32\uFF0C\u8FD9\u6211\u4EEC\u90FD\u77E5\u9053\u3002\u4F46\u4F60\u77E5\u9053\u5417\uFF1F\u5B83\u4EEC\u7684\u7B2C\u4E8C\u4E2A\u53C2\u6570**\u4E0D\u4EC5\u53EF\u4EE5\u662F\u66FF\u6362\u5B57\u7B26\u4E32\uFF0C\u8FD8\u53EF\u4EE5\u662F\u4E00\u4E2A\u56DE\u8C03\u51FD\u6570**\uFF01\u8FD9\u53EF\u5C31\u5389\u5BB3\u4E86\uFF0C\u5B83\u8D4B\u4E88\u4E86\u6211\u4EEC\u8FDB\u884C\u52A8\u6001\u3001\u4E0A\u4E0B\u6587\u76F8\u5173\u66FF\u6362\u7684\u80FD\u529B\u3002\\n\\n\u8FD9\u4E2A\u56DE\u8C03\u51FD\u6570\u4F1A\u63A5\u6536\u5230\u5339\u914D\u5230\u7684\u5B50\u4E32\uFF08\u4EE5\u53CA\u5176\u4ED6\u4FE1\u606F\uFF0C\u5982\u6355\u83B7\u7EC4\u3001\u7D22\u5F15\u4F4D\u7F6E\u7B49\uFF09\uFF0C\u7136\u540E**\u51FD\u6570\u7684\u8FD4\u56DE\u503C\u5C06\u4F5C\u4E3A\u66FF\u6362\u5185\u5BB9**\u3002\\n\\n\u6765\u770B\u4E2A\u4F8B\u5B50\uFF0C\u7ED9\u53E5\u5B50\u4E2D\u6240\u6709\u51FA\u73B0\u7684 \\"NUMBER\\" \u52A8\u6001\u7F16\u53F7\uFF1A\\n\\n```javascript\\nlet counter = 0;\\nconst text =\\n  \\"Found NUMBER item, then another NUMBER item, and finally the last NUMBER.\\";\\n\\nconst result = text.replaceAll(\\"NUMBER\\", (match) => {\\n  // match \u5C31\u662F\u5339\u914D\u5230\u7684 \\"NUMBER\\"\\n  counter++;\\n  return `${match}=${counter}`; // \u8FD4\u56DE\u52A8\u6001\u751F\u6210\u7684\u66FF\u6362\u5185\u5BB9\\n});\\n\\nconsole.log(result);\\n// \u8F93\u51FA: \\"Found NUMBER=1 item, then another NUMBER=2 item, and finally the last NUMBER=3.\\"\\n```\\n\\n\u8FD9\u4E2A\u7279\u6027\u975E\u5E38\u5F3A\u5927\u4E14\u9AD8\u6548\uFF1A\\n\\n- **\u52A8\u6001\u66FF\u6362**\uFF1A\u53EF\u4EE5\u6839\u636E\u5339\u914D\u5230\u7684\u5185\u5BB9\u3001\u4E0A\u4E0B\u6587\u3001\u751A\u81F3\u5916\u90E8\u72B6\u6001\u6765\u51B3\u5B9A\u66FF\u6362\u4E3A\u4EC0\u4E48\u3002\\n- **\u4E00\u6B21\u904D\u5386**\uFF1A`replaceAll` \u914D\u5408\u56DE\u8C03\uFF0C\u53EA\u9700\u8981\u4E00\u6B21\u904D\u5386\u5C31\u80FD\u5B8C\u6210\u6240\u6709\u52A8\u6001\u66FF\u6362\uFF0C\u76F8\u6BD4\u591A\u6B21\u8C03\u7528 `replace` \u6027\u80FD\u66F4\u597D\uFF0C\u5185\u5B58\u5360\u7528\u4E5F\u66F4\u4F4E\u3002\\n- **\u590D\u6742\u903B\u8F91**\uFF1A\u53EF\u4EE5\u5728\u56DE\u8C03\u51FD\u6570\u91CC\u6267\u884C\u66F4\u590D\u6742\u7684\u903B\u8F91\uFF0C\u6BD4\u5982\u67E5\u8868\u3001\u8BA1\u7B97\u7B49\u3002\\n\\n\u60F3\u4E86\u89E3\u56DE\u8C03\u51FD\u6570\u7684\u8BE6\u7EC6\u53C2\u6570\uFF0C\u53EF\u4EE5\u67E5\u9605 [MDN \u6587\u6863](https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/String/replace#\u6307\u5B9A\u4E00\u4E2A\u51FD\u6570\u4F5C\u4E3A\u53C2\u6570)\u3002\\n\\n## 5. \u53D8\u91CF\u4EA4\u6362\uFF1A\u66F4\u4F18\u96C5\u7684 ES6 \u65B9\u5F0F\\n\\n\u4EA4\u6362\u4E24\u4E2A\u53D8\u91CF\u7684\u503C\uFF0C\u7ECF\u5178\u7684\u201C\u4E09\u676F\u6C34\u201D\u65B9\u6CD5\u662F\u4F7F\u7528\u4E00\u4E2A\u4E34\u65F6\u53D8\u91CF\uFF1A\\n\\n```javascript\\nlet a = 1,\\n  b = 2;\\nconsole.log(a, b); // 1, 2\\n\\nconst temp = a;\\na = b;\\nb = temp;\\n\\nconsole.log(a, b); // 2, 1\\n```\\n\\n\u867D\u7136\u53EF\u884C\uFF0C\u4F46\u4E0D\u591F\u7B80\u6D01\u3002\u5728 ES6 \u4E2D\uFF0C\u6211\u4EEC\u53EF\u4EE5\u5229\u7528**\u6570\u7EC4\u89E3\u6784\u8D4B\u503C (Destructuring Assignment)** \u6765\u5B9E\u73B0\u66F4\u4F18\u96C5\u7684\u53D8\u91CF\u4EA4\u6362\uFF1A\\n\\n```javascript\\nlet a = 1,\\n  b = 2;\\nconsole.log(a, b); // 1, 2\\n\\n[a, b] = [b, a]; // \u4E00\u884C\u4EE3\u7801\uFF0C\u641E\u5B9A\uFF01\\n\\nconsole.log(a, b); // 2, 1\\n```\\n\\n\u662F\u4E0D\u662F\u77AC\u95F4\u611F\u89C9\u4EE3\u7801\u903C\u683C\u9AD8\u4E86\u4E0D\u5C11\uFF1F\u8FD9\u5229\u7528\u4E86\u7B49\u53F7\u53F3\u4FA7\u5148\u521B\u5EFA\u4E00\u4E2A\u4E34\u65F6\u6570\u7EC4 `[b, a]`\uFF08\u5373 `[2, 1]`\uFF09\uFF0C\u7136\u540E\u5DE6\u4FA7\u901A\u8FC7\u89E3\u6784\u8D4B\u503C\uFF0C\u5C06\u8FD9\u4E2A\u4E34\u65F6\u6570\u7EC4\u7684\u7B2C\u4E00\u4E2A\u5143\u7D20\u8D4B\u7ED9 `a`\uFF0C\u7B2C\u4E8C\u4E2A\u5143\u7D20\u8D4B\u7ED9 `b`\u3002\u7B80\u6D01\u3001\u76F4\u89C2\u3001\u9AD8\u6548\uFF01\\n\\n## 6. structuredClone()\uFF1A\u66F4\u9760\u8C31\u7684\u6DF1\u62F7\u8D1D\u9009\u62E9\\n\\n\u6DF1\u62F7\u8D1D\uFF08Deep Copy\uFF09\u5BF9\u8C61\u662F\u524D\u7AEF\u5F00\u53D1\u4E2D\u5E38\u89C1\u7684\u9700\u6C42\u3002\u5F88\u591A\u4EBA\u4E60\u60EF\u4F7F\u7528 `JSON.stringify()` \u548C `JSON.parse()` \u7684\u7EC4\u5408\u62F3\u6765\u5B9E\u73B0\uFF1A`const clonedObj = JSON.parse(JSON.stringify(originalObj))`\u3002\u8FD9\u79CD\u65B9\u6CD5\u7B80\u5355\u7C97\u66B4\uFF0C\u4F46\u5728\u5F88\u591A\u60C5\u51B5\u4E0B\u5E76\u4E0D\u53EF\u9760\uFF0C\u751A\u81F3\u4F1A\u51FA\u9519\uFF01\\n\\n**`JSON.stringify()` / `JSON.parse()` \u6DF1\u62F7\u8D1D\u7684\u201C\u5751\u201D\uFF1A**\\n\\n1.  **\u4E22\u5931\u6216\u8F6C\u6362\u7279\u5B9A\u503C\u7C7B\u578B**\uFF1A\\n    - `undefined`\u3001`Function`\u3001`Symbol` \u7C7B\u578B\u7684\u503C\uFF0C\u5728 `JSON.stringify` \u65F6\u4F1A\u88AB\u5FFD\u7565\uFF08\u5982\u679C\u5728\u5BF9\u8C61\u4E2D\uFF09\u6216\u8F6C\u6362\u4E3A `null`\uFF08\u5982\u679C\u5728\u6570\u7EC4\u4E2D\uFF09\u3002\\n    - `NaN`\u3001`Infinity`\u3001`-Infinity` \u4F1A\u88AB\u8F6C\u6362\u4E3A `null`\u3002\\n    - `Date` \u5BF9\u8C61\u4F1A\u88AB\u8F6C\u6362\u4E3A ISO \u683C\u5F0F\u7684\u5B57\u7B26\u4E32\uFF0C`parse` \u540E\u4E0D\u4F1A\u81EA\u52A8\u53D8\u56DE `Date` \u5BF9\u8C61\u3002\\n    - `RegExp` \u6B63\u5219\u8868\u8FBE\u5F0F\u5BF9\u8C61\u4F1A\u88AB\u8F6C\u6362\u4E3A\u7A7A\u5BF9\u8C61 `{}`\u3002\\n    - `Map`\u3001`Set` \u4F1A\u88AB\u8F6C\u6362\u4E3A\u7A7A\u5BF9\u8C61 `{}`\u3002\\n    - \u4E0D\u652F\u6301 `BigInt` \u7C7B\u578B\uFF0C\u4F1A\u76F4\u63A5\u629B\u51FA `TypeError`\u3002\\n2.  **\u65E0\u6CD5\u5904\u7406\u5FAA\u73AF\u5F15\u7528**\uFF1A\u5982\u679C\u5BF9\u8C61\u5185\u90E8\u5B58\u5728\u5FAA\u73AF\u5F15\u7528\uFF08\u4F8B\u5982 `obj.self = obj`\uFF09\uFF0C`JSON.stringify()` \u4F1A\u629B\u51FA `TypeError`\u3002\\n    ```javascript\\n    const obj = {};\\n    obj.selfReference = obj;\\n    // console.log(JSON.stringify(obj)); // Uncaught TypeError: Converting circular structure to JSON\\n    ```\\n3.  **\u6027\u80FD\u95EE\u9898**\uFF1A\u5BF9\u4E8E\u975E\u5E38\u5927\u7684\u6216\u5D4C\u5957\u5F88\u6DF1\u7684\u5BF9\u8C61\uFF0C\u5148\u5E8F\u5217\u5316\u4E3A\u5E9E\u5927\u7684 JSON \u5B57\u7B26\u4E32\uFF0C\u518D\u89E3\u6790\u56DE\u6765\uFF0C\u6027\u80FD\u5F00\u9500\u548C\u5185\u5B58\u5360\u7528\u90FD\u6BD4\u8F83\u5927\u3002\\n\\n**\u63A8\u8350\u4F7F\u7528 `structuredClone()`**\\n\\n\u5E78\u8FD0\u7684\u662F\uFF0C\u73B0\u4EE3\u6D4F\u89C8\u5668\u548C Node.js \u73AF\u5883\u90FD\u5185\u7F6E\u4E86 `structuredClone()` API\u3002\u5B83\u4E13\u95E8\u7528\u4E8E\u6267\u884C\u6DF1\u62F7\u8D1D\uFF0C\u5E76\u4E14\u80FD\u591F\u6B63\u786E\u5904\u7406\u8BB8\u591A `JSON` \u65B9\u6CD5\u65E0\u6CD5\u5904\u7406\u7684\u60C5\u51B5\u3002\\n\\n`structuredClone()` \u7684\u4F18\u52BF\uFF1A\\n\\n- **\u652F\u6301\u66F4\u591A\u7C7B\u578B**\uFF1A\u80FD\u6B63\u786E\u514B\u9686 `Date`, `RegExp`, `Map`, `Set`, `Blob`, `File`, `ImageData`, `ArrayBuffer`, `TypedArray` \u7B49\u591A\u79CD\u7C7B\u578B\u3002\\n- **\u81EA\u52A8\u5904\u7406\u5FAA\u73AF\u5F15\u7528**\uFF1A\u65E0\u9700\u62C5\u5FC3\u5FAA\u73AF\u5F15\u7528\u95EE\u9898\uFF0C`structuredClone()` \u4F1A\u6B63\u786E\u5730\u5728\u514B\u9686\u5BF9\u8C61\u4E2D\u91CD\u5EFA\u8FD9\u4E9B\u5F15\u7528\u5173\u7CFB\u3002\\n- **\u6027\u80FD\u901A\u5E38\u66F4\u597D**\uFF1A\u5E95\u5C42\u4F7F\u7528\u7ED3\u6784\u5316\u514B\u9686\u7B97\u6CD5\uFF08\u4E0E Web Workers `postMessage`\u3001IndexedDB \u5B58\u50A8\u5BF9\u8C61\u65F6\u4F7F\u7528\u7684\u7B97\u6CD5\u76F8\u540C\uFF09\uFF0C\u901A\u5E38\u6BD4 `JSON` \u5E8F\u5217\u5316/\u53CD\u5E8F\u5217\u5316\u66F4\u5FEB\uFF0C\u5185\u5B58\u6548\u7387\u4E5F\u66F4\u9AD8\u3002\\n\\n```javascript\\nconst original = {\\n  date: new Date(),\\n  regex: /hello/g,\\n  map: new Map([[\\"a\\", 1]]),\\n  set: new Set([1, 2]),\\n  undef: undefined,\\n  num: 123,\\n  // BigInt \u9700\u8981\u6CE8\u610F\uFF0C\u867D\u7136 structuredClone \u652F\u6301\uFF0C\u4F46 JSON \u4E0D\u652F\u6301\\n  // bigNum: 123n, // \u5982\u679C\u8981\u7528 JSON \u5E8F\u5217\u5316\uFF0C\u8FD9\u884C\u4F1A\u62A5\u9519\\n};\\noriginal.circular = original; // \u6DFB\u52A0\u5FAA\u73AF\u5F15\u7528\\n\\n// \u4F7F\u7528 structuredClone\\nconst cloned = structuredClone(original);\\n\\nconsole.log(cloned !== original); // true (\u662F\u4E0D\u540C\u7684\u5BF9\u8C61\u5F15\u7528)\\nconsole.log(cloned.date instanceof Date); // true (\u4ECD\u7136\u662F Date \u5BF9\u8C61)\\nconsole.log(cloned.regex instanceof RegExp); // true (\u4ECD\u7136\u662F RegExp \u5BF9\u8C61)\\nconsole.log(cloned.map instanceof Map); // true (\u4ECD\u7136\u662F Map \u5BF9\u8C61)\\nconsole.log(cloned.set instanceof Set); // true (\u4ECD\u7136\u662F Set \u5BF9\u8C61)\\nconsole.log(cloned.undef); // undefined (undefined \u88AB\u4FDD\u7559\u4E86)\\nconsole.log(cloned.circular === cloned); // true (\u5FAA\u73AF\u5F15\u7528\u4E5F\u6B63\u786E\u514B\u9686\u4E86)\\n\\n// \u5BF9\u6BD4 JSON \u65B9\u6CD5 (\u4F1A\u4E22\u5931\u4FE1\u606F\u6216\u6539\u53D8\u7C7B\u578B)\\n// const jsonCloned = JSON.parse(JSON.stringify(original)); // \u5982\u679C\u5305\u542B BigInt \u4F1A\u62A5\u9519\\n// console.log(jsonCloned.date); // \u53D8\u6210\u5B57\u7B26\u4E32\u4E86\\n// console.log(jsonCloned.regex); // \u53D8\u6210 {}\\n// console.log(jsonCloned.map); // \u53D8\u6210 {}\\n// console.log(jsonCloned.set); // \u53D8\u6210 {}\\n// console.log(jsonCloned.undef); // undefined \u4E22\u5931\u4E86 (\u5C5E\u6027\u76F4\u63A5\u6CA1\u4E86)\\n// console.log(JSON.stringify(original)); // \u5982\u679C\u6709\u5FAA\u73AF\u5F15\u7528\uFF0C\u8FD9\u6B65\u5C31\u62A5\u9519\u4E86\\n```\\n\\n**\u6CE8\u610F**\uFF1A`structuredClone()` \u4E5F\u4E0D\u662F\u4E07\u80FD\u7684\uFF0C\u5B83**\u65E0\u6CD5\u514B\u9686\u51FD\u6570 (Function)\u3001\u9519\u8BEF\u5BF9\u8C61 (Error) \u548C DOM \u8282\u70B9**\u3002\u4F46\u5BF9\u4E8E\u7EDD\u5927\u591A\u6570\u6570\u636E\u5BF9\u8C61\u7684\u6DF1\u62F7\u8D1D\u573A\u666F\uFF0C`structuredClone()` \u662F\u76EE\u524D\u6700\u4F18\u3001\u6700\u53EF\u9760\u7684\u9009\u62E9\u3002\\n\\n## 7. Tagged Templates (\u6807\u7B7E\u6A21\u677F)\uFF1A\u7ED9\u6A21\u677F\u5B57\u7B26\u4E32\u52A0\u4E2A\u201C\u5904\u7406\u5668\u201D\\n\\n\u6211\u4EEC\u5BF9\u6A21\u677F\u5B57\u7B26\u4E32\uFF08\u7528\u53CD\u5F15\u53F7 `` ` `` \u5305\u88F9\u7684\u5B57\u7B26\u4E32\uFF09\u5E94\u8BE5\u5F88\u719F\u6089\u4E86\uFF0C\u5B83\u5141\u8BB8\u6211\u4EEC\u65B9\u4FBF\u5730\u5D4C\u5165\u8868\u8FBE\u5F0F `${expression}`\u3002\u4F46\u4F60\u53EF\u80FD\u6CA1\u592A\u6CE8\u610F\u8FC7**\u6807\u7B7E\u6A21\u677F (Tagged Templates)**\u3002\\n\\n\u6807\u7B7E\u6A21\u677F\u5141\u8BB8\u4F60**\u7528\u4E00\u4E2A\u51FD\u6570\u6765\u201C\u89E3\u6790\u201D\u6A21\u677F\u5B57\u7B26\u4E32**\u3002\u8FD9\u4E2A\u51FD\u6570\uFF08\u79F0\u4E3A\u201C\u6807\u7B7E\u51FD\u6570\u201D\uFF09\u4F1A\u63A5\u6536\u5230\u6A21\u677F\u5B57\u7B26\u4E32\u7684\u5404\u4E2A\u90E8\u5206\u4F5C\u4E3A\u53C2\u6570\uFF0C\u7136\u540E\u4F60\u53EF\u4EE5\u5BF9\u5B83\u4EEC\u8FDB\u884C\u5904\u7406\uFF0C\u6700\u540E\u8FD4\u56DE\u5904\u7406\u540E\u7684\u7ED3\u679C\u3002\\n\\n**\u5982\u4F55\u5DE5\u4F5C\uFF1F**\\n\\n\u6807\u7B7E\u51FD\u6570\u7684\u7B2C\u4E00\u4E2A\u53C2\u6570\u662F\u4E00\u4E2A\u6570\u7EC4\uFF0C\u5305\u542B\u4E86\u6A21\u677F\u5B57\u7B26\u4E32\u4E2D\u88AB `${...}` \u5206\u9694\u5F00\u7684**\u9759\u6001\u6587\u672C\u90E8\u5206**\u3002\\n\u540E\u7EED\u7684\u53C2\u6570\u5219\u662F\u6A21\u677F\u5B57\u7B26\u4E32\u4E2D**\u6BCF\u4E2A `${...}` \u8868\u8FBE\u5F0F\u7684\u8BA1\u7B97\u7ED3\u679C**\u3002\\n\\n\u8FD9\u6709\u4EC0\u4E48\u7528\u5462\uFF1F\u5B83\u975E\u5E38\u9002\u5408\u7528\u6765\u5BF9\u6A21\u677F\u5B57\u7B26\u4E32\u8FDB\u884C**\u81EA\u52A8\u8F6C\u6362\u3001\u6821\u9A8C\u6216\u5904\u7406**\u3002\\n\\n**\u4F8B\u5982\uFF1A\u81EA\u52A8 HTML \u8F6C\u4E49**\\n\\n\u5047\u8BBE\u6211\u4EEC\u60F3\u521B\u5EFA\u4E00\u4E2A\u6807\u7B7E\u51FD\u6570 `escapeHtml`\uFF0C\u5B83\u80FD\u81EA\u52A8\u5BF9\u6A21\u677F\u5B57\u7B26\u4E32\u4E2D\u7684\u63D2\u503C\uFF08`${...}` \u91CC\u7684\u5185\u5BB9\uFF09\u8FDB\u884C HTML \u8F6C\u4E49\uFF0C\u9632\u6B62 XSS \u653B\u51FB\uFF1A\\n\\n```javascript\\nfunction escapeHtml(strings, ...values) {\\n  let output = strings[0]; // \u5148\u83B7\u53D6\u7B2C\u4E00\u4E2A\u9759\u6001\u6587\u672C\u7247\u6BB5\\n  for (let i = 0; i < values.length; i++) {\\n    // \u5BF9\u6BCF\u4E2A\u8868\u8FBE\u5F0F\u7684\u503C\u8FDB\u884C\u5904\u7406 (\u8FD9\u91CC\u662F HTML \u8F6C\u4E49)\\n    const value = values[i];\\n    const escapedValue = String(value) // \u786E\u4FDD\u662F\u5B57\u7B26\u4E32\\n      .replace(/&/g, \\"&amp;\\")\\n      .replace(/</g, \\"&lt;\\")\\n      .replace(/>/g, \\"&gt;\\")\\n      .replace(/\\"/g, \\"&quot;\\")\\n      .replace(/\'/g, \\"&#39;\\");\\n    output += escapedValue; // \u62FC\u63A5\u8F6C\u4E49\u540E\u7684\u503C\\n    output += strings[i + 1]; // \u62FC\u63A5\u4E0B\u4E00\u4E2A\u9759\u6001\u6587\u672C\u7247\u6BB5\\n  }\\n  return output;\\n}\\n\\nconst userInput = \'<script>alert(\\"xss\\")<\/script>\';\\nconst safeHtml = escapeHtml`<p>\u7528\u6237\u8F93\u5165\u5185\u5BB9\uFF1A${userInput}</p>`;\\n\\nconsole.log(safeHtml);\\n// \u8F93\u51FA: \\"<p>\u7528\u6237\u8F93\u5165\u5185\u5BB9\uFF1A&lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;</p>\\"\\n// \u7528\u6237\u8F93\u5165\u7684\u6076\u610F\u811A\u672C\u88AB\u6210\u529F\u8F6C\u4E49\u4E86\uFF01\\n```\\n\\n**\u539F\u6587\u4E2D\u7684\u4F8B\u5B50** (\u4F7F\u7528 `innerText` \u548C `innerHTML` \u6765\u8F6C\u4E49\uFF0C\u4E5F\u662F\u4E00\u79CD\u6280\u5DE7\uFF0C\u4F46\u4E0D\u5982\u76F4\u63A5\u66FF\u6362\u7279\u6B8A\u5B57\u7B26\u901A\u7528)\uFF1A\\n\\n```javascript\\n// \u539F\u6587\u793A\u4F8B\u7684\u53E6\u4E00\u79CD\u5B9E\u73B0\u601D\u8DEF\\nfunction escapeHtmlViaDOM(strings, ...args) {\\n  const div = document.createElement(\\"div\\"); // \u4EC5\u5728\u6D4F\u89C8\u5668\u73AF\u5883\u6709\u6548\\n  let output = strings[0];\\n  for (let i = 0; i < args.length; ++i) {\\n    div.innerText = args[i]; // \u5229\u7528 innerText \u7684\u81EA\u52A8\u8F6C\u4E49\u7279\u6027\\n    output += div.innerHTML; // \u8BFB\u53D6\u8F6C\u4E49\u540E\u7684 HTML\\n    output += strings[i + 1];\\n  }\\n  div.remove(); // \u6E05\u7406 DOM \u5143\u7D20\\n  return output;\\n}\\n\\nconst maliciousInput = \\"<br>\\";\\nconsole.log(escapeHtmlViaDOM`<p>Here is some code: ${maliciousInput}</p>`);\\n// \u8F93\u51FA: \\"<p>Here is some code: &lt;br&gt;</p>\\"\\n```\\n\\n\u6807\u7B7E\u6A21\u677F\u975E\u5E38\u5F3A\u5927\uFF0C\u5E38\u89C1\u5E94\u7528\u573A\u666F\u5305\u62EC\uFF1A\\n\\n- **HTML/SQL \u8F6C\u4E49**\uFF1A\u5982\u4E0A\u4F8B\u6240\u793A\uFF0C\u9632\u6B62\u6CE8\u5165\u653B\u51FB\u3002\\n- **\u56FD\u9645\u5316 (i18n)**\uFF1A\u6839\u636E\u8BED\u8A00\u73AF\u5883\u81EA\u52A8\u66FF\u6362\u5360\u4F4D\u7B26\u3002\\n- **\u6837\u5F0F\u5316\u7EC4\u4EF6 (Styled Components)**\uFF1A\u50CF React \u4E2D\u7684 styled-components \u5E93\u5C31\u91CD\u5EA6\u4F7F\u7528\u4E86\u6807\u7B7E\u6A21\u677F\u6765\u5199 CSS in JS\u3002\\n- **\u521B\u5EFA\u9886\u57DF\u7279\u5B9A\u8BED\u8A00 (DSL)**\uFF1A\u6BD4\u5982\u7528\u4E8E\u751F\u6210\u7279\u5B9A\u683C\u5F0F\u7684\u67E5\u8BE2\u8BED\u53E5\u3002\\n\\n## 8. WeakMap / WeakSet\uFF1A\u4E0D\u963B\u6B62\u5783\u573E\u56DE\u6536\u7684\u201C\u5F31\u201D\u96C6\u5408\\n\\n\u9664\u4E86\u6211\u4EEC\u5E38\u7528\u7684 `Map` \u548C `Set`\uFF0CJavaScript \u8FD8\u63D0\u4F9B\u4E86\u5B83\u4EEC\u7684\u201C\u5F31\u201D\u7248\u672C\uFF1A`WeakMap` \u548C `WeakSet`\u3002\u5B83\u4EEC\u4E0E `Map` \u548C `Set` \u7C7B\u4F3C\uFF0C\u4F46\u6709\u51E0\u4E2A\u5173\u952E\u533A\u522B\u548C\u7279\u6027\uFF1A\\n\\n1.  **\u952E\u5FC5\u987B\u662F\u5BF9\u8C61**\uFF1A`WeakMap` \u7684\u952E (key) \u548C `WeakSet` \u7684\u503C (value) **\u53EA\u80FD\u662F\u5BF9\u8C61**\uFF0C\u4E0D\u80FD\u662F\u539F\u59CB\u7C7B\u578B\u503C\uFF08\u5982 `string`, `number`, `boolean`, `symbol`, `bigint`, `null`, `undefined`\uFF09\u3002\\n2.  **\u5F31\u5F15\u7528 (Weak Reference)**\uFF1A\u8FD9\u662F\u5B83\u4EEC\u7684\u6838\u5FC3\u7279\u6027\u3002`WeakMap` \u548C `WeakSet` \u5BF9\u5176\u5B58\u50A8\u7684\u5BF9\u8C61\u952E\uFF08\u6216\u503C\uFF09\u662F**\u5F31\u5F15\u7528**\u3002\u8FD9\u610F\u5473\u7740\uFF0C\u5982\u679C\u4E00\u4E2A\u5BF9\u8C61\u53EA\u88AB `WeakMap` \u6216 `WeakSet` \u5F15\u7528\uFF0C\u800C\u6CA1\u6709\u5176\u4ED6\u4EFB\u4F55\u5F3A\u5F15\u7528\u6307\u5411\u5B83\uFF0C\u90A3\u4E48\u8FD9\u4E2A\u5BF9\u8C61\u5C31\u53EF\u4EE5\u88AB\u5783\u573E\u56DE\u6536\u673A\u5236 (Garbage Collection, GC) \u56DE\u6536\u6389\u3002\u56DE\u6536\u53D1\u751F\u65F6\uFF0C\u5BF9\u5E94\u7684\u952E\u503C\u5BF9\uFF08\u6216\u503C\uFF09\u4E5F\u4F1A\u81EA\u52A8\u4ECE `WeakMap`/`WeakSet` \u4E2D\u79FB\u9664\u3002\\n3.  **\u4E0D\u53EF\u8FED\u4EE3**\uFF1A\u6B63\u56E0\u4E3A\u5783\u573E\u56DE\u6536\u53EF\u80FD\u968F\u65F6\u79FB\u9664\u6210\u5458\uFF0C`WeakMap` \u548C `WeakSet` **\u4E0D\u652F\u6301\u8FED\u4EE3**\uFF08\u6CA1\u6709 `keys()`, `values()`, `entries()`, `forEach` \u65B9\u6CD5\uFF09\uFF0C\u4E5F\u65E0\u6CD5\u83B7\u53D6 `size` \u5C5E\u6027\u3002\u8FD9\u662F\u4E3A\u4E86\u9632\u6B62\u5728\u8FED\u4EE3\u8FC7\u7A0B\u4E2D\u6210\u5458\u7A81\u7136\u6D88\u5931\u5BFC\u81F4\u7684\u4E0D\u786E\u5B9A\u6027\u3002\\n\\n**\u4E3A\u4EC0\u4E48\u9700\u8981\u5B83\u4EEC\uFF1F**\\n\\n\u4E3B\u8981\u7528\u9014\u662F**\u5C06\u6570\u636E\u4E0E\u5BF9\u8C61\u5173\u8054\u8D77\u6765\uFF0C\u540C\u65F6\u53C8\u4E0D\u963B\u6B62\u8BE5\u5BF9\u8C61\u88AB\u5783\u573E\u56DE\u6536**\u3002\u8FD9\u5728\u67D0\u4E9B\u573A\u666F\u4E0B\u975E\u5E38\u6709\u7528\uFF0C\u53EF\u4EE5\u907F\u514D\u5185\u5B58\u6CC4\u6F0F\u3002\\n\\n**\u793A\u4F8B\uFF1A**\\n\\n```javascript\\nconst weakSet = new WeakSet();\\nconst weakMap = new WeakMap();\\n\\nlet obj1 = { id: 1 };\\nlet obj2 = { id: 2 };\\n\\nweakSet.add(obj1);\\nweakMap.set(obj2, \\"\u4E00\u4E9B\u4E0E obj2 \u5173\u8054\u7684\u6570\u636E\\");\\n\\nconsole.log(weakSet.has(obj1)); // true\\nconsole.log(weakMap.get(obj2)); // \'\u4E00\u4E9B\u4E0E obj2 \u5173\u8054\u7684\u6570\u636E\'\\n\\n// \u73B0\u5728\uFF0C\u6211\u4EEC\u79FB\u9664\u5BF9 obj1 \u548C obj2 \u7684\u6240\u6709\u5176\u4ED6\u5F3A\u5F15\u7528\\nobj1 = null;\\nobj2 = null;\\n\\n// \u5728\u5C06\u6765\u7684\u67D0\u4E2A\u65F6\u523B\uFF0C\u5783\u573E\u56DE\u6536\u673A\u5236\u8FD0\u884C\u65F6...\\n// obj1 \u548C obj2 \u56E0\u4E3A\u4E0D\u518D\u88AB\u5F3A\u5F15\u7528\uFF0C\u5B83\u4EEC\u5360\u7528\u7684\u5185\u5B58\u4F1A\u88AB\u56DE\u6536\u3002\\n// \u540C\u65F6\uFF0C\u5B83\u4EEC\u4E5F\u4F1A\u81EA\u52A8\u4ECE weakSet \u548C weakMap \u4E2D\u79FB\u9664\u3002\\n\\n// \u6CE8\u610F\uFF1A\u6211\u4EEC\u65E0\u6CD5\u76F4\u63A5\u9A8C\u8BC1\u5B83\u4EEC\u662F\u5426\u5DF2\u88AB\u79FB\u9664\uFF0C\u56E0\u4E3A WeakMap/WeakSet \u4E0D\u53EF\u8FED\u4EE3\u3002\\n// \u4F46\u6211\u4EEC\u53EF\u4EE5\u786E\u4FE1\uFF0C\u5B83\u4EEC\u4E0D\u4F1A\u963B\u6B62 obj1 \u548C obj2 \u88AB\u56DE\u6536\u3002\\n// console.log(weakSet.has(obj1)); // \u6B64\u65F6 obj1 \u5DF2\u7ECF\u662F null \u4E86\uFF0C\u67E5\u8BE2\u65E0\u610F\u4E49\\n// console.log(weakMap.get(obj2)); // \u6B64\u65F6 obj2 \u5DF2\u7ECF\u662F null \u4E86\uFF0C\u67E5\u8BE2\u65E0\u610F\u4E49\\n```\\n\\n**\u5E38\u89C1\u7528\u4F8B\uFF1A**\\n\\n- **\u7F13\u5B58\u5BF9\u8C61\u5143\u6570\u636E**\uFF1A\u4E3A\u4E00\u4E2A\u5BF9\u8C61\u5B58\u50A8\u4E00\u4E9B\u8BA1\u7B97\u6210\u672C\u8F83\u9AD8\u7684\u5143\u6570\u636E\u3002\u5F53\u5BF9\u8C61\u4E0D\u518D\u4F7F\u7528\u5E76\u88AB\u56DE\u6536\u65F6\uFF0C\u5173\u8054\u7684\u5143\u6570\u636E\u4E5F\u81EA\u52A8\u88AB\u6E05\u7406\uFF0C\u65E0\u9700\u624B\u52A8\u7BA1\u7406\u3002\\n- **\u5B58\u50A8\u79C1\u6709\u6570\u636E**\uFF1A\u5728\u7C7B\u5916\u90E8\uFF08\u6216\u6A21\u62DF\u79C1\u6709\u6210\u5458\uFF09\u4E3A\u7C7B\u7684\u5B9E\u4F8B\u5173\u8054\u4E00\u4E9B\u6570\u636E\uFF0C\u800C\u4E0D\u4F1A\u5E72\u6270\u5B9E\u4F8B\u672C\u8EAB\u7684\u751F\u547D\u5468\u671F\u3002\\n- **\u8DDF\u8E2A DOM \u8282\u70B9\u72B6\u6001**\uFF1A\u6BD4\u5982\u8BB0\u5F55\u67D0\u4E2A DOM \u5143\u7D20\u662F\u5426\u5DF2\u88AB\u5904\u7406\uFF0C\u5F53\u8BE5 DOM \u5143\u7D20\u4ECE\u6587\u6863\u4E2D\u79FB\u9664\u5E76\u88AB\u56DE\u6536\u65F6\uFF0C`WeakMap` \u4E2D\u7684\u8BB0\u5F55\u4E5F\u81EA\u52A8\u6D88\u5931\u3002\\n\\n\u5982\u679C\u4F60\u9700\u8981\u5728\u4E0D\u5F71\u54CD\u5BF9\u8C61\u751F\u547D\u5468\u671F\u7684\u60C5\u51B5\u4E0B\uFF0C\u7ED9\u5BF9\u8C61\u9644\u52A0\u4E00\u4E9B\u4FE1\u606F\uFF0C`WeakMap` \u548C `WeakSet` \u5C31\u662F\u4F60\u7684\u4E0D\u4E8C\u4E4B\u9009\u3002\\n\\n## 9. Set \u96C6\u5408\u64CD\u4F5C\uFF1A\u8F7B\u677E\u5B9E\u73B0\u4EA4\u3001\u5E76\u3001\u5DEE\u96C6\\n\\n`Set` \u5BF9\u8C61\u5B58\u50A8\u552F\u4E00\u503C\uFF0C\u672C\u8EAB\u5C31\u5F88\u6709\u7528\u3002\u6700\u8FD1\uFF0CJavaScript \u53C8\u4E3A `Set` \u589E\u52A0\u4E86\u51E0\u4E2A\u8FDB\u884C**\u96C6\u5408\u8FD0\u7B97**\u7684\u65B9\u6CD5\uFF0C\u4F7F\u5F97\u5904\u7406\u96C6\u5408\u4E4B\u95F4\u7684\u5173\u7CFB\u53D8\u5F97\u5F02\u5E38\u7B80\u5355\u548C\u9AD8\u6548\u3002\u518D\u4E5F\u4E0D\u7528\u81EA\u5DF1\u5199\u5FAA\u73AF\u548C\u5224\u65AD\u903B\u8F91\u5566\uFF01\\n\\n\u8FD9\u4E9B\u65B9\u6CD5\u90FD\u4F1A**\u8FD4\u56DE\u4E00\u4E2A\u65B0\u7684 `Set`**\uFF0C\u800C\u4E0D\u4F1A\u4FEE\u6539\u539F\u59CB\u7684 `Set`\u3002\\n\\n1.  **`set1.difference(set2)` (\u5DEE\u96C6)**: \u8FD4\u56DE\u4E00\u4E2A\u65B0 Set\uFF0C\u5305\u542B\u6240\u6709\u5728 `set1` \u4E2D\u4F46**\u4E0D\u5728** `set2` \u4E2D\u7684\u5143\u7D20\u3002\\n    ```javascript\\n    const set1 = new Set([1, 2, 3, 4]);\\n    const set2 = new Set([3, 4, 5, 6]);\\n    console.log(set1.difference(set2)); // Set(2) { 1, 2 }\\n    ```\\n2.  **`set1.intersection(set2)` (\u4EA4\u96C6)**: \u8FD4\u56DE\u4E00\u4E2A\u65B0 Set\uFF0C\u5305\u542B\u6240\u6709**\u540C\u65F6\u5B58\u5728\u4E8E** `set1` \u548C `set2` \u4E2D\u7684\u5143\u7D20\u3002\\n    ```javascript\\n    const set1 = new Set([1, 2, 3, 4]);\\n    const set2 = new Set([3, 4, 5, 6]);\\n    console.log(set1.intersection(set2)); // Set(2) { 3, 4 }\\n    ```\\n3.  **`set1.union(set2)` (\u5E76\u96C6)**: \u8FD4\u56DE\u4E00\u4E2A\u65B0 Set\uFF0C\u5305\u542B\u6240\u6709\u5728 `set1` **\u6216** `set2` \u4E2D\uFF08\u6216\u4E24\u8005\u7686\u6709\uFF09\u7684\u5143\u7D20\u3002\\n    ```javascript\\n    const set1 = new Set([1, 2, 3, 4]);\\n    const set2 = new Set([3, 4, 5, 6]);\\n    console.log(set1.union(set2)); // Set(6) { 1, 2, 3, 4, 5, 6 }\\n    ```\\n4.  **`set1.symmetricDifference(set2)` (\u5BF9\u79F0\u5DEE\u96C6)**: \u8FD4\u56DE\u4E00\u4E2A\u65B0 Set\uFF0C\u5305\u542B\u6240\u6709**\u53EA\u5B58\u5728\u4E8E** `set1` \u6216 `set2` **\u4E4B\u4E00**\u4E2D\uFF0C\u4F46**\u4E0D\u540C\u65F6\u5B58\u5728\u4E8E\u4E24\u8005**\u4E2D\u7684\u5143\u7D20\u3002\uFF08\u5373\u5E76\u96C6\u51CF\u53BB\u4EA4\u96C6\uFF09\u3002\\n    ```javascript\\n    const set1 = new Set([1, 2, 3, 4]);\\n    const set2 = new Set([3, 4, 5, 6]);\\n    console.log(set1.symmetricDifference(set2)); // Set(4) { 1, 2, 5, 6 }\\n    ```\\n5.  **`set1.isDisjointFrom(set2)` (\u662F\u5426\u4E0D\u76F8\u4EA4)**: \u8FD4\u56DE\u4E00\u4E2A\u5E03\u5C14\u503C\uFF0C\u5224\u65AD `set1` \u548C `set2` **\u662F\u5426\u6CA1\u6709**\u5171\u540C\u5143\u7D20\u3002\\n    ```javascript\\n    const set1 = new Set([1, 2, 3, 4]);\\n    const set2 = new Set([3, 4, 5, 6]);\\n    const set3 = new Set([5, 6]);\\n    console.log(set1.isDisjointFrom(set2)); // false (\u56E0\u4E3A\u6709 3, 4)\\n    console.log(set1.isDisjointFrom(set3)); // true (\u6CA1\u6709\u5171\u540C\u5143\u7D20)\\n    ```\\n6.  **`set1.isSubsetOf(set2)` (\u662F\u5426\u4E3A\u5B50\u96C6)**: \u8FD4\u56DE\u4E00\u4E2A\u5E03\u5C14\u503C\uFF0C\u5224\u65AD `set1` \u4E2D\u7684**\u6240\u6709\u5143\u7D20\u662F\u5426\u90FD\u5B58\u5728\u4E8E** `set2` \u4E2D\u3002\\n    ```javascript\\n    const set1 = new Set([1, 2]);\\n    const set2 = new Set([1, 2, 3, 4]);\\n    const set3 = new Set([3, 4]);\\n    console.log(set1.isSubsetOf(set2)); // true\\n    console.log(set3.isSubsetOf(set1)); // false\\n    ```\\n7.  **`set1.isSupersetOf(set2)` (\u662F\u5426\u4E3A\u8D85\u96C6)**: \u8FD4\u56DE\u4E00\u4E2A\u5E03\u5C14\u503C\uFF0C\u5224\u65AD `set1` **\u662F\u5426\u5305\u542B** `set2` \u4E2D\u7684\u6240\u6709\u5143\u7D20\u3002\\n    ```javascript\\n    const set1 = new Set([1, 2, 3, 4]);\\n    const set2 = new Set([1, 2]);\\n    const set3 = new Set([5, 6]);\\n    console.log(set1.isSupersetOf(set2)); // true\\n    console.log(set1.isSupersetOf(set3)); // false\\n    ```\\n\\n\u8FD9\u4E9B\u96C6\u5408\u64CD\u4F5C\u65B9\u6CD5\u6781\u5927\u5730\u7B80\u5316\u4E86\u5904\u7406\u6570\u636E\u96C6\u76F8\u5173\u7684\u903B\u8F91\uFF0C\u6BD4\u5982\u6BD4\u8F83\u7528\u6237\u6743\u9650\u3001\u7B5B\u9009\u6570\u636E\u3001\u67E5\u627E\u5DEE\u5F02\u7B49\u573A\u666F\uFF0C\u4EE3\u7801\u66F4\u6613\u8BFB\uFF0C\u6027\u80FD\u4E5F\u901A\u5E38\u4F18\u4E8E\u624B\u52A8\u5B9E\u73B0\u3002\\n\\n---\\n\\n**\u603B\u7ED3**\\n\\nJavaScript \u7684\u4E16\u754C\u65E5\u65B0\u6708\u5F02\uFF0C\u4E0D\u65AD\u6709\u65B0\u7684\u7279\u6027\u548C\u8BED\u6CD5\u7CD6\u6D8C\u73B0\uFF0C\u65E8\u5728\u8BA9\u6211\u4EEC\u5199\u51FA\u66F4\u9AD8\u6548\u3001\u66F4\u7B80\u6D01\u3001\u66F4\u5065\u58EE\u7684\u4EE3\u7801\u3002\u4ECA\u5929\u4ECB\u7ECD\u7684\u8FD9\u4E9B\u7279\u6027\uFF0C\u6709\u4E9B\u662F\u8FD1\u5E74\u7684\u65B0\u79C0\uFF08\u5982 Iterator Helpers, Set Operations\uFF09\uFF0C\u6709\u4E9B\u662F\u867D\u8001\u4F46\u53EF\u80FD\u88AB\u5FFD\u89C6\u7684\u5B9E\u7528\u6280\u5DE7\uFF08\u5982 `replace` \u56DE\u8C03, \u53D8\u91CF\u89E3\u6784\u4EA4\u6362\uFF09\u3002\\n\\n\u4F5C\u4E3A\u524D\u7AEF\u5F00\u53D1\u8005\uFF0C\u6301\u7EED\u5B66\u4E60\u3001\u62E5\u62B1\u53D8\u5316\u662F\u6211\u4EEC\u7684\u5FC5\u5907\u7D20\u517B\u3002\u5E0C\u671B\u8FD9\u7BC7\u89E3\u8BFB\u80FD\u5E2E\u52A9\u4F60\u66F4\u597D\u5730\u7406\u89E3\u548C\u8FD0\u7528\u8FD9\u4E9B JavaScript \u7279\u6027\uFF0C\u63D0\u5347\u4F60\u7684\u5F00\u53D1\u6548\u7387\u548C\u4EE3\u7801\u8D28\u91CF\uFF01\u4E0B\u6B21\u9047\u5230\u7C7B\u4F3C\u573A\u666F\uFF0C\u4E0D\u59A8\u8BD5\u8BD5\u8FD9\u4E9B\u65B0\u201C\u6B66\u5668\u201D\u5427\uFF01\uD83D\uDE80"},{"id":"/2025/04/19/require-esm-in-node-js","metadata":{"permalink":"/transblog/2025/04/19/require-esm-in-node-js","source":"@site/blog-translated/2025/04-19-require-esm-in-node-js.md","title":"require() ESM in Node.js","description":"- \u539F\u6587\u94FE\u63A5\uFF1Ahttps://joyeecheung.github.io/blog/2024/03/18/require-esm-in-node-js","date":"2025-04-19T13:00:00.000Z","tags":[{"inline":true,"label":"nodejs","permalink":"/transblog/tags/nodejs"},{"inline":true,"label":"esm","permalink":"/transblog/tags/esm"}],"readingTime":27.49,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"require() ESM in Node.js","date":"2025-04-19T13:00:00.000Z","draft":false,"tags":["nodejs","esm"]},"unlisted":false,"prevItem":{"title":"2025\u5E74\u6BCF\u4E2AJavaScript\u5F00\u53D1\u4EBA\u5458\u90FD\u5E94\u8BE5\u77E5\u9053\u7684\u4E00\u4E9B\u7279\u6027","permalink":"/transblog/2025/04/24/2025\u5E74\u6BCF\u4E2AJavaScript\u5F00\u53D1\u4EBA\u5458\u90FD\u5E94\u8BE5\u77E5\u9053\u7684\u4E00\u4E9B\u7279\u6027"},"nextItem":{"title":"TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","permalink":"/transblog/2025/04/15/TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357"}},"content":"> - \u539F\u6587\u94FE\u63A5\uFF1Ahttps://joyeecheung.github.io/blog/2024/03/18/require-esm-in-node-js\\n> - \u673A\u5668\u7FFB\u8BD1\uFF1A Gemini 2.5 Pro Preview\\n> - \u63D0\u793A\u8BCD\uFF1A \u7FFB\u8BD1\u4EE5\u4E0B\u6587\u6863\uFF0C\u5E76\u4E14\u7ED3\u5408\u4F60\u7684\u524D\u7AEF\u5F00\u53D1\u4E13\u4E1A\u77E5\u8BC6\u8865\u5145\u76F8\u5173\u7684\u77E5\u8BC6\u70B9\u8BF4\u660E\uFF0C\u5BF9\u6587\u7AE0\u5185\u5BB9\u8FDB\u884C\u7ED3\u6784\u5316\uFF0C\u4EE5 Markdown \u683C\u5F0F\u8FD4\u56DE\uFF0C\u6587\u5B57\u98CE\u683C\u662F\u6280\u672F\u535A\u5BA2\u3002\\n> - \u7FFB\u8BD1\u7406\u7531\uFF1A\u8FD9\u4E2A\u7279\u6027\u662F Node.js \u9886\u57DF\u7684\u4E00\u4E2A\u957F\u671F\u75DB\u70B9\uFF0C\u867D\u7136\u5F88\u591A\u6700\u4F73\u5B9E\u8DF5\u662F\u4E0D\u5EFA\u8BAE require esm \u7684\uFF0C\u4F46\u662F\u4E0D\u5EFA\u8BAE\u548C\u4E0D\u80FD\u662F\u4E24\u7801\u4E8B\uFF0C\u8FD9\u4E2A\u8FDB\u5C55\u8FD8\u662F\u975E\u5E38\u503C\u5F97\u671F\u5F85\u7684\u3002\u987A\u4FBF\u8BF4\u4E00\u53E5\uFF0C\u8FD9\u4E2A\u4F18\u79C0\u7684\u7279\u6027\u7684\u8D21\u732E\u503C\u662F\u4E2D\u56FD\u4EBA\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n# \u7EC8\u7ED3 `ERR_REQUIRE_ESM`\uFF1ANode.js \u8FCE\u6765\u5B9E\u9A8C\u6027 `require(esm)` \u652F\u6301\\n\\n\u5927\u5BB6\u597D\uFF01\u6700\u8FD1\uFF0C\u6211\u5728 Node.js \u4E2D\u5B9E\u73B0\u4E86\u4E00\u4E2A\u5B9E\u9A8C\u6027\u7684\u65B0\u529F\u80FD\uFF1A**\u652F\u6301\u901A\u8FC7 `require()` \u52A0\u8F7D\u540C\u6B65\u7684 ES \u6A21\u5757 (ESM)** ([PR #51977](https://github.com/nodejs/node/pull/51977))\u3002\u8FD9\u53EF\u4EE5\u8BF4\u662F Node.js \u751F\u6001\u671F\u5F85\u5DF2\u4E45\u7684\u4E00\u4E2A\u7279\u6027\u3002\u5728\u90A3\u4E2A PR \u7684\u8BC4\u8BBA\u533A\uFF0C\u6211\u7559\u4E0B\u4E86\u81EA\u5DF1\u5BF9\u4E8E\u201C\u4E3A\u4EC0\u4E48\u8FD9\u4E2A\u529F\u80FD\u76F4\u5230 2024 \u5E74\u624D\u51FA\u73B0\u201D\u7684\u7406\u89E3 ([\u8BC4\u8BBA\u94FE\u63A5](https://github.com/nodejs/node/pull/51977#issuecomment-1994837735))\u3002\u8FD9\u7BC7\u535A\u5BA2\u6587\u7AE0\u5C06\u57FA\u4E8E\u90A3\u6761\u8BC4\u8BBA\uFF0C\u505A\u66F4\u6DF1\u5165\u7684\u63A2\u8BA8\u3002\\n\\n**\u8BF7\u6CE8\u610F\uFF1A** \u672C\u6587\u8868\u8FBE\u7684\u89C2\u70B9\u4EC5\u4EE3\u8868\u6211\u4E2A\u4EBA\uFF0C\u53CD\u6620\u4E86\u6211\u4F5C\u4E3A\u4E00\u4E2A\u957F\u671F\u65C1\u89C2\u8005\u5BF9 Node.js ESM \u53D1\u5C55\u7684\u770B\u6CD5\u3002\u6211\u4E0D\u4EE3\u8868\u4EFB\u4F55\u7279\u5B9A\u56E2\u4F53\u6216 Node.js \u9879\u76EE\u672C\u8EAB\u2014\u2014Node.js \u9879\u76EE\u7684\u5B98\u65B9\u7ACB\u573A\u9700\u8981\u901A\u8FC7\u534F\u4F5C\u8005 (collaborators) \u8FBE\u6210\u5171\u8BC6\u6765\u5F62\u6210\uFF0C\u6CA1\u6709\u4EFB\u4F55\u4E2A\u4F53\u53EF\u4EE5\u5355\u72EC\u4EE3\u8868\u9879\u76EE\u53D1\u8A00\u3002\\n\\n## `ERR_REQUIRE_ESM` \u5E26\u6765\u7684\u56F0\u6270\\n\\n\u5982\u679C\u4F60\u662F Node.js \u5F00\u53D1\u8005\uFF0C\u5E76\u4E14\u66FE\u7ECF\u88AB `ERR_REQUIRE_ESM` \u8FD9\u4E2A\u9519\u8BEF\u6298\u78E8\u8FC7\uFF0C\u90A3\u4E48\u4F60\u4E00\u5B9A\u660E\u767D\u4E3A\u4EC0\u4E48\u8BA9 `require()` \u652F\u6301\u52A0\u8F7D ESM \u662F\u5982\u6B64\u91CD\u8981\u3002\u4F46\u4E3A\u4E86\u90A3\u4E9B\u53EF\u80FD\u5076\u7136\u770B\u5230\u8FD9\u7BC7\u6587\u7AE0\u7684\u975E Node.js \u7528\u6237\uFF0C\u6211\u5148\u7B80\u5355\u89E3\u91CA\u4E00\u4E0B Node.js \u4E2D ESM \u7684\u73B0\u72B6\u4EE5\u53CA\u4E3A\u4EC0\u4E48\u6211\u8BA4\u4E3A\uFF08\u4EE5\u53CA\u8BB8\u591A\u5176\u4ED6\u4EBA\u4E5F\u8BA4\u4E3A\uFF09\u8FD9\u4E2A\u65B0\u529F\u80FD\u662F\u5FC5\u8981\u7684\u3002\\n\\n### CJS \u4E0E ESM \u7684\u9E3F\u6C9F\\n\\nNode.js \u6700\u521D\u7684\u6A21\u5757\u7CFB\u7EDF\u662F CommonJS (CJS)\uFF0C\u4F7F\u7528 `require()` \u5BFC\u5165\u6A21\u5757\uFF0C`module.exports` \u5BFC\u51FA\u6A21\u5757\u3002\u540E\u6765\uFF0C\u4E3A\u4E86\u8DDF\u8FDB ECMAScript \u6807\u51C6\uFF0CNode.js \u5F15\u5165\u4E86 ES Modules (ESM)\uFF0C\u4F7F\u7528 `import` \u548C `export` \u5173\u952E\u5B57\u3002\\n\\n\u7136\u800C\uFF0C\u591A\u5E74\u4EE5\u6765\uFF0CNode.js \u7684\u5B9E\u73B0\u5B58\u5728\u4E00\u4E2A\u4E0D\u5BF9\u79F0\u6027\uFF1A\\n\\n- \u4F60\u53EF\u4EE5\u5728 ESM \u6587\u4EF6\u4E2D `import` \u4E00\u4E2A CJS \u6A21\u5757 (`import cjs`)\u3002\\n- \u4F46\u4F60**\u4E0D\u80FD**\u5728 CJS \u6587\u4EF6\u4E2D `require()` \u4E00\u4E2A ESM \u6A21\u5757 (`require(esm)`)\u3002\\n\\n\u5C1D\u8BD5\u540E\u8005\u4F1A\u76F4\u63A5\u629B\u51FA `ERR_REQUIRE_ESM` \u9519\u8BEF\u3002\\n\\n\u8FD9\u79CD\u9650\u5236\u7ED9\u5F00\u53D1\u8005\u5E26\u6765\u4E86\u5DE8\u5927\u7684\u9EBB\u70E6\uFF0C\u53EF\u4EE5\u8BF4\u662F Node.js \u751F\u6001\u7CFB\u7EDF\u4E2D\u6D6A\u8D39\u5F00\u53D1\u8005\u65F6\u95F4\u7684\u201C\u7F6A\u9B41\u7978\u9996\u201D\u4E4B\u4E00\u3002\\n\\n### \u5305\u4F5C\u8005\u7684\u56F0\u5883\u4E0E\u53CC\u6A21\u5757\u5305 (Dual Packages)\\n\\n\u5982\u679C\u4E00\u4E2A\u5E93\u7684\u4F5C\u8005\u5E0C\u671B\u4ED6\u4EEC\u7684\u5305\u65E2\u80FD\u88AB CJS \u7528\u6237\uFF08\u4F7F\u7528 `require`\uFF09\u6D88\u8D39\uFF0C\u4E5F\u80FD\u88AB ESM \u7528\u6237\uFF08\u4F7F\u7528 `import`\uFF09\u6D88\u8D39\uFF0C\u4ED6\u4EEC\u901A\u5E38\u9762\u4E34\u4E24\u79CD\u9009\u62E9\uFF1A\\n\\n1.  **\u7EE7\u7EED\u53D1\u5E03 CJS \u683C\u5F0F\uFF1A** \u8FD9\u662F\u6700\u5B89\u5168\u7684\u65B9\u5F0F\uFF0C\u4F46\u65E0\u6CD5\u5229\u7528 ESM \u7684\u4E00\u4E9B\u7279\u6027\uFF08\u5982\u9759\u6001\u5206\u6790\u3001Tree Shaking \u7B49\uFF09\u3002\\n2.  **\u53D1\u5E03\u53CC\u6A21\u5757\u5305 (Dual Package)\uFF1A** \u540C\u65F6\u63D0\u4F9B CJS \u548C ESM \u4E24\u79CD\u683C\u5F0F\u7684\u7248\u672C\u3002\u8FD9\u9700\u8981\u7CBE\u5FC3\u914D\u7F6E `package.json` \u4E2D\u7684 `exports` \u5B57\u6BB5\uFF08\u4F7F\u7528\u6761\u4EF6\u5BFC\u51FA Conditional Exports\uFF09\u6765\u544A\u8BC9 Node.js \u548C\u6253\u5305\u5DE5\u5177\u5728\u4E0D\u540C\u573A\u666F\u4E0B\u52A0\u8F7D\u54EA\u4E2A\u7248\u672C\u3002\u867D\u7136\u8FD9\u662F\u4E00\u79CD\u975E\u5E38\u666E\u904D\u7684\u505A\u6CD5\uFF0C\u4F46\u5B83\u672C\u8EAB\u4E5F\u53EF\u80FD\u5F15\u5165\u4E00\u4E9B\u590D\u6742\u7684\u95EE\u9898\uFF08\u4F8B\u5982\uFF0C[\u53CC\u91CD\u5305\u5371\u5BB3 Dual Package Hazard](https://nodejs.org/api/packages.html#dual-package-hazard)\uFF0C\u53EF\u80FD\u5BFC\u81F4\u540C\u4E00\u4E2A\u5305\u7684\u4E0D\u540C\u7248\u672C\u5B9E\u4F8B\u88AB\u540C\u65F6\u52A0\u8F7D\uFF0C\u5F15\u53D1\u72B6\u6001\u4E0D\u4E00\u81F4\u7B49\u95EE\u9898\uFF09\u3002\\n\\n> **\u77E5\u8BC6\u70B9\u8865\u5145 (Conditional Exports):**\\n>\\n> ```json\\n> // package.json\\n> {\\n>   \\"name\\": \\"my-dual-package\\",\\n>   \\"type\\": \\"module\\", // \u9ED8\u8BA4 .js \u6587\u4EF6\u662F ESM\\n>   \\"main\\": \\"./dist/index.cjs\\", // \u65E7\u7248 Node.js \u6216\u672A\u6307\u5B9A\u7C7B\u578B\u65F6\u7684\u5165\u53E3 (CJS)\\n>   \\"module\\": \\"./dist/index.js\\", // \u6253\u5305\u5DE5\u5177\uFF08\u5982 Webpack, Rollup\uFF09\u8BC6\u522B\u7684 ESM \u5165\u53E3\\n>   \\"exports\\": {\\n>     \\".\\": {\\n>       \\"import\\": \\"./dist/index.js\\", // \u5F53\u4F7F\u7528 import \u65F6\u52A0\u8F7D ESM \u7248\u672C\\n>       \\"require\\": \\"./dist/index.cjs\\" // \u5F53\u4F7F\u7528 require \u65F6\u52A0\u8F7D CJS \u7248\u672C\\n>     }\\n>   }\\n>   // ...\\n> }\\n> ```\\n>\\n> \u8FD9\u79CD\u914D\u7F6E\u8BA9\u540C\u4E00\u4E2A\u5305\u80FD\u9002\u5E94\u4E0D\u540C\u7684\u6A21\u5757\u7CFB\u7EDF\u3002\\n\\n### \u8F6C\u8BD1\u5668\u7528\u6237\u7684\u56F0\u60D1\\n\\n\u8BB8\u591A\u5F00\u53D1\u8005\u4F7F\u7528 TypeScript\u3001Babel \u7B49\u8F6C\u8BD1\u5668\u7F16\u5199\u4EE3\u7801\u3002\u4ED6\u4EEC\u53EF\u80FD\u5728\u4EE3\u7801\u4E2D\u5B8C\u5168\u4F7F\u7528 ESM \u8BED\u6CD5 (`import`/`export`)\u3002\u7136\u800C\uFF0C\u5F88\u591A\u65F6\u5019\uFF0C\u8FD9\u4E9B\u8F6C\u8BD1\u5668\u7684\u9ED8\u8BA4\u914D\u7F6E\uFF08\u6216\u8005\u4E3A\u4E86\u6700\u5927\u5316\u517C\u5BB9\u6027\uFF09\u4F1A\u5C06\u4EE3\u7801\u6700\u7EC8\u7F16\u8BD1\u6210 CJS \u683C\u5F0F\u3002\\n\\n\u8FD9\u610F\u5473\u7740\uFF0C\u5F00\u53D1\u8005\u5199\u7684\u867D\u7136\u662F ESM \u98CE\u683C\u7684\u4EE3\u7801\uFF0C\u4F46\u5728 Node.js \u4E2D\u5B9E\u9645\u8FD0\u884C\u7684\u53EF\u80FD\u662F CJS \u4EE3\u7801\u3002\u5F53\u8FD9\u6BB5 (\u4F2A\u88C5\u6210 CJS \u7684) \u4EE3\u7801\u5C1D\u8BD5 `require()` \u4E00\u4E2A _\u771F\u6B63_ \u7684\u7B2C\u4E09\u65B9 ESM \u5305\u65F6\uFF0C`ERR_REQUIRE_ESM` \u9519\u8BEF\u5C31\u4F1A\u51FA\u73B0\u3002\u8FD9\u4F1A\u8BA9\u5F00\u53D1\u8005\u975E\u5E38\u56F0\u60D1\uFF0C\u56E0\u4E3A\u4ED6\u4EEC\u53EF\u80FD\u4E00\u76F4\u4EE5\u4E3A\u81EA\u5DF1\u7684\u4EE3\u7801\u5C31\u662F\u4EE5 ESM \u65B9\u5F0F\u8FD0\u884C\u7684\u3002\\n\\n## \u5173\u4E8E ESM \u540C\u6B65\u6027\u7684\u8FF7\u601D\\n\\n\u5F88\u81EA\u7136\u5730\uFF0C\u4EBA\u4EEC\u4F1A\u95EE\uFF1A\u4E3A\u4EC0\u4E48 `require()` \u5C31\u4E0D\u80FD\u76F4\u63A5\u652F\u6301\u52A0\u8F7D ESM \u5462\uFF1F\\n\\n\u5728\u5F88\u957F\u4E00\u6BB5\u65F6\u95F4\u91CC\uFF0CNode.js \u9879\u76EE\u7ED9\u51FA\u7684\u7B54\u6848\uFF08\u5F15\u7528\u6211\u63D0\u4EA4 PR \u524D\u7684\u5B98\u65B9\u6587\u6863\uFF09\u5927\u81F4\u662F\u8FD9\u6837\u7684\uFF1A\\n\\n> \u4E0D\u652F\u6301\u4F7F\u7528 require \u52A0\u8F7D ES \u6A21\u5757\uFF0C\u56E0\u4E3A ES \u6A21\u5757\u5177\u6709\u5F02\u6B65\u6267\u884C\u7279\u6027 (asynchronous execution)\u3002\\n\\n\u8FD9\u4E2A\u8BF4\u6CD5\u5728\u5404\u79CD\u534A\u5B98\u65B9\u7684\u6C9F\u901A\u4E2D\u4E5F\u53CD\u590D\u51FA\u73B0\uFF0C\u5E76\u4E14\u603B\u662F\u4EE5\u4E00\u79CD\u975E\u5E38\u80AF\u5B9A\u7684\u8BED\u6C14\u3002\u56E0\u6B64\uFF0C\u5373\u4F7F\u6211\u4F5C\u4E3A\u4E00\u540D\u957F\u671F\u7684 Node.js \u8D21\u732E\u8005\uFF0C\u4E5F\u4E00\u76F4\u76F8\u4FE1\u8FD9\u4E2A\u8BF4\u6CD5\u2014\u2014\u6BD5\u7ADF ESM \u548C Node.js \u7684\u7528\u6237\u6A21\u5757\u52A0\u8F7D\u5668\u5E76\u975E\u6211\u6240\u64C5\u957F\u7684\u9886\u57DF\u3002\u5BF9\u4E8E\u4E0D\u719F\u6089\u7684\u7EC4\u4EF6\uFF0C\u6211\u81EA\u7136\u4F1A\u50CF\u5176\u4ED6\u4EBA\u4E00\u6837\uFF0C\u76F8\u4FE1\u5B98\u65B9\u6587\u6863\u7684\u8BF4\u6CD5\u3002\\n\\n### \u771F\u76F8\uFF1AESM \u53EA\u662F _\u6709\u6761\u4EF6\u5730_ \u5F02\u6B65\\n\\n\u7136\u800C\uFF0C\u8FD9\u6B63\u662F\u6587\u6863\u548C\u5176\u4ED6\u6C9F\u901A\u6E20\u9053\u5B58\u5728\u8BEF\u5BFC\u7684\u5730\u65B9\u3002\u6216\u8BB8\u4ED6\u4EEC\u63CF\u8FF0\u7684\u53EA\u662F Node.js _\u5F53\u65F6_ \u7684 ESM \u5B9E\u73B0\u884C\u4E3A\uFF0C\u800C\u975E ESM \u6807\u51C6\u672C\u8EAB\u7684\u8BBE\u8BA1\u3002\\n\\n\u53BB\u5E74\uFF0C\u5F53\u6211\u5728\u4FEE\u590D Node.js `vm` API \u7684\u5185\u5B58\u6CC4\u6F0F\u95EE\u9898 ([\u535A\u5BA2\u6587\u7AE0\u94FE\u63A5](https://joyeecheung.github.io/blog/2023/12/30/fixing-nodejs-vm-apis-2/)) \u65F6\uFF0C\u5076\u7136\u6D4F\u89C8\u4E86 V8 \u5F15\u64CE\u7684\u6E90\u7801 ([\u94FE\u63A5](https://chromium.googlesource.com/v8/v8/+/7276abbe09fbe4d7ecff3ea48b3e8bcaae677d2d/src/objects/source-text-module.cc#712))\u3002\u6211\u60CA\u8BB6\u5730\u53D1\u73B0\uFF0C**ESM \u672C\u8EAB\u5E76\u975E\u88AB\u8BBE\u8BA1\u6210\u65E0\u6761\u4EF6\u5F02\u6B65\u7684**\u3002\\n\\n\u6839\u636E ECMAScript \u89C4\u8303 ([\u94FE\u63A5](https://tc39.es/ecma262/#sec-moduleevaluation))\uFF0CESM \u7684\u6267\u884C (evaluation) \u9636\u6BB5**\u53EA\u6709\u5728\u6A21\u5757\u4F9D\u8D56\u56FE\u4E2D\u5305\u542B\u9876\u5C42 `await` (Top-Level `await`, TLA) \u65F6\uFF0C\u624D\u662F\u5F02\u6B65\u7684** ([\u94FE\u63A5](https://tc39.es/ecma262/#sec-source-text-module-record-execute-module))\u3002\\n\\n> **\u77E5\u8BC6\u70B9\u8865\u5145 (Top-Level `await` - TLA):**\\n>\\n> TLA \u5141\u8BB8\u4F60\u5728\u6A21\u5757\u7684\u9876\u5C42\u4F5C\u7528\u57DF\u76F4\u63A5\u4F7F\u7528 `await` \u5173\u952E\u5B57\uFF0C\u800C\u65E0\u9700\u5C06\u5176\u5305\u88F9\u5728 `async` \u51FD\u6570\u4E2D\u3002\\n>\\n> ```javascript\\n> // data-fetcher.js (ESM)\\n> const response = await fetch(\\"/api/data\\"); // Top-level await\\n> export const data = await response.json();\\n>\\n> // main.js (ESM)\\n> import { data } from \\"./data-fetcher.js\\"; // \u8FD9\u4E2A import \u4F1A\u7B49\u5F85 data-fetcher.js \u4E2D\u7684 await \u5B8C\u6210\\n> console.log(data);\\n> ```\\n>\\n> \u5F53\u4E00\u4E2A\u6A21\u5757\u4F9D\u8D56\u56FE\u4E2D\u4EFB\u4F55\u4E00\u4E2A\u6A21\u5757\u4F7F\u7528\u4E86 TLA\uFF0C\u6574\u4E2A\u56FE\u7684\u6267\u884C\u5C31\u53D8\u6210\u4E86\u5F02\u6B65\u8FC7\u7A0B\u3002\u5982\u679C\u6CA1\u6709\u4EFB\u4F55 TLA\uFF0C\u6574\u4E2A\u56FE\u7684\u6267\u884C\u53EF\u4EE5\u662F\u540C\u6B65\u5B8C\u6210\u7684\u3002\\n\\n### \u540C\u6B65 `require(esm)` \u7684\u53EF\u80FD\u6027\\n\\n\u65E2\u7136 ESM \u53EA\u6709\u5728\u5305\u542B TLA \u65F6\u624D\u662F\u5F02\u6B65\u7684\uFF0C\u90A3\u4E48\u8BA9 `require()` \u81F3\u5C11\u652F\u6301\u52A0\u8F7D**\u4E0D\u5305\u542B TLA \u7684 ESM \u6A21\u5757\u56FE**\uFF0C\u4F3C\u4E4E\u5C31\u53D8\u5F97\u975E\u5E38\u81EA\u7136\u4E86\u3002\\n\\n\u867D\u7136\u67D0\u4E9B\u5E93\u53EF\u80FD\u6709\u4F7F\u7528 TLA \u7684\u5408\u7406\u7406\u7531\uFF08\u4F8B\u5982\uFF0C\u5728\u6A21\u5757\u52A0\u8F7D\u65F6\u8FDB\u884C\u5F02\u6B65\u521D\u59CB\u5316\uFF09\uFF0C\u4F46\u8FD9\u53EF\u80FD\u5E76\u4E0D\u662F\u975E\u5E38\u666E\u904D\u7684\u60C5\u51B5\u3002\u4E8B\u5B9E\u4E0A\uFF0C\u5728\u6211\u540E\u6765\u6D4B\u8BD5\u6211\u7684 `require(esm)` PR \u65F6\uFF0C\u5728 npm \u4E0A\u627E\u4E86\u5927\u7EA6 30 \u4E2A\u9AD8\u5F71\u54CD\u529B\u7684\u7EAF ESM \u5305\uFF0C\u6CA1\u6709\u4E00\u4E2A\u5305\u542B TLA\u3002\\n\\n\u56E0\u6B64\uFF0C\u4EC5\u4EC5\u652F\u6301\u5728 `require()` \u4E2D\u52A0\u8F7D\u540C\u6B65\u7684 ESM \u6A21\u5757\uFF0C\u53EF\u80FD\u5C31\u5DF2\u7ECF\u8DB3\u4EE5\u89E3\u51B3\u751F\u6001\u7CFB\u7EDF\u4E2D\u8BB8\u591A\u4EE4\u4EBA\u5934\u75BC\u7684\u95EE\u9898\u4E86\u3002\\n\\n\u4F46 ESM \u6807\u51C6\u8FD9\u6837\u8BBE\u8BA1\u5DF2\u7ECF\u5F88\u4E45\u4E86\uFF0C\u80AF\u5B9A\u6709\u5176\u4ED6\u4EBA\u6BD4\u6211\u66F4\u65E9\u610F\u8BC6\u5230\u8FD9\u4E00\u70B9\u5427\uFF1F\u662F\u7684\uFF0C\u5F53\u7136\u6709\u3002\\n\\n## 2019 \u5E74\u7684\u5C1D\u8BD5\uFF1A\u540C\u6B65 `require(esm)` \u7684\u63D0\u51FA\u4E0E\u6401\u6D45\\n\\n\u8BA9 `require()` \u652F\u6301\u540C\u6B65 ESM \u56FE\u7684\u60F3\u6CD5\u5E76\u975E\u5168\u65B0\u3002\u6211\u540E\u6765\u53D1\u73B0\uFF0C\u8FD9\u4E2A\u60F3\u6CD5\u5728 2019 \u5E74\u7684\u4E00\u4E2A PR ([#30891](https://github.com/nodejs/node/pull/30891)) \u4E2D\u5C31\u5DF2\u7ECF\u88AB\u63D0\u51FA\u6765\u4E86\uFF0C\u90A3\u4E2A PR \u5C1D\u8BD5\u6DFB\u52A0\u5BF9 `require()` \u52A0\u8F7D `.mjs` \u6587\u4EF6\uFF08Node.js \u4E2D\u660E\u786E\u8868\u793A ESM \u7684\u6587\u4EF6\u6269\u5C55\u540D\uFF09\u7684\u652F\u6301\u3002\\n\\n\u7136\u800C\uFF0C\u90A3\u4E2A PR \u8BD5\u56FE\u901A\u8FC7\u5728\u52A0\u8F7D\u5668\u4E2D\u201C\u7A7A\u8F6C\u201D\u4E8B\u4EF6\u5FAA\u73AF (spin the event loop) \u6765\u5904\u7406 TLA\uFF0C\u8FD9\u79CD\u65B9\u5F0F\u88AB\u8BA4\u4E3A\u662F\u4E0D\u5B89\u5168\u7684\uFF0C\u6700\u7EC8\u5BFC\u81F4 PR \u88AB\u5173\u95ED\u3002\u867D\u7136\u5F53\u65F6\u6709\u4EBA\u63D0\u5230\u4E86\u201C\u53EA\u652F\u6301\u540C\u6B65\u56FE\uFF0C\u4E0D\u7A7A\u8F6C\u4E8B\u4EF6\u5FAA\u73AF\u201D\u7684\u60F3\u6CD5 ([\u8BC4\u8BBA\u94FE\u63A5](https://github.com/nodejs/node/pull/30891#issuecomment-565604651))\uFF0C\u4F46\u90A3\u4E2A PR \u4F3C\u4E4E\u504F\u79BB\u4E86\u65B9\u5411\uFF0C\u6700\u7EC8\u6CA1\u6709\u671D\u7740\u8FD9\u4E2A\u76EE\u6807\u53D1\u5C55\u3002\\n\\n\u6B64\u540E\uFF0C\u81F3\u5C11\u5728\u6211\u80FD\u627E\u5230\u7684\u516C\u5F00 PR \u4E2D\uFF0C\u518D\u6CA1\u6709\u51FA\u73B0\u8FC7\u5B9E\u73B0\u540C\u6B65 `require(esm)` \u7684\u5C1D\u8BD5\u4E86\uFF08\u540E\u6765\u6709\u4E00\u4E9B\u5176\u4ED6\u7684 `require(esm)` \u5C1D\u8BD5\uFF0C\u4F46\u5B83\u4EEC\u4ECD\u7136\u57FA\u4E8E\u201CESM \u662F\u65E0\u6761\u4EF6\u5F02\u6B65\u201D\u7684\u5047\u8BBE\uFF09\u3002\\n\\n### \u6807\u51C6\u5DF2\u77E5\uFF0CNode.js \u672A\u77E5\uFF1F\\n\\n\u5728\u89C4\u8303\u5C42\u9762\uFF0C\u57FA\u4E8E\u8BED\u6CD5\u7684 ESM \u540C\u6B65\u6267\u884C\u7406\u8BBA\u57FA\u7840\u65E9\u5728 2019 \u5E74\u5C31\u5DF2\u7ECF\u786E\u7ACB ([TC39 TLA \u63D0\u6848 PR #61](https://github.com/tc39/proposal-top-level-await/pull/61))\u3002\u540E\u6765\u6211\u4E0E\uFF08\u975E Node.js \u9879\u76EE\u7684\uFF09\u4ECE\u4E8B ESM \u76F8\u5173\u5DE5\u4F5C\u7684\u4EBA\u4EA4\u6D41\u65F6\uFF0C\u53D1\u73B0\u8FD9\u4F3C\u4E4E\u662F\u4ED6\u4EEC\u7684\u5171\u8BC6\u3002\\n\\n\u770B\u8D77\u6765\uFF0C\u968F\u7740\u65F6\u95F4\u7684\u63A8\u79FB\uFF0CNode.js \u5185\u90E8\u9010\u6E10\u5F62\u6210\u4E86\u4E00\u4E2A\u8FF7\u601D\uFF1A\u201CESM \u662F\u5F02\u6B65\u7684\uFF0CCJS \u662F\u540C\u6B65\u7684\uFF0C\u6240\u4EE5 CJS \u4E0D\u80FD\u52A0\u8F7D ESM\u201D\u3002\u4E0E\u6B64\u540C\u65F6\uFF0C\u5728\u6807\u51C6\u7EC4\u7EC7\uFF08\u5982 TC39 \u548C W3C\uFF09\u90A3\u8FB9\uFF0CES \u89C4\u8303\u7279\u522B\u6CE8\u610F\u786E\u4FDD ESM \u53EA\u662F*\u6709\u6761\u4EF6\u5730*\u5F02\u6B65\uFF0CW3C \u89C4\u8303\u751A\u81F3\u5229\u7528\u8FD9\u4E00\u70B9\u6765\u786E\u4FDD Service Workers \u53EA\u5141\u8BB8\u540C\u6B65\u7684\u6A21\u5757\u8BC4\u4F30 ([W3C ServiceWorker Issue #1407](https://github.com/w3c/ServiceWorker/issues/1407))\u3002\\n\\n\u5982\u679C\u89C4\u8303\u4E2D\u57FA\u4E8E\u8BED\u6CD5\u7684\u540C\u6B65\u6027\u88AB\u66F4\u5E7F\u6CDB\u5730\u4E86\u89E3\uFF0C\u90A3\u4E48\u5728 2019 \u5E74\u4E4B\u540E\u5F88\u53EF\u80FD\u4F1A\u6709\u66F4\u591A\u4EBA\u5C1D\u8BD5\u5B9E\u73B0\u540C\u6B65 `require(esm)`\uFF0C\u5B98\u65B9\u6587\u6863\u4E5F\u4E0D\u4F1A\u518D\u7528\u90A3\u79CD\u201C\u65E0\u6761\u4EF6\u5F02\u6B65\u201D\u7684\u53E3\u543B\u6765\u63CF\u8FF0 ESM \u4E86\u3002\\n\\n\u90A3\u4E48\uFF0C\u4E3A\u4EC0\u4E48\u8FD9\u4E2A\u76F8\u5BF9\u91CD\u8981\u7684\u4FE1\u606F\u5728 Node.js \u5185\u90E8\uFF08\u7279\u522B\u662F\u90A3\u4E9B\u4E0D\u76F4\u63A5\u53C2\u4E0E ESM \u5B9E\u73B0\u7684\u4EBA\u4E2D\uFF09\u5374\u9C9C\u4E3A\u4EBA\u77E5\u5462\uFF1F\\n\\n## ESM \u7684\u201C\u4FE1\u606F\u5B64\u5C9B\u201D (The ESM Silo)\\n\\n> **\u77E5\u8BC6\u70B9\u8865\u5145 (\u4FE1\u606F\u5B64\u5C9B - Information Silo):**\\n>\\n> \u6307\u5728\u4E00\u4E2A\u7EC4\u7EC7\u5185\u90E8\uFF0C\u4E0D\u540C\u90E8\u95E8\u3001\u56E2\u961F\u6216\u4E2A\u4F53\u4E4B\u95F4\u7F3A\u4E4F\u6709\u6548\u7684\u4FE1\u606F\u6C9F\u901A\u548C\u5171\u4EAB\uFF0C\u5BFC\u81F4\u4FE1\u606F\u88AB\u9650\u5236\u5728\u5C40\u90E8\u8303\u56F4\u5185\uFF0C\u65E0\u6CD5\u6D41\u901A\u548C\u6574\u5408\u7684\u73B0\u8C61\u3002\u8FD9\u4F1A\u963B\u788D\u534F\u4F5C\u3001\u51B3\u7B56\u548C\u521B\u65B0\u3002\\n\\n\u5728\u6DF1\u5165\u601D\u8003\u540E\uFF0C\u6211\u8BA4\u4E3A ESM \u7684\u540C\u6B65\u6027\u4E4B\u6240\u4EE5\u6CA1\u6709\u66F4\u65E9\u5730\u5728 Node.js \u4E2D\u50AC\u751F\u51FA\u540C\u6B65 `require(esm)`\uFF0C**\u6587\u5316\u539F\u56E0\u53EF\u80FD\u5927\u4E8E\u6280\u672F\u539F\u56E0**\u3002\u5728 Node.js \u5185\u90E8\uFF0C\u8D1F\u8D23 ESM \u5B9E\u73B0\u3001\u4E0E\u6807\u51C6\u7EC4\u7EC7\u6C9F\u901A\u7684\u4EBA\u548C\u4E0D\u53C2\u4E0E\u8FD9\u4E9B\u5DE5\u4F5C\u7684\u4EBA\u4E4B\u95F4\uFF0C\u4F3C\u4E4E\u5B58\u5728\u4E00\u4E2A\u201C\u4FE1\u606F\u5B64\u5C9B\u201D\u95EE\u9898\u3002\\n\\n### Node.js \u7684\u51B3\u7B56\u6D41\u7A0B\u4E0E ESM \u7684\u7279\u6B8A\u6027\\n\\n\u901A\u5E38\uFF0CNode.js \u7684\u5927\u90E8\u5206\u51B3\u7B56\u662F\u901A\u8FC7 100 \u591A\u540D\u534F\u4F5C\u8005 (collaborators) \u8FBE\u6210\u5171\u8BC6\u6765\u5B8C\u6210\u7684\u3002\u8FD9\u4E9B\u534F\u4F5C\u8005\u662F\u901A\u8FC7\u5BF9\u9879\u76EE\u7684\u8D21\u732E\u83B7\u5F97\u63D0\u540D\u5E76\u62E5\u6709\u63D0\u4EA4\u6743\u9650\u7684\u4EBA\u3002\u5F53\u534F\u4F5C\u8005\u4E4B\u95F4\u65E0\u6CD5\u8FBE\u6210\u5171\u8BC6\u65F6\uFF0C\u51B3\u7B56\u4F1A\u63D0\u4EA4\u7ED9 Node.js \u6280\u672F\u6307\u5BFC\u59D4\u5458\u4F1A (TSC)\u3002TSC \u662F\u7531\u66F4\u6D3B\u8DC3\u7684 Node.js \u534F\u4F5C\u8005\u7EC4\u6210\u7684\u5C0F\u7EC4\uFF0C\u53EF\u4EE5\u901A\u8FC7\u7B80\u5355\u591A\u6570\u6295\u7968\u6765\u505A\u51FA\u51B3\u7B56\u3002\\n\\n\u7136\u800C\uFF0CNode.js \u4E2D ESM \u7684\u65E9\u671F\u5F00\u53D1\u91C7\u7528\u4E86\u4E0D\u540C\u7684\u6D41\u7A0B\u3002ESM \u7684\u5B9E\u73B0\u548C\u51B3\u7B56\u88AB\u59D4\u6258\u7ED9\u4E86\u201C\u6A21\u5757\u56E2\u961F (modules group)\u201D\u3002\u8FD9\u4E2A\u56E2\u961F\u4E0D\u4EC5\u5305\u62EC Node.js \u534F\u4F5C\u8005\uFF0C\u8FD8\u5305\u62EC\u793E\u533A\u6210\u5458\uFF08\u5982\u5305\u4F5C\u8005\u3001\u6807\u51C6\u7EC4\u7EC7\u53C2\u4E0E\u8005\u548C\u5176\u4ED6\u5229\u76CA\u76F8\u5173\u8005\uFF09\u3002\u5728 ESM \u51B3\u7B56\u65B9\u9762\uFF0CNode.js TSC \u5927\u591A\u53EA\u662F\u5BF9\u6A21\u5757\u56E2\u961F\u8FBE\u6210\u7684\u5171\u8BC6\u8FDB\u884C\u4F8B\u884C\u6279\u51C6 (rubber stamp)\u3002\\n\\n### \u6C9F\u901A\u58C1\u5792\u4E0E\u77E5\u8BC6\u9694\u9602\\n\\n\u7531\u4E8E\u8BAE\u9898\u672C\u8EAB\u7684\u7279\u6027\uFF0C\u6A21\u5757\u56E2\u961F\u7684\u8BA8\u8BBA\u5F80\u5F80\u975E\u5E38\u6FC0\u70C8\u3002\u867D\u7136\u56E2\u961F\u7684\u6784\u6210\u65E8\u5728\u8BA9\u51B3\u7B56\u66F4\u5177\u5305\u5BB9\u6027\uFF0C\u4F46\u8FD9\u79CD\u5206\u79BB\u7684\u8BBE\u7F6E\u548C\u6FC0\u70C8\u7684\u8BA8\u8BBA\uFF0C\u4F7F\u5F97\u56E2\u961F\u4E4B\u5916\u7684\u534F\u4F5C\u8005\uFF08\u5305\u62EC TSC \u6210\u5458\uFF09\u5F88\u96BE\u8DDF\u4E0A\u8FDB\u5EA6\u6216\u53C2\u4E0E\u5176\u4E2D\u3002\u6211\u81EA\u5DF1\u5728\u5F53\u65F6\u4E5F\u786E\u5B9E\u5C3D\u91CF\u907F\u5F00 Node.js \u7684 ESM \u76F8\u5173\u4E8B\u52A1\u2014\u2014\u770B\u8D77\u6765\u4ED6\u4EEC\u5DF2\u7ECF\u6709\u8DB3\u591F\u591A\u7684\u610F\u89C1\u4E86\u3002\\n\\n\u7ED3\u679C\u5C31\u662F\u5F62\u6210\u4E86\u4FE1\u606F\u5B64\u5C9B\u3002\u5982\u679C\u4E00\u573A\u8FA9\u8BBA\u4ECE\u672A\u5347\u7EA7\u5230\u6A21\u5757\u56E2\u961F\u4E4B\u5916\uFF0C\u5B83\u5C31\u53EF\u80FD\u6210\u4E3A Node.js \u5185\u90E8\u7814\u7A76 ESM \u7684\u90A3\u4E00\u5C0F\u90E8\u5206\u4EBA\uFF0C\u751A\u81F3\u53EA\u662F\u53C2\u4E0E\u4E86\u90A3\u573A\u7279\u5B9A\u8FA9\u8BBA\u7684\u4EBA\u624D\u4E86\u89E3\u7684\u201C\u5C0F\u4F17\u77E5\u8BC6\u201D\u3002\u6211\u8BA4\u4E3A\u5173\u4E8E\u540C\u6B65 `require(esm)` \u7684\u8FA9\u8BBA\u5C31\u662F\u8FD9\u79CD\u60C5\u51B5\u3002\u81F3\u5C11\u636E\u6211\u8BB0\u5FC6\uFF0C\u5173\u4E8E\u540C\u6B65 `require(esm)` \u7684\u8FA9\u8BBA\u4ECE\u672A\u88AB\u63D0\u4EA4\u7ED9 TSC\u3002\u53C2\u4E0E\u8FA9\u8BBA\u7684\u4EBA\u65E0\u6CD5\u8FBE\u6210\u5171\u8BC6\uFF0C\u8FD9\u4E2A\u95EE\u9898\u5C31\u5728\u4E86\u89E3\u5B83\u7684\u4EBA\u4E2D\u95F4\u9010\u6E10\u6C89\u5BC2\u4E86\uFF0C\u800C\u5176\u4ED6\u4EBA\u5219\u5F00\u59CB\u5047\u8BBE\u8FD9\u662F\u4E0D\u53EF\u80FD\u5B9E\u73B0\u7684\u3002\\n\\n### \u8D21\u732E\u8005\u7684\u95E8\u69DB\\n\\n\u53E6\u4E00\u4E2A\u5BFC\u81F4\u540C\u6B65 `require(esm)` \u5EF6\u8FDF\u7684\u56E0\u7D20\u662F\uFF0C\u5BF9 Node.js ESM \u52A0\u8F7D\u5668\u7684\u66F4\u6539\u5F80\u5F80\u6BD4\u5BF9\u5176\u4ED6\u4EFB\u4F55\u7CFB\u7EDF\u90FD\u66F4\u5BB9\u6613\u5F15\u53D1\u4E89\u8BBA\uFF0C\u8FD9\u53EF\u80FD\u4F1A\u8BA9\u8D21\u732E\u8005\u671B\u800C\u5374\u6B65\u3002\u6211\u4E3A Node.js \u8D21\u732E\u4E86 7 \u5E74\uFF0C\u4F46\u5728\u53BB\u5E74\u4E4B\u524D\u5F88\u5C11\u63A5\u89E6 ESM \u52A0\u8F7D\u5668\u2014\u2014\u53BB\u5E74\u6211\u4E3B\u8981\u662F\u5728\u4FEE\u590D\u4E00\u4E9B\u6CA1\u6709\u4E89\u8BAE\u7684 bug \u6216\u5185\u5B58\u6CC4\u6F0F\uFF0C\u800C\u4E0D\u662F\u6539\u53D8 ESM \u5728 Node.js \u4E2D\u201C\u5E94\u8BE5\u201D\u5982\u4F55\u5DE5\u4F5C\uFF0C\u540E\u8005\u5F80\u5F80\u5145\u6EE1\u4E89\u8BAE\u3002\\n\\n\u8FD9\u53EF\u80FD\u4E5F\u963B\u6B62\u4E86\u66F4\u591A\u4EBA\u53BB\u7814\u7A76\u52A0\u8F7D\u5668\u5E76\u66F4\u65E9\u5730\u5B9E\u73B0 `require(esm)`\u3002\u81F3\u5C11\uFF0C\u5F53\u6211\u5728\u53BB\u5E74\u5F00\u59CB\u7814\u7A76 `require(esm)` \u65F6\uFF0C\u6211\u786E\u5B9E\u4E0D\u60F3\u8FC7\u65E9\u58F0\u5F20\uFF0C\u4EE5\u907F\u514D\u5728\u53D6\u5F97\u4EFB\u4F55\u6280\u672F\u8FDB\u5C55\u4E4B\u524D\u5C31\u5377\u5165\u4E0D\u5FC5\u8981\u7684\u8FA9\u8BBA\u3002\\n\\n## ESM \u52A0\u8F7D\u5668\u7684\u6280\u672F\u590D\u6742\u6027\\n\\n\u867D\u7136\u6211\u8BA4\u4E3A\u540C\u6B65 `require(esm)` \u672A\u80FD\u65E9\u65E5\u5B9E\u73B0\u4E3B\u8981\u662F\u6587\u5316\u539F\u56E0\uFF0C\u4F46\u4E00\u4E9B\u8F83\u5C0F\u7684\u6280\u672F\u56E0\u7D20\u53EF\u80FD\u4E5F\u8D77\u5230\u4E86\u63A8\u6CE2\u52A9\u6F9C\u7684\u4F5C\u7528\u3002\\n\\n### \u590D\u6742\u4E14\u201C\u6709\u673A\u751F\u957F\u201D\u7684\u4EE3\u7801\u5E93\\n\\n\u53D1\u5C55\u81F3\u4ECA\uFF0CNode.js \u7684 ESM \u52A0\u8F7D\u5668\u672C\u8EAB\u5DF2\u7ECF\u76F8\u5F53\u5E9E\u5927\u548C\u590D\u6742\u3002\u5F53\u6211\u521A\u5F00\u59CB\u4E3A Node.js \u505A\u8D21\u732E\u65F6\uFF0C\u6211\u89C9\u5F97 CJS \u52A0\u8F7D\u5668\u5C31\u5DF2\u7ECF\u5F88\u96BE\u7406\u89E3\u4E86\u2014\u2014\u90A3\u8FD8\u662F\u5728 Node.js \u6709 ESM \u52A0\u8F7D\u5668\u4E4B\u524D\u3002\u51E0\u5E74\u540E\uFF0C\u5F53\u6211\u4FEE\u590D\u7531 ESM \u96C6\u6210\u5F15\u8D77\u7684 `vm` API \u5185\u5B58\u6CC4\u6F0F\u65F6 ([\u4E4B\u524D\u7684\u535A\u5BA2\u6587\u7AE0](https://joyeecheung.github.io/blog/2023/12/30/fixing-nodejs-vm-apis-3/))\uFF0C\u6211\u7B2C\u4E00\u6B21\u4E0D\u5F97\u4E0D\u6DF1\u5165\u7814\u7A76 Node.js \u7684 ESM \u52A0\u8F7D\u5668\u3002\u6211\u60CA\u8BB6\u5730\u53D1\u73B0\uFF0CESM \u52A0\u8F7D\u5668\u6BD4 CJS \u52A0\u8F7D\u5668\u8FD8\u8981\u590D\u6742\u5F97\u591A\uFF08\u4EE3\u7801\u91CF\u51E0\u4E4E\u662F\u540E\u8005\u7684 3 \u500D\uFF09\u3002\u8FD9\u53EF\u80FD\u662F\u52A0\u8F7D\u5668\u591A\u5E74\u6765\u201C\u6709\u673A\u751F\u957F\u201D\u7684\u7ED3\u679C\uFF0C\u770B\u8D77\u6765\u786E\u5B9E\u9700\u8981\u4E00\u4E9B\u6E05\u7406\u5DE5\u4F5C\u3002\\n\\n### JavaScript \u5B9E\u73B0\u6838\u5FC3\u7684\u6311\u6218\\n\\nESM \u52A0\u8F7D\u5668\u4E3B\u8981\u7528 JavaScript \u5B9E\u73B0\u3002\u867D\u7136\u6211\u8BA4\u4E3A JavaScript \u5728\u5B9E\u73B0\u67D0\u4E9B API\uFF08\u5982 Streams\uFF09\u65F6\u6709\u5176\u4F18\u52BF\uFF0C\u4F46\u5F53\u4F60\u5C1D\u8BD5\u7528\u5B83\u6765\u5B9E\u73B0 JavaScript \u8FD0\u884C\u65F6\u81EA\u8EAB\u7684\u6838\u5FC3\u90E8\u5206\uFF08\u6BD4\u5982 ESM \u52A0\u8F7D\u5668\uFF09\u65F6\uFF0C\u8FD9\u53EF\u80FD\u4F1A\u9002\u5F97\u5176\u53CD\u3002\\n\\n- **\u539F\u578B\u94FE\u6C61\u67D3\u9632\u5FA1:** Node.js \u5185\u90E8\u7684 JavaScript \u4EE3\u7801\u4E3A\u4E86\u9632\u6B62\u539F\u578B\u94FE\u6C61\u67D3\uFF0C\u4F7F\u7528\u4E86 JavaScript \u5185\u5EFA\u5BF9\u8C61\u7684\u4E00\u4E2A\u7279\u6B8A\u526F\u672C\uFF0C\u8FD9\u5927\u5927\u964D\u4F4E\u4E86\u4EE3\u7801\u7684\u53EF\u8BFB\u6027\u3002\\n- **\u5FAA\u73AF\u4F9D\u8D56:** \u52A0\u8F7D\u5668\u88AB\u62C6\u5206\u5230\u591A\u4E2A\u6587\u4EF6\u4E2D\uFF0C\u4F46\u6587\u4EF6\u4E4B\u95F4\u7684\u7EC4\u7EC7\u65B9\u5F0F\u5BFC\u81F4\u4E86\u666E\u904D\u7684\u5FAA\u73AF\u4F9D\u8D56\u3002\\n- **\u4E34\u65F6\u6B7B\u533A (TDZ) \u9632\u5FA1:** \u90E8\u5206\u4EE3\u7801\u9700\u8981\u4E3B\u52A8\u9632\u5FA1 `let` \u548C `const` \u5F15\u5165\u7684[\u4E34\u65F6\u6B7B\u533A (TDZ)](https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Statements/let#%E6%9A%82%E6%97%B6%E6%80%A7%E6%AD%BB%E5%8C%BA_tdz)\uFF0C\u8FD9\u4F7F\u5F97\u4EE3\u7801\u66F4\u52A0\u96BE\u4EE5\u9605\u8BFB\u3002\\n- **\u4E0D\u5FC5\u8981\u7684\u5F02\u6B65:** \u8FD9\u4E2A\u76F8\u5F53\u590D\u6742\u7684 JavaScript \u4EE3\u7801\u5E93\u4E5F\u7ED9\u52A0\u8F7D\u8FC7\u7A0B\u5E26\u6765\u4E86\u5F88\u591A\u968F\u673A\u4E14\u4E0D\u5FC5\u8981\u7684\u5F02\u6B65\u6027\u3002\\n- **\u5BF9 V8 \u80FD\u529B\u5229\u7528\u4E0D\u8DB3:** ESM \u7684\u76F8\u5F53\u4E00\u90E8\u5206\u652F\u6301\u662F\u7531 V8 \u63D0\u4F9B\u7684\uFF0C\u8FD9\u4E9B\u80FD\u529B\u901A\u8FC7 C++/JS \u7ED1\u5B9A\u66B4\u9732\u7ED9 JavaScript \u5C42\u3002\u4F46\u770B\u8D77\u6765\u968F\u7740\u65F6\u95F4\u7684\u63A8\u79FB\uFF0CJavaScript \u90E8\u5206\u5F00\u59CB\u81EA\u6211\u9650\u5236\u4E8E C++/JS \u7ED1\u5B9A\u6240\u63D0\u4F9B\u7684\u529F\u80FD\uFF0C\u800C\u6CA1\u6709\u5145\u5206\u5229\u7528 V8 \u672C\u8EAB\u63D0\u4F9B\u7684\u80FD\u529B\u3002\\n\\n### \u6027\u80FD\u5F71\u54CD\uFF1A\u540C\u6B65\u53CD\u800C\u66F4\u5FEB\uFF1F\\n\\n\u8FD9\u4E9B ESM \u52A0\u8F7D\u5668\u7684\u6280\u672F\u95EE\u9898\u4E5F\u5E26\u6765\u4E86\u5176\u4ED6\u540E\u679C\uFF0C\u4F8B\u5982\u6027\u80FD\u65B9\u9762\u3002\u6709\u4EBA\u53EF\u80FD\u5047\u8BBE\uFF0C\u80FD\u591F\u59CB\u7EC8\u5F02\u6B65\u52A0\u8F7D\uFF08\u5E76\u4E14\u5982\u679C\u6A21\u5757\u5305\u542B\u591A\u4E2A `import`\uFF0C\u8FD8\u80FD\u5E76\u884C\u52A0\u8F7D\uFF09\u4F1A\u8BA9\u52A0\u8F7D\u901F\u5EA6\u66F4\u5FEB\u3002\\n\\n\u4F46\u5F53\u6211\u7528 `require(esm)` \u6D4B\u8BD5\u90A3 30 \u591A\u4E2A\u7EAF ESM npm \u5305\uFF0C\u5E76\u4E0E `import esm` \u8FDB\u884C\u6BD4\u8F83\u65F6\uFF0C\u524D\u8005\uFF08\u4F7F\u7528\u4E86\u4E13\u95E8\u7684\u540C\u6B65\u8DEF\u5F84\uFF09**\u5B9E\u9645\u4E0A\u901F\u5EA6\u5FEB\u4E86\u7EA6 1.22 \u500D** ([\u6D4B\u8BD5\u7ED3\u679C\u8BC4\u8BBA](https://github.com/nodejs/node/pull/51977#issuecomment-1995209126))\u3002\u8FD9\u8868\u660E\u5F53\u524D ESM \u52A0\u8F7D\u5668\u4E2D\u7684\uFF08\u4E0D\u5FC5\u8981\u7684\uFF09\u5F02\u6B65\u5F00\u9500\u53EF\u80FD\u62D6\u6162\u4E86\u540C\u6B65\u6A21\u5757\u7684\u52A0\u8F7D\u901F\u5EA6\u3002\\n\\n## \u91CD\u542F\u540C\u6B65 `require(esm)` \u4E4B\u8DEF\\n\\n\u53BB\u5E74\u5E74\u5E95\uFF0C\u5728\u6211\u53D1\u73B0 ESM \u7684\u6267\u884C\u53EF\u4EE5\u6839\u636E\u8BED\u6CD5\u662F\u540C\u6B65\u7684\uFF0C\u5E76\u4E14\u53EA\u662F Node.js \u5728\u52A0\u8F7D\u8FC7\u7A0B\u4E2D\u5F3A\u52A0\u4E86\u5F02\u6B65\u6027\u4E4B\u540E\uFF0C\u6211\u548C [@GeoffreyBooth](https://github.com/GeoffreyBooth) \u5F00\u59CB\u8BA8\u8BBA\u91CD\u542F\u540C\u6B65 `require(esm)` \u7684\u5DE5\u4F5C\u3002\u5373\u4F7F\u5230\u4ECA\u5929\uFF0CNode.js \u7684 ESM \u5BF9\u6211\u6765\u8BF4\u4ECD\u7136\u662F\u4E00\u4E2A\u4EE4\u4EBA\u751F\u754F\u7684\u8BDD\u9898\uFF0C\u4F46\u662F `ERR_REQUIRE_ESM` \u5E26\u6765\u7684\u75DB\u82E6\u5B9E\u5728\u592A\u6DF1\u4E86\uFF0C\u4F3C\u4E4E\u503C\u5F97\u5192\u7740\u5377\u5165\u90A3\u4E9B\u8D39\u529B\u8FA9\u8BBA\u7684\u98CE\u9669\uFF0C\u6765\u91CD\u65B0\u63A8\u52A8\u8FD9\u4EF6\u4E8B\u3002\\n\\n\u8BDD\u867D\u5982\u6B64\uFF0C\u5982\u679C\u8FD9\u662F\u4E00\u4E2A\u975E\u5E38\u96BE\u4EE5\u5B9E\u73B0\u7684\u76EE\u6807 (high-hanging fruit)\uFF0C\u6211\u4E5F\u4E0D\u4F1A\u53BB\u5192\u9669\u2014\u2014\u5728\u6211\u771F\u6B63\u7814\u7A76 ESM \u52A0\u8F7D\u5668\u4E4B\u524D\uFF0C\u6211\u786E\u5B9E\u662F\u8FD9\u4E48\u8BA4\u4E3A\u7684\u3002\u5F53\u65F6\u6709\u4E00\u4E2A\u6B63\u5728\u8FDB\u884C\u7684\u52AA\u529B\uFF0C\u76EE\u6807\u662F\u201C\u8BA9 ESM \u52A0\u8F7D\u5668\u6210\u4E3A Node.js \u4E2D\u552F\u4E00\u7684\u52A0\u8F7D\u5668\u201D\u3002\u8003\u8651\u5230\u524D\u9762\u63D0\u5230\u7684\u590D\u6742\u6027\uFF0C\u4F30\u8BA1\u9700\u8981\u76F8\u5F53\u957F\u7684\u65F6\u95F4\u6765\u91CD\u6784 ESM \u52A0\u8F7D\u5668\u4EE5\u652F\u6301\u8FD9\u4E00\u76EE\u6807\u3002\u6240\u4EE5\u6211\u5B81\u613F\u628A\u8FD9\u9879\u91CD\u6784\u5DE5\u4F5C\u7559\u7ED9\u90A3\u4E9B\u66F4\u719F\u6089 ESM \u52A0\u8F7D\u5668\u7684\u4EBA\u3002\\n\\n### \u53D1\u73B0\u66F4\u7B80\u5355\u7684\u8DEF\u5F84\\n\\n\u76F4\u5230 2024 \u5E74 2 \u6708\u5E95\uFF0C\u5F53\u6211\u5728\u4E3A CJS \u548C ESM \u52A0\u8F7D\u5668\u5F00\u53D1\u4E00\u4E2A\u7C7B\u4F3C ccache \u7684\u7F13\u5B58\u673A\u5236 ([Issue #47472](https://github.com/nodejs/node/issues/47472)) \u5E76\u518D\u6B21\u6DF1\u5165\u7814\u7A76\u5B83\u4EEC\u65F6\uFF0C\u6211\u6CE8\u610F\u5230\u4F3C\u4E4E\u5B58\u5728\u4E00\u79CD\u66F4\u7B80\u5355\u7684\u5B9E\u73B0\u65B9\u5F0F\uFF1A\\n\\n**\u653E\u5F03\u201C\u8BA9 ESM \u52A0\u8F7D\u5668\u6210\u4E3A\u552F\u4E00\u52A0\u8F7D\u5668\u201D\u7684\u60F3\u6CD5**\uFF08\u6211\u5BF9\u6B64\u672C\u5C31\u6301\u6000\u7591\u6001\u5EA6\uFF09\uFF0C\u8F6C\u800C\u4E3A CJS \u52A0\u8F7D\u5668\u5B9E\u73B0\u4E00\u4E9B**\u4E13\u95E8\u7684\u540C\u6B65\u4F8B\u7A0B**\u6765\u652F\u6301 `require(esm)`\u3002\u5B83\u4F7F\u7528\u7684\u73B0\u6709 ESM \u52A0\u8F7D\u5668\u4EE3\u7801\u8D8A\u5C11\uFF0C\u5B9E\u73B0\u8D77\u6765\u5C31\u8D8A\u5BB9\u6613\u3002\\n\\n### \u65B0\u7684 PR \u4E0E\u66F4\u5C0F\u7684\u8303\u56F4\\n\\n\u8FD9\u5C31\u50AC\u751F\u4E86 [PR #51977](https://github.com/nodejs/node/pull/51977)\u3002\u8FD9\u4E2A PR \u4E0E 2019 \u5E74\u7684\u90A3\u4E2A\u4E3B\u8981\u533A\u522B\u5728\u4E8E\uFF0C\u5B83**\u8BD5\u56FE\u5C06 `require(esm)` \u7684\u8303\u56F4\u4FDD\u6301\u5F97\u5F88\u5C0F\uFF0C\u5E76\u4E14\u53EA\u652F\u6301\u52A0\u8F7D\u540C\u6B65\u7684 ESM**\u3002\\n\\n\u4E8B\u5B9E\u8BC1\u660E\uFF0C\u8FD9\u4E2A\u60F3\u6CD5\u5728\u534F\u4F5C\u8005/TSC \u4E2D\u6839\u672C\u6CA1\u6709\u4E89\u8BAE\uFF0C\u5E76\u4E14\u51E0\u4E4E\u6CA1\u6709\u9047\u5230\u963B\u529B\u5C31\u5408\u5E76\u4E86\uFF08\u4E2D\u95F4\u56E0\u4E3A\u5173\u4E8E\u52A0\u8F7D\u5668\u94A9\u5B50 (loader hooks) \u7684\u8BA8\u8BBA\u7A0D\u5FAE\u504F\u79BB\u4E86\u4E00\u4E0B\uFF0C\u4F46\u81F3\u5C11\u6211\u4EEC\u8FBE\u6210\u4E86\u4E00\u81F4\uFF1A\u94A9\u5B50\u652F\u6301\u53EF\u4EE5\u7559\u7ED9\u540E\u7EED\u5DE5\u4F5C\uFF0C\u800C `require(esm)` \u672C\u8EAB\u5E94\u8BE5\u56DE\u5230\u6B63\u8F68\uFF09\u3002\\n\\n## \u4E0B\u4E00\u6B65\u8BA1\u5212\u662F\u4EC0\u4E48\uFF1F\\n\\n\u76EE\u524D\uFF0C\u8FD9\u4E2A\u529F\u80FD\u4ECD\u7136\u662F\u5B9E\u9A8C\u6027\u7684\uFF0C\u9700\u8981\u901A\u8FC7 `--experimental-require-module` \u6807\u5FD7\u542F\u7528\u3002\u5728\u5B83\u6B63\u5F0F\u53D1\u5E03\u4E4B\u524D\uFF0C\u8FD8\u6709\u4E00\u4E9B\u5DE5\u4F5C\u9700\u8981\u5B8C\u6210\u3002\\n\\n### \u5F85\u529E\u4E8B\u9879\\n\\n1.  **\u5904\u7406\u8FB9\u7F18\u60C5\u51B5:** \u53EF\u80FD\u8FD8\u6709\u4E00\u4E9B\u8FB9\u7F18\u60C5\u51B5\u9700\u8981\u5904\u7406\u3002\u6211\u5728 PR \u4E2D\u5C1D\u8BD5\u6D4B\u8BD5\u4E86\u5F88\u591A\u8FB9\u7F18\u60C5\u51B5\uFF0C\u4F46\u6A21\u5757\u56FE\u7684\u53EF\u80FD\u6027\u5B9E\u5728\u592A\u591A\uFF0C\u65E0\u6CD5\u5728\u4E00\u4E2A PR \u4E2D\u5168\u90E8\u8986\u76D6\u3002\u521D\u59CB\u7248\u672C\u5DF2\u7ECF\u8DB3\u4EE5\u52A0\u8F7D\u6211\u6D4B\u8BD5\u8FC7\u7684\u5927\u591A\u6570\u9AD8\u5F71\u54CD\u529B\u7684\u7EAF ESM npm \u5305\u3002\u6211\u4EEC\u53EF\u4EE5\u968F\u7740\u7528\u6237\u53CD\u9988\u7EE7\u7EED\u6253\u78E8\u5B83\u3002\\n2.  **\u81EA\u5B9A\u4E49\u52A0\u8F7D\u5668\u94A9\u5B50 (Loader Hooks) \u652F\u6301:** \u5F53\u524D\u7684\u52A0\u8F7D\u5668\u94A9\u5B50\u4E5F\u662F\u65E0\u6761\u4EF6\u5F02\u6B65\u7684\u3002\u8FD9\u901A\u8FC7\u4F7F\u7528 worker \u6765\u8BA9\u4E3B\u7EBF\u7A0B\u963B\u585E\u5728\u52A0\u8F7D\u5668\u4E0A\uFF0C\u5E26\u6765\u4E86\u5DE8\u5927\u7684\u5F00\u9500\u3002\u867D\u7136\u8FD9\u603B\u6BD4\u5B8C\u5168\u6CA1\u6709\u52A0\u8F7D\u5668\u94A9\u5B50\u8981\u597D\uFF0C\u4F46\u5728\u6027\u80FD\u548C\u80FD\u529B\u65B9\u9762\uFF0C\u8FD9\u8FDC\u4E0D\u53CA `require()` \u7684\u7334\u5B50\u8865\u4E01 (monkey-patching) \u6240\u80FD\u63D0\u4F9B\u7684\u3002\\n\\n    > **\u77E5\u8BC6\u70B9\u8865\u5145 (Loader Hooks & Monkey Patching):**\\n    >\\n    > - **Loader Hooks:** Node.js \u63D0\u4F9B\u7684\u4E00\u79CD\u673A\u5236\uFF0C\u5141\u8BB8\u5F00\u53D1\u8005\u4ECB\u5165\u6A21\u5757\u52A0\u8F7D\u8FC7\u7A0B\uFF0C\u4F8B\u5982\u5B9E\u73B0\u81EA\u5B9A\u4E49\u7684\u6A21\u5757\u89E3\u6790\u903B\u8F91\uFF08\u5982\u8DEF\u5F84\u522B\u540D\uFF09\u3001\u8F6C\u6362\u4EE3\u7801\uFF08\u5982\u5B9E\u65F6\u7F16\u8BD1 TypeScript\uFF09\u7B49\u3002\u76EE\u524D\u7684\u94A9\u5B50\u662F\u5F02\u6B65\u7684\uFF0C\u8FD0\u884C\u5728\u5355\u72EC\u7684 worker \u7EBF\u7A0B\u4E2D\u3002\\n    > - **Monkey Patching `require()`:** \u5728 CJS \u65F6\u4EE3\uFF0C\u5F88\u591A\u5E93\uFF08\u5982 `ts-node/register`, `babel-register`, APM \u5DE5\u5177\u7B49\uFF09\u901A\u8FC7\u76F4\u63A5\u4FEE\u6539 Node.js \u5185\u5EFA\u7684 `require` \u51FD\u6570\u6216\u5176\u5185\u90E8\u673A\u5236\u6765\u8FBE\u5230\u7C7B\u4F3C\u76EE\u7684\u3002\u8FD9\u79CD\u65B9\u5F0F\u867D\u7136\u7075\u6D3B\u5F3A\u5927\uFF0C\u4F46\u975E\u5E38\u8106\u5F31\uFF08\u4F9D\u8D56 Node.js \u5185\u90E8\u5B9E\u73B0\uFF09\u3001\u53EF\u80FD\u76F8\u4E92\u51B2\u7A81\uFF0C\u4E14\u88AB\u8BA4\u4E3A\u662F\u4E0D\u5B89\u5168\u7684\u5B9E\u8DF5\u3002\\n    >\\n    > \u540C\u6B65\u52A0\u8F7D\u5668\u94A9\u5B50\u7684\u76EE\u6807\u662F\u63D0\u4F9B\u4E00\u4E2A\u5B98\u65B9\u3001\u7A33\u5B9A\u4E14\u9AD8\u6027\u80FD\u7684\u66FF\u4EE3\u65B9\u6848\uFF0C\u53D6\u4EE3\u8106\u5F31\u7684\u7334\u5B50\u8865\u4E01\u3002\\n\\n    \u6211\u8BA4\u4E3A\u4E0B\u4E00\u6B65\u5E94\u8BE5\u662F\u5F00\u53D1\u4E00\u79CD**\u7EBF\u7A0B\u5185 (in-thread) \u4E14\u540C\u6B65**\u7684\u52A0\u8F7D\u5668\u94A9\u5B50\u53D8\u4F53\uFF0C\u540C\u65F6\u652F\u6301 `require()` \u548C `import`\u3002\u8FD9\u53EF\u80FD\u4F7F\u5F97 `require()` \u7334\u5B50\u8865\u4E01\u4E0D\u518D\u5FC5\u8981\uFF0C\u5E76\u8BA9\u66F4\u591A\u7528\u6237\u80FD\u591F\u4ECE CJS \u8FC1\u79FB\u5230 ESM\u3002\\n\\n3.  **\u6A21\u5757\u7C7B\u578B\u68C0\u6D4B:** \u76EE\u524D `require(esm)` \u53EA\u652F\u6301\u88AB\u660E\u786E\u6807\u8BB0\u4E3A ESM \u7684\u6A21\u5757\u2014\u2014\u8981\u4E48\u901A\u8FC7 `.mjs` \u6269\u5C55\u540D\uFF0C\u8981\u4E48\u5728\u6700\u8FD1\u7684 `package.json` \u4E2D\u4E3A `.js` \u6587\u4EF6\u8BBE\u7F6E\u4E86 `\\"type\\": \\"module\\"`\u3002\u8FD9\u5DF2\u7ECF\u8DB3\u4EE5\u652F\u6301\u52A0\u8F7D npm \u4E0A\u7684\u7EAF ESM \u5305\u3002\\n    \u6280\u672F\u4E0A\u53EF\u4EE5\u5B9E\u73B0\u5F53\u9047\u5230\u6CA1\u6709 `\\"type\\": \\"module\\"` \u6807\u8BB0\u4F46\u5305\u542B ESM \u8BED\u6CD5\u7684 `.js` \u6587\u4EF6\u65F6\uFF0C\u56DE\u9000\u5230 ESM \u52A0\u8F7D\u3002\u4F46\u8FD9\u901A\u5E38\u662F\u7528\u6237\u5E94\u8BE5\u907F\u514D\u7684\u505A\u6CD5\u2014\u2014ESM \u8BED\u6CD5\u68C0\u6D4B\u4F1A\u5E26\u6765\u5F00\u9500\u3002\u4E00\u65E6\u4F60\u7684\u9879\u76EE\u4E2D\u6709\u8DB3\u591F\u591A\u7684 ESM \u6A21\u5757\uFF0C\u4F60\u53EF\u80FD\u4E0D\u5E0C\u671B Node.js \u6D6A\u8D39\u65F6\u95F4\u53BB\u731C\u6D4B\u4F60\u7684\u6A21\u5757\u7C7B\u578B\uFF0C\u800C\u4F60\u672C\u53EF\u4EE5\u901A\u8FC7\u5728 `package.json` \u4E2D\u6DFB\u52A0\u4E00\u4E2A\u660E\u786E\u7684 `\\"type\\": \\"module\\"` \u5B57\u6BB5\u6765\u8282\u7701\u8FD9\u4E9B\u6210\u672C\u3002\\n\\n4.  **\u5165\u53E3\u70B9\u7684\u9876\u5C42 `await` \u652F\u6301:** \u652F\u6301\u5728\u5165\u53E3\u70B9\u4F7F\u7528 TLA \u4ECD\u7136\u662F\u53EF\u80FD\u7684\u3002\u56E0\u4E3A\u5165\u53E3\u70B9\u7684\u5BFC\u51FA (exports) \u4E0D\u4F1A\u88AB\u5176\u4ED6\u6A21\u5757\u4F7F\u7528\uFF0C\u6211\u4EEC\u53EF\u4EE5\u5728\u8FD9\u79CD\u60C5\u51B5\u4E0B\u7B80\u5355\u5730\u56DE\u9000\u5230\u5F02\u6B65\u52A0\u8F7D\u3002\u8FD9\u5DF2\u7ECF\u53EF\u4EE5\u901A\u8FC7 `--experimental-detect-module` \u6807\u5FD7\u5B9E\u73B0\uFF0C\u73B0\u5728\u66F4\u591A\u7684\u662F\u4E00\u4E2A\u5B9E\u73B0\u7EC6\u8282\u95EE\u9898\uFF0C\u5373\u5728 CJS \u52A0\u8F7D\u5668\u5185\u90E8\uFF08\u65E2\u7136\u5B83\u73B0\u5728\u652F\u6301\u52A0\u8F7D ESM \u4E86\uFF09\u5B9E\u73B0\u8FD9\u79CD\u56DE\u9000\u3002\\n\\n## \u7ED3\u8BED\\n\\n\u8FD9\u9879\u5B9E\u9A8C\u6027\u529F\u80FD\u6807\u5FD7\u7740 Node.js \u5728\u5F25\u5408 CJS \u548C ESM \u9E3F\u6C9F\u65B9\u9762\u8FC8\u51FA\u4E86\u91CD\u8981\u4E00\u6B65\u3002\u867D\u7136\u8FD8\u6709\u540E\u7EED\u5DE5\u4F5C\u8981\u505A\uFF0C\u4F46\u5B83\u6709\u671B\u6781\u5927\u5730\u6539\u5584\u5F00\u53D1\u8005\u7684\u4F53\u9A8C\uFF0C\u51CF\u5C11\u56E0 `ERR_REQUIRE_ESM` \u800C\u6D6A\u8D39\u7684\u65F6\u95F4\uFF0C\u5E76\u53EF\u80FD\u4E3A\u66F4\u5E73\u6ED1\u5730\u5411 ESM \u8FC7\u6E21\u94FA\u5E73\u9053\u8DEF\u3002\\n\\n\u6700\u540E\uFF0C\u611F\u8C22 Bloomberg \u591A\u5E74\u6765\u5BF9\u6211\u5DE5\u4F5C\u7684\u8D5E\u52A9\uFF0C\u652F\u6301\u6211\u89E3\u51B3\u4E86\u8FD9\u4E2A\u4EE4\u4EBA\u5934\u75BC\u7684\u95EE\u9898\u3002\\n\\n---"},{"id":"/2025/04/15/TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","metadata":{"permalink":"/transblog/2025/04/15/TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","source":"@site/blog-translated/2025/04-15-TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357.md","title":"TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","description":"- \u539F\u6587\u94FE\u63A5\uFF1A https://github.com/sindresorhus/typescript-definition-style-guide/blob/main/readme.md?plain=1","date":"2025-04-15T12:00:00.000Z","tags":[{"inline":true,"label":"TypeScript","permalink":"/transblog/tags/type-script"}],"readingTime":23.255,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","date":"2025-04-15T12:00:00.000Z","tags":["TypeScript"]},"unlisted":false,"prevItem":{"title":"require() ESM in Node.js","permalink":"/transblog/2025/04/19/require-esm-in-node-js"},"nextItem":{"title":"\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","permalink":"/transblog/2025/04/05/\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357"}},"content":"> - \u539F\u6587\u94FE\u63A5\uFF1A https://github.com/sindresorhus/typescript-definition-style-guide/blob/main/readme.md?plain=1\\n> - \u673A\u5668\u7FFB\u8BD1\uFF1A Gemini 2.5 Pro Preview\\n> - \u63D0\u793A\u8BCD\uFF1A \u7FFB\u8BD1\u4EE5\u4E0B\u6587\u6863\uFF0C\u5E76\u4E14\u7ED3\u5408\u4F60\u7684\u524D\u7AEF\u5F00\u53D1\u4E13\u4E1A\u77E5\u8BC6\u8865\u5145\u76F8\u5173\u7684\u77E5\u8BC6\u70B9\u8BF4\u660E\uFF0C\u5BF9\u6587\u7AE0\u5185\u5BB9\u8FDB\u884C\u7ED3\u6784\u5316\uFF0C\u4EE5 Markdown \u683C\u5F0F\u8FD4\u56DE\uFF0C\u6587\u5B57\u98CE\u683C\u662F\u6280\u672F\u535A\u5BA2\u3002\\n> - \u7FFB\u8BD1\u7406\u7531\uFF1A\u4F5C\u8005\u5728 npm \u4E0A\u8D21\u732E\u9887\u591A\uFF0C\u6240\u4EE5\u4ED6\u7684 TS \u5FC3\u5F97\u6709\u4E00\u5B9A\u501F\u9274\u610F\u4E49\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n# TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357 (\u589E\u5F3A\u7248)\\n\\n\u672C\u6307\u5357\u5047\u8BBE\u4F60\u7684 npm \u5305\u662F\u539F\u751F ES Module (ESM) \u683C\u5F0F\u3002\u7F16\u5199\u548C\u7EF4\u62A4\u826F\u597D\u7684 TypeScript \u7C7B\u578B\u5B9A\u4E49 (`.d.ts` \u6587\u4EF6) \u5BF9\u4E8E\u5E93\u7684\u5F00\u53D1\u8005\u548C\u4F7F\u7528\u8005\u90FD\u81F3\u5173\u91CD\u8981\u3002\u5B83\u4E0D\u4EC5\u80FD\u63D0\u4F9B\u5F3A\u5927\u7684\u4EE3\u7801\u63D0\u793A\u3001\u81EA\u52A8\u8865\u5168\u548C\u7F16\u8BD1\u65F6\u7C7B\u578B\u68C0\u67E5\uFF0C\u8FD8\u80FD\u4F5C\u4E3A\u4E00\u79CD\u7CBE\u786E\u7684 API \u6587\u6863\u5F62\u5F0F\uFF0C\u663E\u8457\u63D0\u5347\u5F00\u53D1\u4F53\u9A8C (DX) \u548C\u4EE3\u7801\u5065\u58EE\u6027\u3002\\n\\n## \u6838\u5FC3\u6E05\u5355 (Core Checklist)\\n\\n\u5728\u4E3A\u4F60\u7684 npm \u5305\u6DFB\u52A0\u6216\u66F4\u65B0 TypeScript \u7C7B\u578B\u5B9A\u4E49\u65F6\uFF0C\u8BF7\u9075\u5FAA\u4EE5\u4E0B\u6838\u5FC3\u539F\u5219\uFF1A\\n\\n1.  **\u4EE3\u7801\u98CE\u683C**:\\n    - \u4F7F\u7528 **Tab** \u8FDB\u884C\u7F29\u8FDB\u3002\\n    - \u4F7F\u7528 **\u5206\u53F7** (`;`) \u7ED3\u675F\u8BED\u53E5\u3002\\n    - _\u8865\u5145: \u4FDD\u6301\u4E00\u81F4\u7684\u4EE3\u7801\u98CE\u683C\u6709\u52A9\u4E8E\u56E2\u961F\u534F\u4F5C\u548C\u4EE3\u7801\u5E93\u7684\u53EF\u7EF4\u62A4\u6027\u3002\u9009\u62E9 Tab \u8FD8\u662F\u7A7A\u683C\u3001\u662F\u5426\u4F7F\u7528\u5206\u53F7\u867D\u7136\u6709\u4E89\u8BAE\uFF0C\u4F46\u5173\u952E\u662F\u9075\u5FAA\u9879\u76EE\u6216\u56E2\u961F\u7684\u7EDF\u4E00\u89C4\u8303\u3002_\\n2.  **TypeScript \u7248\u672C**: \u7C7B\u578B\u5B9A\u4E49\u5E94\u9488\u5BF9 **\u6700\u65B0\u7A33\u5B9A\u7248** \u7684 TypeScript \u8FDB\u884C\u7F16\u5199\u3002\\n    - _\u8865\u5145: \u5229\u7528 TypeScript \u7684\u6700\u65B0\u7279\u6027\u53EF\u4EE5\u7F16\u5199\u51FA\u66F4\u7CBE\u786E\u3001\u66F4\u7B80\u6D01\u7684\u7C7B\u578B\u5B9A\u4E49\uFF0C\u540C\u65F6\u786E\u4FDD\u4E0E\u6700\u65B0\u7684 TS \u5F00\u53D1\u73AF\u5883\u517C\u5BB9\u3002_\\n3.  **\u6587\u6863\u6CE8\u91CA**: \u6240\u6709\u5BFC\u51FA\u7684\u5C5E\u6027\u3001\u65B9\u6CD5\u3001\u7C7B\u578B\u7B49\u90FD\u5E94\u4F7F\u7528 [TSDoc](https://github.com/Microsoft/tsdoc) \u683C\u5F0F\u6DFB\u52A0\u6587\u6863\u6CE8\u91CA (\u8BE6\u89C1\u4E0B\u6587)\u3002\\n    - _\u8865\u5145: \u6E05\u6670\u7684\u6587\u6863\u6CE8\u91CA\u662F\u826F\u597D\u7C7B\u578B\u5B9A\u4E49\u7684\u5173\u952E\u7EC4\u6210\u90E8\u5206\uFF0CIDE \u4F1A\u5229\u7528\u8FD9\u4E9B\u6CE8\u91CA\u63D0\u4F9B\u4E30\u5BCC\u7684\u60AC\u505C\u63D0\u793A\u4FE1\u606F\u3002_\\n4.  **\u7C7B\u578B\u6D4B\u8BD5**: \u7C7B\u578B\u5B9A\u4E49\u5FC5\u987B\u7ECF\u8FC7\u6D4B\u8BD5 (\u8BE6\u89C1\u4E0B\u6587)\u3002\\n    - _\u8865\u5145: \u7C7B\u578B\u6D4B\u8BD5\u786E\u4FDD\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u80FD\u6B63\u786E\u53CD\u6620\u8FD0\u884C\u65F6\u7684\u884C\u4E3A\uFF0C\u9632\u6B62\u7C7B\u578B\u9519\u8BEF\u6216\u4E0D\u51C6\u786E\u5BFC\u81F4\u7684\u4F7F\u7528\u8005\u56F0\u60D1\u3002_\\n5.  **Node.js \u7C7B\u578B**:\\n    - \u5982\u679C\u9700\u8981\u4F7F\u7528 Node.js \u5185\u7F6E\u6A21\u5757\u7684\u7C7B\u578B (\u5982 `fs`, `http` \u7B49)\uFF0C\u8BF7\u5C06 `@types/node` \u5B89\u88C5\u4E3A **\u5F00\u53D1\u4F9D\u8D56** (`devDependencies`)\u3002\\n    - **\u4E0D\u8981** \u5728\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u9876\u90E8\u6DFB\u52A0 `/// <reference types=\\"node\\"/>` \u4E09\u659C\u7EBF\u6307\u4EE4\u3002\u5E94\u4F7F\u7528 ES Module \u7684 `import` \u8BED\u6CD5\u5BFC\u5165\u6240\u9700\u7C7B\u578B\u3002\\n    - _\u8865\u5145: \u5C06 `@types/node` \u4F5C\u4E3A `devDependency` \u662F\u56E0\u4E3A\u7C7B\u578B\u68C0\u67E5\u53EA\u5728\u5F00\u53D1\u9636\u6BB5\u9700\u8981\u3002\u907F\u514D\u4E09\u659C\u7EBF\u6307\u4EE4\u6709\u52A9\u4E8E\u4FDD\u6301\u4EE3\u7801\u7684\u6A21\u5757\u5316\u548C\u6E05\u6670\u6027\uFF0C`import` \u8BED\u6CD5\u662F\u73B0\u4EE3 JS/TS \u7684\u6807\u51C6\u3002_\\n6.  **\u7B2C\u4E09\u65B9\u5E93\u7C7B\u578B**:\\n    - \u5982\u679C\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u4F9D\u8D56\u4E86\u5176\u4ED6\u7B2C\u4E09\u65B9\u5E93\u7684\u7C7B\u578B (\u901A\u5E38\u5728 `@types/*` \u547D\u540D\u7A7A\u95F4\u4E0B)\uFF0C\u8FD9\u4E9B\u7C7B\u578B\u5305\u5FC5\u987B\u4F5C\u4E3A **\u76F4\u63A5\u4F9D\u8D56** (`dependencies`) \u5B89\u88C5\u3002\\n    - \u540C\u6837\uFF0C\u4F7F\u7528 `import` \u8BED\u53E5\u5BFC\u5165\u7C7B\u578B\uFF0C**\u4E0D\u8981** \u4F7F\u7528\u4E09\u659C\u7EBF\u6307\u4EE4\u3002\\n    - _\u8865\u5145: \u5982\u679C\u4F60\u7684 `.d.ts` \u6587\u4EF6\u5BFC\u51FA\u7684\u7C7B\u578B\u7B7E\u540D\u4E2D\u5305\u542B\u4E86\u6765\u81EA `@types/some-lib` \u7684\u7C7B\u578B\uFF0C\u90A3\u4E48\u4F7F\u7528\u8005\u5728\u5B89\u88C5\u4F60\u7684\u5305\u65F6\uFF0C\u4E5F\u9700\u8981\u8FD9\u4E2A\u7C7B\u578B\u4FE1\u606F\u624D\u80FD\u6B63\u786E\u8FDB\u884C\u7C7B\u578B\u68C0\u67E5\u3002\u56E0\u6B64\uFF0C\u8FD9\u4E9B\u7C7B\u578B\u5305\u662F\u516C\u5171 API \u7684\u4E00\u90E8\u5206\uFF0C\u5E94\u4F5C\u4E3A `dependencies`\u3002_\\n7.  **\u907F\u514D\u5E38\u89C1\u9519\u8BEF**: \u786E\u4FDD\u4F60\u6CA1\u6709\u72AF [DefinitelyTyped \u5E38\u89C1\u9519\u8BEF\u5217\u8868](https://github.com/DefinitelyTyped/DefinitelyTyped/#common-mistakes) \u4E2D\u63D0\u5230\u7684\u95EE\u9898\u3002\\n8.  **\u9ED8\u8BA4\u5BFC\u51FA**: \u5BF9\u4E8E\u5177\u6709\u9ED8\u8BA4\u5BFC\u51FA\u7684\u5305\uFF0C\u4F7F\u7528 `export default function foo(\u2026)` \u6216 `export default class Bar {\u2026}` \u7B49\u6807\u51C6\u8BED\u6CD5\u3002\\n    - _\u8865\u5145: \u8FD9\u786E\u4FDD\u4E86\u4E0E ES Module \u7684 `import defaultMember from \'package\'` \u8BED\u6CD5\u517C\u5BB9\u3002_\\n9.  **\u7981\u6B62 `namespace`**: \u4E0D\u8981\u4F7F\u7528 `namespace` (\u6216\u65E7\u7684 `module`) \u5173\u952E\u5B57\u6765\u7EC4\u7EC7\u7C7B\u578B\u3002\\n    - _\u8865\u5145: ES Module \u63D0\u4F9B\u4E86\u6807\u51C6\u7684\u6A21\u5757\u5316\u673A\u5236\uFF0C`namespace` \u662F\u65E7\u65F6\u4EE3\u7684\u4EA7\u7269\uFF0C\u5728\u73B0\u4EE3 TS \u5F00\u53D1\u4E2D\u5E94\u907F\u514D\u4F7F\u7528\uFF0C\u4EE5\u9632\u547D\u540D\u51B2\u7A81\u548C\u589E\u52A0\u7406\u89E3\u8D1F\u62C5\u3002_\\n10. **\u9075\u5FAA\u8D21\u732E\u6D41\u7A0B** (\u5982\u679C\u9002\u7528\uFF0C\u4F8B\u5982\u5411 Sindre Sorhus \u7684\u9879\u76EE\u8D21\u732E):\\n    - Pull Request \u7684\u6807\u9898\u5E94\u4E3A `Add TypeScript definition` (\u8BF7\u76F4\u63A5\u590D\u5236\u7C98\u8D34\uFF0C\u786E\u4FDD\u65E0\u8BEF)\u3002\\n    - \u79EF\u6781\u5E2E\u52A9\u5BA1\u67E5\u5176\u4ED6\u6DFB\u52A0\u7C7B\u578B\u5B9A\u4E49\u7684 [Pull Requests](https://github.com/search?q=user%3Asindresorhus+is%3Apr+is%3Aopen+%22Add+TypeScript+definition%22&type=Issues)\u3002\\n\\n\u53EF\u4EE5\u53C2\u8003\u4EE5\u4E0B\u4F18\u79C0\u5B9E\u8DF5\u6848\u4F8B\uFF1A\\n\\n- [sindresorhus/filled-array \u7684\u7C7B\u578B\u5B9A\u4E49\u63D0\u4EA4](https://github.com/sindresorhus/filled-array/commit/aae7539cb32f163cb063499664b012d0b04b3104) (\u5305\u542B\u6D4B\u8BD5\u96C6\u6210)\\n- [sindresorhus/write-json-file \u7684 index.d.ts](https://github.com/sindresorhus/write-json-file/blob/main/index.d.ts)\\n- [sindresorhus/delay \u7684 index.d.ts](https://github.com/sindresorhus/delay/blob/main/index.d.ts)\\n\\n## `package.json` \u914D\u7F6E\\n\\n\u6B63\u786E\u914D\u7F6E `package.json` \u662F\u8BA9 TypeScript \u548C\u5F00\u53D1\u5DE5\u5177\u627E\u5230\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u7684\u5173\u952E\u3002\\n\\n1.  **`types` \u5B57\u6BB5**:\\n    - \u4F7F\u7528 `\\"types\\"` \u5B57\u6BB5\u6307\u5B9A\u4E3B\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u7684\u8DEF\u5F84\uFF0C**\u4E0D\u8981** \u4F7F\u7528 `\\"typings\\"`\u3002\\n    - _\u8865\u5145: `\\"types\\"` \u662F TypeScript \u5B98\u65B9\u63A8\u8350\u4E14\u66F4\u73B0\u4EE3\u7684\u5B57\u6BB5\u540D\u3002_\\n    - \u8BE5\u5B57\u6BB5\u5E94\u653E\u7F6E\u5728\u6240\u6709\u5B98\u65B9 `package.json` \u5C5E\u6027 (\u5982 `name`, `version`, `main`, `module`, `exports`) \u4E4B\u540E\uFF0C\u4F46\u5728\u81EA\u5B9A\u4E49\u5C5E\u6027\u4E4B\u524D\u3002\u63A8\u8350\u653E\u5728 `\\"dependencies\\"` \u548C/\u6216 `\\"devDependencies\\"` \u4E4B\u540E\u3002\\n2.  **\u5165\u53E3\u6587\u4EF6\u4E0E\u7C7B\u578B\u6587\u4EF6\u547D\u540D**:\\n    - \u5982\u679C\u5305\u7684\u5165\u53E3\u6587\u4EF6\u662F `index.js` (\u6216 `index.mjs` \u7B49)\uFF0C\u5219\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u5E94\u547D\u540D\u4E3A `index.d.ts` \u5E76\u653E\u7F6E\u5728 **\u5305\u7684\u6839\u76EE\u5F55**\u3002\\n    - \u5728\u8FD9\u79CD\u60C5\u51B5\u4E0B\uFF0C\u4F60 **\u4E0D\u9700\u8981** \u5728 `package.json` \u4E2D\u6DFB\u52A0 `\\"types\\"` \u5B57\u6BB5\uFF0CTypeScript \u4F1A\u6839\u636E `main` \u6216 `exports` \u5B57\u6BB5\u81EA\u52A8\u63A8\u65AD\u5E76\u627E\u5230\u540C\u540D\u7684 `.d.ts` \u6587\u4EF6\u3002\\n    - _\u8865\u5145: \u5229\u7528 TypeScript \u7684\u9ED8\u8BA4\u63A8\u65AD\u673A\u5236\u53EF\u4EE5\u7B80\u5316\u914D\u7F6E\u3002\u4F46\u5982\u679C\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u4E0D\u5728\u6839\u76EE\u5F55\u6216\u540D\u79F0\u4E0E\u5165\u53E3\u6587\u4EF6\u4E0D\u540C\uFF0C\u5219\u5FC5\u987B\u4F7F\u7528 `\\"types\\"` \u5B57\u6BB5\u663E\u5F0F\u6307\u5B9A\u3002_\\n3.  **`files` \u5B57\u6BB5**:\\n    - \u786E\u4FDD\u5C06\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6 (\u5982 `index.d.ts` \u6216 `dist/types/` \u76EE\u5F55) \u6DFB\u52A0\u5230 `package.json` \u7684 `\\"files\\"` \u6570\u7EC4\u4E2D\u3002\\n    - _\u8865\u5145: `\\"files\\"` \u5B57\u6BB5\u63A7\u5236\u54EA\u4E9B\u6587\u4EF6\u4F1A\u88AB\u5305\u542B\u5728\u6700\u7EC8\u53D1\u5E03\u7684 npm \u5305\u91CC\u3002\u5FD8\u8BB0\u6DFB\u52A0\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6\u4F1A\u5BFC\u81F4\u4F7F\u7528\u8005\u5B89\u88C5\u4E86\u4F60\u7684\u5305\u5374\u65E0\u6CD5\u83B7\u5F97\u7C7B\u578B\u652F\u6301\u3002_\\n\\n## \u7C7B\u578B\u5B9A\u4E49\u6700\u4F73\u5B9E\u8DF5 (Type Definition Best Practices)\\n\\n\u7F16\u5199\u6E05\u6670\u3001\u51C6\u786E\u3001\u6613\u4E8E\u4F7F\u7528\u7684\u7C7B\u578B\u662F\u6211\u4EEC\u7684\u76EE\u6807\u3002\\n\\n### \u7C7B\u578B\u547D\u540D\u4E0E\u98CE\u683C\\n\\n1.  **\u7C7B\u578B\u547D\u540D**:\\n    - \u7C7B\u578B\u540D\u79F0\u4E0D\u5E94\u5305\u542B\u547D\u540D\u7A7A\u95F4\u524D\u7F00\uFF0C\u4F8B\u5982\u4F7F\u7528 `type Options {}` \u800C\u4E0D\u662F `type FooOptions {}`\uFF0C\u9664\u975E\u786E\u5B9E\u5B58\u5728\u591A\u4E2A\u540C\u540D `Options` \u63A5\u53E3\u9700\u8981\u533A\u5206\u3002\\n    - \u907F\u514D\u4F7F\u7528\u7F29\u5199\uFF1A\u51FD\u6570\u53C2\u6570\u3001\u53D8\u91CF\u548C\u7C7B\u578B\u540D\u5E94\u4F7F\u7528\u5B8C\u6574\u5355\u8BCD\uFF0C\u5982 `function process(options: Options)` \u800C\u4E0D\u662F `function process(opts: Opts)`\u3002\\n    - \u63A5\u53E3\u540D\u79F0 **\u4E0D\u8981** \u52A0 `I` \u524D\u7F00\uFF1A\u4F7F\u7528 `Options` \u800C\u4E0D\u662F `IOptions`\u3002\\n    - _\u8865\u5145: \u8FD9\u4E9B\u7EA6\u5B9A\u63D0\u9AD8\u4E86\u4EE3\u7801\u7684\u53EF\u8BFB\u6027\u548C\u4E00\u81F4\u6027\u3002`I` \u524D\u7F00\u662F\u67D0\u4E9B\u8BED\u8A00 (\u5982 C#) \u7684\u4E60\u60EF\uFF0C\u4F46\u5728 TypeScript \u793E\u533A\u5DF2\u4E0D\u518D\u63A8\u8350\u3002_\\n2.  **\u6570\u7EC4\u7C7B\u578B**:\\n    - \u4F7F\u7528\u6570\u7EC4\u7C7B\u578B\u7B80\u5199\uFF1A`number[]` \u800C\u4E0D\u662F `Array<number>`\u3002\\n    - \u4F7F\u7528 `readonly` \u4FEE\u9970\u7B26\u8868\u793A\u53EA\u8BFB\u6570\u7EC4\uFF1A`readonly number[]` \u800C\u4E0D\u662F `ReadonlyArray<number>`\u3002\\n    - _\u8865\u5145: \u7B80\u5199\u5F62\u5F0F\u66F4\u7B80\u6D01\uFF0C`readonly T[]` \u662F TS \u5185\u7F6E\u7684\u3001\u66F4\u63A8\u8350\u7684\u53EA\u8BFB\u6570\u7EC4\u8868\u793A\u6CD5\u3002_\\n3.  **\u6CDB\u578B\u53D8\u91CF**:\\n    - \u5F53\u4E00\u4E2A\u65B9\u6CD5\u6216\u7C7B\u578B\u6709\u591A\u4E2A\u6CDB\u578B\u7C7B\u578B\u53D8\u91CF\u65F6\uFF0C\u5E94\u4F7F\u7528\u5177\u6709\u63CF\u8FF0\u6027\u7684\u540D\u79F0\uFF1A`type Mapper<Element, NewElement> = \u2026` \u800C\u4E0D\u662F `type Mapper<T, U> = \u2026`\u3002\\n    - _\u8865\u5145: \u867D\u7136 `T`, `U`, `K`, `V` \u662F\u5E38\u89C1\u7684\u6CDB\u578B\u53D8\u91CF\u540D\uFF0C\u4F46\u5728\u6709\u591A\u4E2A\u6CDB\u578B\u53C2\u6570\u65F6\uFF0C\u63CF\u8FF0\u6027\u540D\u79F0\u80FD\u663E\u8457\u63D0\u9AD8\u590D\u6742\u7C7B\u578B\u7684\u53EF\u8BFB\u6027\u3002_\\n4.  **\u4EE3\u7801\u683C\u5F0F**:\\n    - \u5BFC\u5165\u3001\u89E3\u6784\u8D4B\u503C\u548C\u5BF9\u8C61\u5B57\u9762\u91CF\u4E2D\uFF0C\u6807\u8BC6\u7B26\u5468\u56F4 **\u4E0D** \u5E94\u6709\u7A7A\u683C\uFF1A\u4F7F\u7528 `{foo}` \u800C\u4E0D\u662F `{ foo }`\u3002\\n    - _\u8865\u5145: \u8FD9\u662F\u8BB8\u591A\u6D41\u884C\u683C\u5F0F\u5316\u5DE5\u5177 (\u5982 Prettier) \u7684\u9ED8\u8BA4\u884C\u4E3A\uFF0C\u4FDD\u6301\u4E00\u81F4\u6027\u3002_\\n\\n### \u7C7B\u578B\u7CBE\u786E\u6027\\n\\n1.  **`unknown` vs `any`**:\\n    - \u5C3D\u53EF\u80FD\u4F7F\u7528 [`unknown` \u7C7B\u578B](https://www.typescriptlang.org/docs/handbook/release-notes/typescript-3-0.html#new-unknown-top-type)\u66FF\u4EE3 `any`\u3002\\n    - _\u8865\u5145: `any` \u4F1A\u5B8C\u5168\u7ED5\u8FC7\u7C7B\u578B\u68C0\u67E5\uFF0C\u662F\u7C7B\u578B\u5B89\u5168\u7684\u201C\u540E\u95E8\u201D\u3002`unknown` \u5219\u8868\u793A\u201C\u4EFB\u4F55\u7C7B\u578B\u90FD\u53EF\u4EE5\u8D4B\u7ED9\u6211\uFF0C\u4F46\u6211\u662F\u7C7B\u578B\u5B89\u5168\u7684\uFF0C\u4F60\u4E0D\u80FD\u76F4\u63A5\u64CD\u4F5C\u6211\uFF0C\u5FC5\u987B\u5148\u8FDB\u884C\u7C7B\u578B\u68C0\u67E5\u6216\u65AD\u8A00\u201D\u3002\u4F7F\u7528 `unknown` \u80FD\u5728\u4FDD\u6301\u7075\u6D3B\u6027\u7684\u540C\u65F6\u5F3A\u5236\u8FDB\u884C\u7C7B\u578B\u4FDD\u62A4\uFF0C\u63D0\u9AD8\u4EE3\u7801\u7684\u5065\u58EE\u6027\u3002_\\n2.  **\u907F\u514D\u5BBD\u6CDB\u7C7B\u578B**:\\n    - \u4E0D\u8981\u4F7F\u7528\u8FC7\u4E8E\u5BBD\u6CDB\u7684\u7C7B\u578B\uFF0C\u5982 `object` \u6216 `Function`\u3002\u5E94\u4F7F\u7528\u66F4\u5177\u4F53\u7684\u7C7B\u578B\u7B7E\u540D\uFF0C\u4F8B\u5982 `Record<string, number>` (\u8868\u793A\u952E\u4E3A\u5B57\u7B26\u4E32\u3001\u503C\u4E3A\u6570\u5B57\u7684\u5BF9\u8C61) \u6216 `(input: string) => boolean;` (\u8868\u793A\u63A5\u53D7\u4E00\u4E2A\u5B57\u7B26\u4E32\u53C2\u6570\u5E76\u8FD4\u56DE\u5E03\u5C14\u503C\u7684\u51FD\u6570)\u3002\\n    - _\u8865\u5145: `object` \u7C7B\u578B\u51E0\u4E4E\u4E0D\u63D0\u4F9B\u4EFB\u4F55\u6709\u7528\u7684\u7C7B\u578B\u4FE1\u606F\u3002`Function` \u7C7B\u578B\u540C\u6837\u65E0\u6CD5\u63CF\u8FF0\u51FD\u6570\u7684\u53C2\u6570\u548C\u8FD4\u56DE\u503C\u3002\u4F7F\u7528\u5177\u4F53\u7684\u7C7B\u578B\u7B7E\u540D\u80FD\u63D0\u4F9B\u66F4\u5F3A\u7684\u7C7B\u578B\u7EA6\u675F\u548C\u66F4\u597D\u7684\u5F00\u53D1\u4F53\u9A8C\u3002_\\n3.  **\u5BF9\u8C61\u7D22\u5F15\u7B7E\u540D**:\\n    - \u5BF9\u4E8E\u63A5\u53D7\u5177\u6709\u5B57\u7B26\u4E32\u7D22\u5F15\u7C7B\u578B\u7684\u5BF9\u8C61\u4F5C\u4E3A\u53C2\u6570\u65F6\uFF0C\u53EF\u4EE5\u4F7F\u7528 `Record<string, any>`\u3002\\n    - \u5BF9\u4E8E\u8FD4\u56DE\u6B64\u7C7B\u5BF9\u8C61\u65F6\uFF0C\u5E94\u4F7F\u7528 `Record<string, unknown>`\u3002\\n    - \u539F\u56E0\uFF1ATypeScript \u5BF9 `Record<string, any>` \u6709\u7279\u6B8A\u5904\u7406\uFF1A**\u4EFB\u4F55\u5BF9\u8C61\u7C7B\u578B\u90FD\u53EF\u4EE5\u8D4B\u503C\u7ED9\u5B83**\u3002\u8FD9\u4F7F\u5F97\u5B83\u5728\u4F5C\u4E3A\u51FD\u6570\u53C2\u6570\u65F6\u66F4\u5177\u7075\u6D3B\u6027\uFF08\u5C3D\u7BA1\u635F\u5931\u4E86\u4E00\u4E9B\u7C7B\u578B\u5B89\u5168\uFF09\u3002\u800C\u8FD4\u56DE `Record<string, unknown>` \u5219\u66F4\u5B89\u5168\uFF0C\u5F3A\u5236\u4F7F\u7528\u8005\u5728\u4F7F\u7528\u8FD4\u56DE\u503C\u4E4B\u524D\u8FDB\u884C\u7C7B\u578B\u68C0\u67E5\u3002\\n\\n### \u5F3A\u8C03\u53EA\u8BFB\u6027 (Prefer Read-only Values)\\n\\n\u5F53\u67D0\u4E2A\u503C\uFF08\u901A\u5E38\u662F\u51FD\u6570\u8FD4\u56DE\u503C\u6216\u914D\u7F6E\u9009\u9879\uFF09\u4E0D\u5E94\u8BE5\u88AB\u4FEE\u6539\u65F6\uFF0C\u660E\u786E\u5730\u5C06\u5176\u6807\u8BB0\u4E3A\u53EA\u8BFB\u3002\u719F\u6089 `readonly` \u5173\u952E\u5B57\u5728[\u5C5E\u6027](https://www.typescriptlang.org/docs/handbook/interfaces.html#readonly-properties)\u548C[\u6570\u7EC4/\u5143\u7EC4\u7C7B\u578B](https://github.com/Microsoft/TypeScript/wiki/What\'s-new-in-TypeScript#improvements-for-readonlyarray-and-readonly-tuples)\u4E2D\u7684\u5E94\u7528\u3002\u6B64\u5916\uFF0C\u8FD8\u6709\u4E00\u4E2A [`Readonly<T>` \u6620\u5C04\u7C7B\u578B](https://basarat.gitbooks.io/typescript/docs/types/readonly.html)\u53EF\u4EE5\u5C06\u4E00\u4E2A\u7C7B\u578B\u7684\u6240\u6709\u5C5E\u6027\u6807\u8BB0\u4E3A `readonly`\u3002\\n\\n**\u4E4B\u524D**:\\n\\n```ts\\ntype Point = {\\n  x: number;\\n  y: number;\\n  children: Point[];\\n};\\n```\\n\\n**\u4E4B\u540E**:\\n\\n```ts\\ntype Point = {\\n  readonly x: number;\\n  readonly y: number;\\n  readonly children: readonly Point[];\\n};\\n\\n// \u6216\u8005\u5BF9\u4E8E\u6574\u4E2A\u5BF9\u8C61\u53CA\u5176\u5D4C\u5957\u5C5E\u6027\\ntype DeepReadonlyPoint = Readonly<{\\n  x: number;\\n  y: number;\\n  children: ReadonlyArray<DeepReadonlyPoint>; // \u6CE8\u610F\u9012\u5F52\u5E94\u7528\\n}>;\\n```\\n\\n_\u8865\u5145: \u4F7F\u7528 `readonly` \u6709\u52A9\u4E8E\u5B9E\u73B0\u4E0D\u53EF\u53D8\u6027 (Immutability)\uFF0C\u8FD9\u53EF\u4EE5\u51CF\u5C11\u526F\u4F5C\u7528\uFF0C\u4F7F\u4EE3\u7801\u72B6\u6001\u66F4\u53EF\u9884\u6D4B\uFF0C\u7279\u522B\u662F\u5728\u5904\u7406\u590D\u6742\u6570\u636E\u7ED3\u6784\u6216\u8FDB\u884C\u51FD\u6570\u5F0F\u7F16\u7A0B\u65F6\u3002_\\n\\n### \u663E\u5F0F\u5BFC\u5165\u7C7B\u578B (Import Types Explicitly)\\n\\n\u9664\u4E86 JavaScript \u5185\u7F6E\u7C7B\u578B (\u5982 `string`, `Promise`) \u6216\u65E0\u6CD5\u901A\u8FC7 `import` \u5BFC\u5165\u7684\u5168\u5C40\u7C7B\u578B (\u4F8B\u5982\u67D0\u4E9B\u73AF\u5883\u7279\u5B9A\u7684\u5168\u5C40\u53D8\u91CF)\uFF0C\u90FD **\u4E0D\u8981** \u4F9D\u8D56\u9690\u5F0F\u7684\u5168\u5C40\u7C7B\u578B\u3002\\n\\n**\u4E4B\u524D**: (\u5047\u8BBE `Electron` \u7C7B\u578B\u88AB\u5168\u5C40\u6CE8\u5165)\\n\\n```ts\\nexport function getWindow(): Electron.BrowserWindow;\\n```\\n\\n**\u4E4B\u540E**: (\u660E\u786E\u5BFC\u5165\u6240\u9700\u7C7B\u578B)\\n\\n```ts\\nimport { BrowserWindow } from \\"electron\\"; // \u9700\u8981\u5B89\u88C5 @types/electron\\n\\nexport function getWindow(): BrowserWindow;\\n```\\n\\n_\u8865\u5145: \u663E\u5F0F\u5BFC\u5165\u4F7F\u4EE3\u7801\u7684\u4F9D\u8D56\u5173\u7CFB\u66F4\u6E05\u6670\uFF0C\u907F\u514D\u4E86\u5168\u5C40\u547D\u540D\u7A7A\u95F4\u7684\u6C61\u67D3\uFF0C\u5E76\u4E14\u66F4\u7B26\u5408 ES Module \u7684\u89C4\u8303\u3002_\\n\\n### \u53EF\u8BFB\u7684\u547D\u540D\u5BFC\u5165 (Readable Named Imports)\\n\\n\u5F53\u5BFC\u5165\u7684\u7C7B\u578B\u540D\u79F0\u53EF\u80FD\u4E0E\u5176\u4ED6\u5C40\u90E8\u53D8\u91CF\u6216\u7C7B\u578B\u51B2\u7A81\uFF0C\u6216\u8005\u540D\u79F0\u672C\u8EAB\u4E0D\u591F\u6E05\u6670\u65F6\uFF0C\u4F7F\u7528 `as` \u5173\u952E\u5B57\u8FDB\u884C\u91CD\u547D\u540D\uFF0C\u63D0\u4F9B\u4E00\u4E2A\u66F4\u5177\u53EF\u8BFB\u6027\u7684\u522B\u540D\u3002\\n\\n**\u4E4B\u524D**: (\u5982\u679C `Writable` \u5728\u5F53\u524D\u4F5C\u7528\u57DF\u53EF\u80FD\u5F15\u8D77\u6B67\u4E49)\\n\\n```ts\\nimport { Writable } from \\"node:stream\\";\\n\\nexport function createLogStream(): Writable;\\n```\\n\\n**\u4E4B\u540E**: (\u4F7F\u7528\u522B\u540D\u63D0\u9AD8\u6E05\u6670\u5EA6)\\n\\n```ts\\nimport { Writable as WritableStream } from \\"node:stream\\"; // \u9700\u8981 @types/node\\n\\nexport function createLogStream(): WritableStream;\\n```\\n\\n_\u8865\u5145: \u597D\u7684\u547D\u540D\u662F\u4EE3\u7801\u81EA\u6587\u6863\u5316\u7684\u91CD\u8981\u90E8\u5206\u3002\u5BF9\u4E8E\u6765\u81EA Node.js \u6216\u5176\u4ED6\u5E93\u7684\u901A\u7528\u540D\u79F0 (\u5982 `Stream`, `Buffer`, `EventEmitter`)\uFF0C\u6DFB\u52A0\u4E0A\u4E0B\u6587\u76F8\u5173\u7684\u540E\u7F00 (\u5982 `WritableStream`, `FileBuffer`, `MyEventEmitter`) \u901A\u5E38\u662F\u4E2A\u597D\u4E3B\u610F\u3002_\\n\\n## \u4F7F\u7528 TSDoc \u7F16\u5199\u6587\u6863\u6CE8\u91CA (Documenting with TSDoc)\\n\\n\u6240\u6709\u5BFC\u51FA\u7684\u5B9A\u4E49 (\u51FD\u6570\u3001\u7C7B\u3001\u7C7B\u578B\u3001\u63A5\u53E3\u3001\u5E38\u91CF\u7B49) \u90FD\u5E94\u4F7F\u7528 [TSDoc](https://github.com/Microsoft/tsdoc) \u6807\u51C6\u8FDB\u884C\u6587\u6863\u6CE8\u91CA\u3002\u4F60\u53EF\u4EE5\u4ECE\u9879\u76EE\u7684 `README.md` \u6587\u4EF6\u4E2D\u501F\u9274\u63CF\u8FF0\u6027\u6587\u5B57\u3002\\n\\n**\u793A\u4F8B**:\\n\\n````ts\\n/**\\n * Represents configuration options for the \'add\' function.\\n */\\nexport type Options = {\\n  /**\\n   * Allow negative numbers in the calculation.\\n   *\\n   * @default true\\n   */\\n  readonly allowNegative?: boolean;\\n\\n  /**\\n   * Specifies whether the ultimate foo feature is enabled.\\n   *\\n   * Note: Only use this feature for good, never for evil.\\n   *\\n   * @default false\\n   */\\n  readonly hasFoo?: boolean;\\n\\n  /**\\n   * The directory path where the result should be saved.\\n   *\\n   * Defaults to the user\'s downloads directory (see [https://example.com](https://example.com) for details).\\n   *\\n   * @example\\n   * ```typescript\\n   * import add from \'my-add-package\';\\n   *\\n   * add(1, 2, {saveDirectory: \'/my/awesome/dir\'});\\n   * ```\\n   */\\n  readonly saveDirectory?: string;\\n};\\n\\n/**\\n * Adds two numbers together.\\n * This function serves as a basic example for demonstrating TSDoc usage.\\n *\\n * @param x - The first number to add. Must be a finite number.\\n * @param y - The second number to add. Must be a finite number.\\n * @param options - Optional configuration for the addition process.\\n * @returns The sum of `x` and `y`.\\n *\\n * @throws {TypeError} If either x or y is not a finite number.\\n */\\nexport default function add(x: number, y: number, options?: Options): number;\\n````\\n\\n**TSDoc \u6CE8\u91CA\u89C4\u8303**:\\n\\n- \u6CE8\u91CA\u5757\u4EE5 `/**` \u5F00\u59CB\uFF0C\u4EE5 `*/` \u7ED3\u675F\u3002\\n- \u6CE8\u91CA\u5185\u5BB9 **\u4E0D\u8981** \u4EE5 `*` \u5F00\u5934\u3002\\n- \u6CE8\u91CA\u6587\u672C **\u4E0D\u8981** \u8FDB\u884C\u786C\u6362\u884C (hard-wrap)\uFF0C\u8BA9\u7F16\u8F91\u5668\u6216\u6E32\u67D3\u5DE5\u5177\u81EA\u52A8\u5904\u7406\u3002\\n- \u5728\u7C7B\u578B/\u63A5\u53E3\u7684\u5C5E\u6027\u6587\u6863\u4E4B\u95F4\u4FDD\u7559\u4E00\u4E2A\u7A7A\u884C\u3002\\n- \u53E5\u5B50\u5E94\u4EE5\u5927\u5199\u5B57\u6BCD\u5F00\u5934\uFF0C\u4EE5\u53E5\u70B9 (`.`) \u7ED3\u675F\u3002\\n- \u51FD\u6570/\u65B9\u6CD5\u7684\u4E3B\u63CF\u8FF0\u540E\u9762\u5E94\u6709\u4E00\u4E2A\u7A7A\u884C\uFF0C\u7136\u540E\u662F `@param`, `@returns` \u7B49\u6807\u7B7E\u3002\\n- \u6240\u6709\u53C2\u6570 (`@param`) \u548C\u8FD4\u56DE\u503C (`@returns`) \u90FD\u5E94\u88AB\u6587\u6863\u5316\u3002\\n- `@param` \u540E\u9762\u8DDF\u7740\u53C2\u6570\u540D\uFF0C\u7136\u540E\u662F\u4E00\u4E2A\u7834\u6298\u53F7 (`-`)\uFF0C\u6700\u540E\u662F\u53C2\u6570\u63CF\u8FF0\u3002\\n- `@param` **\u4E0D\u5E94** \u5305\u542B\u53C2\u6570\u7684\u7C7B\u578B\u4FE1\u606F (\u7C7B\u578B\u4FE1\u606F\u7531 TypeScript \u4EE3\u7801\u672C\u8EAB\u63D0\u4F9B)\u3002\\n- \u5982\u679C\u53C2\u6570\u63CF\u8FF0\u4EC5\u4EC5\u662F\u91CD\u590D\u53C2\u6570\u540D (\u4F8B\u5982 `@param options - The options object`)\uFF0C\u53EF\u4EE5\u7701\u7565\u63CF\u8FF0 (\u9664\u975E\u53C2\u6570\u540D\u672C\u8EAB\u4E0D\u591F\u6E05\u6670)\u3002\u5BF9\u4E8E\u5E38\u89C1\u7684 `options` \u53C2\u6570\uFF0C\u901A\u5E38\u4E0D\u9700\u8981\u989D\u5916\u63CF\u8FF0\u3002\\n- \u5982\u679C\u51FD\u6570\u8FD4\u56DE `void` \u6216\u5305\u88F9 `void` \u7684 Promise (\u5982 `Promise<void>`)\uFF0C\u53EF\u4EE5\u7701\u7565 `@returns` \u6807\u7B7E\u3002\\n- \u4F7F\u7528 `@returns` \u800C\u4E0D\u662F `@return`\u3002\\n- `@returns` \u7684\u63CF\u8FF0\u5E94\u6E05\u6670\u8BF4\u660E\u8FD4\u56DE\u503C\u7684\u542B\u4E49\uFF0C\u9664\u975E\u8FD4\u56DE\u503C\u7684\u7C7B\u578B\u672C\u8EAB\u5DF2\u7ECF\u8DB3\u591F\u6E05\u6670\uFF0C\u5426\u5219**\u4E0D\u8981**\u7B80\u5355\u91CD\u590D\u7C7B\u578B\u4FE1\u606F (\u4F8B\u5982\uFF0C\u5C06 `@returns A boolean of whether it was enabled.` \u6539\u8FDB\u4E3A `@returns Whether it was enabled.`)\u3002\\n- \u4F7F\u7528 `@default` \u6807\u7B7E\u8BB0\u5F55\u9009\u9879\u6216\u53C2\u6570\u7684\u9ED8\u8BA4\u503C\u3002\u7531\u4E8E\u7C7B\u578B\u5B9A\u4E49\u672C\u8EAB\u4E0D\u80FD\u6307\u5B9A\u9ED8\u8BA4\u503C\uFF0C\u8FD9\u4E2A\u6807\u7B7E\u975E\u5E38\u91CD\u8981\u3002\u5982\u679C\u9ED8\u8BA4\u503C\u9700\u8981\u6587\u5B57\u63CF\u8FF0\u800C\u4E0D\u662F\u7B80\u5355\u7684\u5B57\u9762\u91CF\uFF0C\u53EF\u4EE5\u4F7F\u7528 `Default: Some description.` \u7684\u683C\u5F0F\u3002\\n- \u5982\u679C\u5305\u542B `@example` \u6807\u7B7E\uFF0C\u5176\u4E0A\u65B9\u5E94\u6709\u4E00\u4E2A\u7A7A\u884C\u3002\u4EE3\u7801\u793A\u4F8B\u5E94\u4F7F\u7528 Markdown \u7684\u4EE3\u7801\u5757 (\u4E09\u4E2A\u53CD\u5F15\u53F7 ```) \u5305\u88F9\uFF0C\u5E76\u6700\u597D\u6307\u5B9A\u8BED\u8A00 (\u5982 `typescript`\u6216`javascript`)\u3002\\n- \u73AF\u5883\u58F0\u660E (ambient declarations, `.d.ts` \u6587\u4EF6\u4E2D\u7684\u5185\u5BB9) \u4E0D\u80FD\u6709\u9ED8\u8BA4\u53C2\u6570\u503C\u3002\u5982\u679C\u51FD\u6570\u5B9E\u73B0\u4E2D\u6709\u9ED8\u8BA4\u53C2\u6570\uFF0C\u5E94\u5728 `@param` \u7684\u63CF\u8FF0\u4E2D\u6216\u4F7F\u7528 `@default` \u6807\u7B7E\u8FDB\u884C\u8BF4\u660E\u3002\\n\\n_\u8865\u5145: \u9075\u5FAA TSDoc \u89C4\u8303\u4F7F\u5F97\u6587\u6863\u6CE8\u91CA\u80FD\u591F\u88AB\u5404\u79CD\u5DE5\u5177 (\u5982 VS Code \u7684 IntelliSense\u3001TypeDoc \u7B49\u6587\u6863\u751F\u6210\u5668) \u6B63\u786E\u89E3\u6790\u548C\u5C55\u793A\uFF0C\u6781\u5927\u5730\u63D0\u5347\u4E86\u5E93\u7684\u4F7F\u7528\u8005\u4F53\u9A8C\u3002_\\n\\n### \u4EE3\u7801\u793A\u4F8B (Code Examples in Docs)\\n\\n- \u5C3D\u53EF\u80FD\u591A\u5730\u5305\u542B\u4EE3\u7801\u793A\u4F8B\uFF0C\u53EF\u4EE5\u4ECE `README.md` \u6216\u5B9E\u9645\u7528\u4F8B\u4E2D\u63D0\u53D6\u3002\\n- \u4EE3\u7801\u793A\u4F8B\u5E94\u8BE5\u662F\u529F\u80FD\u5B8C\u6574\u7684\uFF0C\u80FD\u591F\u76F4\u63A5\u8FD0\u884C (\u6216\u7A0D\u4F5C\u4FEE\u6539\u5373\u53EF\u8FD0\u884C)\uFF0C\u5E76\u5E94\u5305\u542B\u5FC5\u8981\u7684 `import` \u8BED\u53E5\u3002\\n- _\u8865\u5145: \u597D\u7684\u4EE3\u7801\u793A\u4F8B\u662F\u5B66\u4E60\u5982\u4F55\u4F7F\u7528\u5E93\u7684\u6700\u5FEB\u65B9\u5F0F\u3002\u786E\u4FDD\u793A\u4F8B\u6E05\u6670\u3001\u51C6\u786E\u4E14\u6DB5\u76D6\u5E38\u89C1\u7528\u4F8B\u3002_\\n\\n## \u4F7F\u7528 tsd \u8FDB\u884C\u7C7B\u578B\u6D4B\u8BD5 (Testing Types with tsd)\\n\\n\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6 (`.d.ts`) \u672C\u8EAB\u4E5F\u9700\u8981\u6D4B\u8BD5\uFF01\u8FD9\u786E\u4FDD\u4E86\u7C7B\u578B\u5B9A\u4E49\u7684\u51C6\u786E\u6027\uFF0C\u80FD\u6355\u83B7\u8BF8\u5982\u7C7B\u578B\u8FC7\u4E8E\u5BBD\u6CDB\u3001\u8FC7\u7A84\u3001\u9519\u8BEF\u6216\u4E0E\u5B9E\u9645 JavaScript \u5B9E\u73B0\u4E0D\u7B26\u7B49\u95EE\u9898\u3002\u63A8\u8350\u4F7F\u7528 [`tsd`](https://github.com/SamVerschueren/tsd) \u8FD9\u4E2A\u5DE5\u5177\u6765\u8FDB\u884C\u7C7B\u578B\u6D4B\u8BD5\u3002\\n\\n**\u96C6\u6210\u793A\u4F8B**: \u67E5\u770B [sindresorhus/filled-array \u7684\u8FD9\u4E2A\u63D0\u4EA4](https://github.com/sindresorhus/filled-array/commit/aae7539cb32f163cb063499664b012d0b04b3104)\uFF0C\u4E86\u89E3\u5982\u4F55\u5C06 `tsd` \u96C6\u6210\u5230\u9879\u76EE\u4E2D (\u901A\u5E38\u662F\u5728 `package.json` \u7684 `scripts` \u4E2D\u6DFB\u52A0\u4E00\u4E2A\u6D4B\u8BD5\u547D\u4EE4\uFF0C\u5E76\u521B\u5EFA\u4E00\u4E2A\u7C7B\u578B\u6D4B\u8BD5\u6587\u4EF6)\u3002\\n\\n**\u6D4B\u8BD5\u6587\u4EF6\u793A\u4F8B**:\\n\\n```ts\\n// test/index.test-d.ts \u6216\u7C7B\u4F3C\u8DEF\u5F84\\nimport { expectType, expectError, expectAssignable } from \\"tsd\\";\\nimport delay, { type Options } from \\"../index.js\\"; // \u5047\u8BBE index.js \u662F\u5165\u53E3\\n\\n// \u6D4B\u8BD5\u6210\u529F\u6848\u4F8B (\u7C7B\u578B\u5339\u914D)\\nexpectType<Promise<void>>(delay(200));\\nexpectType<Promise<string>>(delay(200, { value: \\"\uD83E\uDD84\\" }));\\nexpectType<Promise<number>>(delay(200, { value: 0 }));\\n\\n// \u6D4B\u8BD5 Promise<never> for reject\\nexpectType<Promise<never>>(delay.reject(200, { value: \\"\uD83E\uDD84\\" }));\\nexpectType<Promise<never>>(delay.reject(200, { value: 0 }));\\n\\n// \u6D4B\u8BD5\u51FD\u6570\u7684\u53EF\u8D4B\u503C\u6027 (\u53C2\u6570\u7C7B\u578B\u68C0\u67E5)\\nconst options: Options = { value: \\"test\\" };\\nexpectAssignable<Options>(options);\\n// expectAssignable<Options>({unknownProp: 1}); // \u8FD9\u4F1A\u62A5\u9519\uFF0C\u56E0\u4E3A unknownProp \u4E0D\u5728 Options \u7C7B\u578B\u4E2D\\n\\n// \u6D4B\u8BD5\u9519\u8BEF\u6848\u4F8B (\u7C7B\u578B\u4E0D\u5339\u914D\u6216\u7528\u6CD5\u9519\u8BEF)\\nexpectError(delay(\\"200\\")); // \u53C2\u6570\u7C7B\u578B\u9519\u8BEF\\nexpectError(delay(100, { value: true })); // value \u7C7B\u578B\u9519\u8BEF (\u5047\u8BBE\u5B83\u53EA\u63A5\u53D7 string/number)\\n\\n// \u6D4B\u8BD5\u53EA\u8BFB\u5C5E\u6027\\nconst resultPromise = delay(100, { value: \\"hello\\" });\\nexpectType<Promise<string>>(resultPromise);\\n// resultPromise.value = \'world\'; // \u5982\u679C Promise<string> \u672C\u8EAB\u6CA1\u6709\u7279\u6B8A\u5904\u7406\uFF0C\u8FD9\u884C\u4F1A\u62A5\u9519\\n// \u5BF9\u4E8E\u8FD4\u56DE\u7684\u5BF9\u8C61\uFF0C\u6D4B\u8BD5\u5176\u5C5E\u6027\u662F\u5426\u53EA\u8BFB\\n// const resultObj = await someFuncReturningReadonlyObject();\\n// expectError(resultObj.someProp = \'new value\'); // \u5982\u679C someProp \u662F readonly\\n```\\n\\n**\u7C7B\u578B\u6D4B\u8BD5\u6CE8\u610F\u4E8B\u9879**:\\n\\n- \u7C7B\u578B\u6D4B\u8BD5\u6587\u4EF6\u901A\u5E38\u547D\u540D\u4E3A `*.test-d.ts` (\u4F8B\u5982 `index.test-d.ts`)\uFF0C\u653E\u5728 `test` \u6216 `tests` \u76EE\u5F55\u4E0B\u3002\\n- `tsd` \u652F\u6301\u5728\u6D4B\u8BD5\u6587\u4EF6\u4E2D\u4F7F\u7528\u9876\u5C42 `await` (Top-Level Await)\u3002\\n- **\u91CD\u8981**: \u5728\u6D4B\u8BD5\u8FD4\u56DE Promise \u7684\u51FD\u6570\u65F6\uFF0C**\u4E0D\u8981** \u5728 `expectType` \u4E2D\u4F7F\u7528 `await` \u5173\u952E\u5B57\u3002\u5E94\u76F4\u63A5\u65AD\u8A00\u8FD4\u56DE\u503C\u7684\u7C7B\u578B\u662F `Promise<ExpectedType>`\uFF0C\u5982 `expectType<Promise<string>>(func())`\u3002\\n  - _\u539F\u56E0: \u5982\u679C\u4F60\u5199 `expectType<string>(await func())`\uFF0C\u5373\u4F7F `func` \u610F\u5916\u5730\u8FD4\u56DE\u4E86\u4E00\u4E2A\u975E Promise \u7684\u503C `string`\uFF0C`await` \u4E5F\u4F1A\u6B63\u5E38\u5DE5\u4F5C (\u5B83\u4F1A\u76F4\u63A5\u8FD4\u56DE\u503C)\uFF0C\u5BFC\u81F4\u6D4B\u8BD5\u901A\u8FC7\uFF0C\u4F46\u7C7B\u578B\u5B9A\u4E49 (\u58F0\u660E\u8FD4\u56DE `Promise<string>`) \u5B9E\u9645\u4E0A\u662F\u9519\u8BEF\u7684\u3002\u76F4\u63A5\u6D4B\u8BD5 `Promise<ExpectedType>` \u80FD\u786E\u4FDD\u51FD\u6570\u786E\u5B9E\u8FD4\u56DE\u4E86\u4E00\u4E2A Promise\u3002_\\n- \u5F53\u9700\u8981\u5411\u88AB\u6D4B\u8BD5\u51FD\u6570\u4F20\u9012\u5B57\u9762\u91CF\u7C7B\u578B\u6216\u53EA\u8BFB\u7C7B\u578B\u7684\u503C\u65F6\uFF0C\u53EF\u4EE5\u4F7F\u7528 [**`const` \u65AD\u8A00**](https://www.typescriptlang.org/docs/handbook/release-notes/typescript-3-4.html#const-assertions) (as const)\u3002\u8FD9\u4F1A\u544A\u8BC9 TypeScript \u5C06\u7C7B\u578B\u63A8\u65AD\u4E3A\u6700\u7A84\u7684\u5B57\u9762\u91CF\u7C7B\u578B\u6216\u53EA\u8BFB\u7C7B\u578B\u3002\\n\\n  ```ts\\n  import myLib from \\"./my-lib\\";\\n  import { expectType } from \\"tsd\\";\\n\\n  // \u5047\u8BBE myLib.process \u9700\u8981\u4E00\u4E2A\u5B57\u9762\u91CF\u7C7B\u578B \'literal\' \u6216 \'const\'\\n  const config = { type: \\"literal\\" } as const; // \'as const\' \u4F7F type \u6210\u4E3A \'literal\' \u7C7B\u578B\\n  expectType<void>(myLib.process(config));\\n\\n  const readonlyArray = [\\"a\\", \\"b\\"] as const; // \u63A8\u65AD\u4E3A readonly [\'a\', \'b\']\\n  expectType<readonly string[]>(myLib.handleArray(readonlyArray));\\n  ```\\n\\n- \u9002\u5F53\u65F6\uFF0C\u4F7F\u7528 `expectError()` \u6765\u9A8C\u8BC1\u4E0D\u6B63\u786E\u7684\u7528\u6CD5\u786E\u5B9E\u4F1A\u5BFC\u81F4 TypeScript \u7F16\u8BD1\u9519\u8BEF\u3002\u8FD9\u6709\u52A9\u4E8E\u786E\u4FDD\u4F60\u7684\u7C7B\u578B\u5B9A\u4E49\u4E0D\u4F1A\u8FC7\u4E8E\u5BBD\u677E\u3002\\n- \u4F7F\u7528 `expectAssignable<Target>(source)` \u6765\u6D4B\u8BD5 `source` \u7C7B\u578B\u7684\u503C\u662F\u5426\u53EF\u4EE5\u8D4B\u503C\u7ED9 `Target` \u7C7B\u578B\u7684\u53D8\u91CF\uFF0C\u8FD9\u5BF9\u4E8E\u68C0\u67E5\u63A5\u53E3\u517C\u5BB9\u6027\u5F88\u6709\u7528\u3002\\n\\n_\u8865\u5145: `tsd` \u6D4B\u8BD5\u662F\u7C7B\u578B\u5B9A\u4E49\u7684\u201C\u5355\u5143\u6D4B\u8BD5\u201D\u3002\u5B83\u4E0D\u8FD0\u884C\u5B9E\u9645\u4EE3\u7801\uFF0C\u800C\u662F\u5229\u7528 TypeScript \u7F16\u8BD1\u5668\u6765\u68C0\u67E5\u7C7B\u578B\u58F0\u660E\u662F\u5426\u7B26\u5408\u9884\u671F\u3002\u8FD9\u5BF9\u4E8E\u7EF4\u62A4\u9AD8\u8D28\u91CF\u3001\u53EF\u9760\u7684\u7C7B\u578B\u5B9A\u4E49\u81F3\u5173\u91CD\u8981\uFF0C\u5C24\u5176\u662F\u5728\u5E93\u4EE3\u7801\u6216\u7C7B\u578B\u5B9A\u4E49\u53D1\u751F\u53D8\u66F4\u65F6\u3002_\\n\\n## \u603B\u7ED3\\n\\n\u4E3A npm \u5305\u63D0\u4F9B\u9AD8\u8D28\u91CF\u7684 TypeScript \u7C7B\u578B\u5B9A\u4E49\u662F\u73B0\u4EE3\u524D\u7AEF\u548C Node.js \u5F00\u53D1\u4E2D\u7684\u4E00\u9879\u91CD\u8981\u5B9E\u8DF5\u3002\u9075\u5FAA\u672C\u6307\u5357\u4E2D\u7684\u7EA6\u5B9A\u548C\u6700\u4F73\u5B9E\u8DF5\uFF0C\u53EF\u4EE5\u5E2E\u52A9\u4F60\u521B\u5EFA\u51FA\u6E05\u6670\u3001\u51C6\u786E\u3001\u6613\u4E8E\u4F7F\u7528\u4E14\u5065\u58EE\u7684\u7C7B\u578B\u5B9A\u4E49\uFF0C\u4ECE\u800C\uFF1A\\n\\n- **\u63D0\u5347\u5F00\u53D1\u8005\u4F53\u9A8C (DX)**\uFF1A\u63D0\u4F9B\u7CBE\u51C6\u7684\u81EA\u52A8\u8865\u5168\u548C\u7C7B\u578B\u63D0\u793A\u3002\\n- **\u589E\u5F3A\u4EE3\u7801\u5065\u58EE\u6027**: \u5728\u7F16\u8BD1\u65F6\u6355\u83B7\u6F5C\u5728\u7684\u7C7B\u578B\u9519\u8BEF\u3002\\n- **\u6539\u5584\u53EF\u7EF4\u62A4\u6027**: \u7C7B\u578B\u5B9A\u4E49\u672C\u8EAB\u5C31\u662F\u4E00\u79CD\u7CBE\u786E\u7684 API \u6587\u6863\u3002\\n- **\u4FC3\u8FDB\u5E93\u7684\u91C7\u7528**: \u826F\u597D\u7684\u7C7B\u578B\u652F\u6301\u662F\u8BB8\u591A\u5F00\u53D1\u8005\u9009\u62E9\u5E93\u7684\u91CD\u8981\u56E0\u7D20\u3002\\n\\n\u6295\u5165\u65F6\u95F4\u7F16\u5199\u548C\u7EF4\u62A4\u9AD8\u8D28\u91CF\u7684 `.d.ts` \u6587\u4EF6\uFF0C\u662F\u5BF9\u4F60\u7684\u5E93\u7528\u6237\u6700\u597D\u7684\u6295\u8D44\u4E4B\u4E00\u3002"},{"id":"/2025/04/05/\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","metadata":{"permalink":"/transblog/2025/04/05/\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","source":"@site/blog-translated/2025/04-05-\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357.md","title":"\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","description":"- \u539F\u6587\u94FE\u63A5\uFF1A https://gist.github.com/sindresorhus/a39789f98801d908bbc7ff3ecc99d99c","date":"2025-04-05T05:28:47.000Z","tags":[{"inline":true,"label":"ESM","permalink":"/transblog/tags/esm"}],"readingTime":18.71,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"\u7EAF ESM \u5305\uFF1A\u73B0\u4EE3 JavaScript \u6A21\u5757\u5316\u6307\u5357","date":"2025-04-05T05:28:47.000Z","draft":false,"tags":["ESM"]},"unlisted":false,"prevItem":{"title":"TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357","permalink":"/transblog/2025/04/15/TypeScript \u7C7B\u578B\u5B9A\u4E49\u98CE\u683C\u6307\u5357"}},"content":"> - \u539F\u6587\u94FE\u63A5\uFF1A https://gist.github.com/sindresorhus/a39789f98801d908bbc7ff3ecc99d99c\\n> - \u673A\u5668\u7FFB\u8BD1\uFF1A Gemini 2.5 Pro Preview\\n> - \u63D0\u793A\u8BCD\uFF1A \u7FFB\u8BD1\u4EE5\u4E0B\u6587\u6863\uFF0C\u5E76\u4E14\u7ED3\u5408\u4F60\u7684\u524D\u7AEF\u5F00\u53D1\u4E13\u4E1A\u77E5\u8BC6\u8865\u5145\u76F8\u5173\u7684\u77E5\u8BC6\u70B9\u8BF4\u660E\uFF0C\u5BF9\u6587\u7AE0\u5185\u5BB9\u8FDB\u884C\u7ED3\u6784\u5316\uFF0C\u4EE5 Markdown \u683C\u5F0F\u8FD4\u56DE\uFF0C\u6587\u5B57\u98CE\u683C\u662F\u6280\u672F\u535A\u5BA2\u3002\\n> - \u7FFB\u8BD1\u7406\u7531\uFF1A\u8D8A\u6765\u8D8A\u591A\u7684\u5E93\u5F00\u53D1\u8005\u8BB2\u81EA\u5DF1\u7684\u5305\u76F4\u63A5\u6253\u5305\u6210\u7EAF ESM \u5F62\u5F0F\uFF0C\u5E76\u4E14\u6307\u5411\u8FD9\u4E2A\u6587\u6863\uFF0C\u8BA9\u5E93\u4F7F\u7528\u8005\u4E5F\u5C3D\u5FEB\u8FC1\u79FB\u5230 ESM\u3002\\n\\n\x3c!--truncate--\x3e\\n\\n## \u6838\u5FC3\u95EE\u9898\uFF1A\u65E0\u6CD5\u518D\u4F7F\u7528 `require()`\\n\\n**\u5173\u952E\u70B9**\uFF1A\u4E00\u4E2A Pure ESM \u5305\u4E0D\u80FD\u518D\u901A\u8FC7 CommonJS \u7684 `require()` \u51FD\u6570\u6765\u540C\u6B65\u5BFC\u5165\u3002\\n\\n```javascript\\n// \u274C \u8FD9\u79CD\u65B9\u5F0F\u5728 CommonJS \u9879\u76EE\u4E2D\u4F1A\u62A5\u9519\\n// const foo = require(\'pure-esm-package\');\\n\\n// \u2705 \u9700\u8981\u6539\u7528 ESM \u7684 import \u8BED\u6CD5\\n// import foo from \'pure-esm-package\';\\n```\\n\\n\u8FD9\u79CD\u8F6C\u53D8\u662F JavaScript \u751F\u6001\u7CFB\u7EDF\u9010\u6B65\u62E5\u62B1\u5B98\u65B9\u6807\u51C6\u6A21\u5757\u7CFB\u7EDF\u7684\u4E00\u90E8\u5206\u3002\u867D\u7136\u5E26\u6765\u4E86\u9635\u75DB\uFF0C\u4F46\u957F\u8FDC\u6765\u770B\uFF0C\u5B83\u7EDF\u4E00\u4E86\u524D\u540E\u7AEF\u7684\u6A21\u5757\u89C4\u8303\uFF0C\u5E26\u6765\u4E86\u8BF8\u591A\u597D\u5904\u3002\\n\\n## \u5982\u4F55\u5E94\u5BF9 Pure ESM \u5305\uFF1F\\n\\n\u9762\u5BF9\u8FD9\u79CD\u60C5\u51B5\uFF0C\u4F60\u6709\u4EE5\u4E0B\u51E0\u79CD\u9009\u62E9\uFF1A\\n\\n1.  **\u8FC1\u79FB\u4F60\u7684\u9879\u76EE\u5230 ESM (\u5F3A\u70C8\u63A8\u8350)**\uFF1A\\n\\n    - **\u65B9\u6CD5**\uFF1A\u5728\u4F60\u7684\u4EE3\u7801\u4E2D\u4F7F\u7528 `import foo from \'pure-esm-package\'` \u66FF\u4EE3 `const foo = require(\'pure-esm-package\')`\u3002\\n    - **\u914D\u5957\u63AA\u65BD**\uFF1A\u9700\u8981\u5728 `package.json` \u4E2D\u6DFB\u52A0 `\\"type\\": \\"module\\"` \u58F0\u660E\uFF0C\u5E76\u53EF\u80FD\u9700\u8981\u8C03\u6574\u6784\u5EFA\u914D\u7F6E\u3001\u6587\u4EF6\u6269\u5C55\u540D\u7B49\u3002\u4E0B\u6587\u4F1A\u8BE6\u7EC6\u4ECB\u7ECD\u3002\\n    - **\u524D\u7AEF\u89C6\u89D2**\uFF1A\u73B0\u4EE3\u524D\u7AEF\u6846\u67B6\uFF08\u5982 Vue 3, React with Vite, SvelteKit, Next.js 12+\uFF09\u539F\u751F\u6216\u66F4\u597D\u5730\u652F\u6301 ESM\u3002\u8FC1\u79FB\u5230 ESM \u53EF\u4EE5\u66F4\u597D\u5730\u5229\u7528 Tree Shaking\uFF08\u6447\u6811\u4F18\u5316\uFF09\u51CF\u5C11\u6700\u7EC8\u6253\u5305\u4F53\u79EF\uFF0C\u5E76\u4E0E\u6D4F\u89C8\u5668\u539F\u751F\u6A21\u5757\u52A0\u8F7D\u673A\u5236\u4FDD\u6301\u4E00\u81F4\u3002\\n\\n2.  **\u5728 CommonJS \u4E2D\u4F7F\u7528\u52A8\u6001 `import()` (\u5F02\u6B65\u4E0A\u4E0B\u6587)**\uFF1A\\n\\n    - **\u65B9\u6CD5**\uFF1A\u5982\u679C\u4F60\u7684\u4EE3\u7801\u5141\u8BB8\u5F02\u6B65\u64CD\u4F5C\uFF0C\u53EF\u4EE5\u4F7F\u7528 `await import(\'pure-esm-package\')` \u6765\u52A0\u8F7D ESM \u5305\u3002\\n    - **\u793A\u4F8B**:\\n      ```javascript\\n      // \u5728 async \u51FD\u6570\u6216\u9876\u5C42 await (Node.js >= 14.8) \u4E2D\\n      async function loadMyModule() {\\n        const { default: foo } = await import(\\"pure-esm-package\\");\\n        // \u6CE8\u610F\uFF1AESM \u9ED8\u8BA4\u5BFC\u51FA\u7684\u6A21\u5757\u9700\u8981\u901A\u8FC7 .default \u8BBF\u95EE\\n        // \u5982\u679C\u662F\u547D\u540D\u5BFC\u51FA\uFF0C\u5219\uFF1A const { namedExport } = await import(\'pure-esm-package\');\\n        foo.doSomething();\\n      }\\n      ```\\n    - **\u9650\u5236**\uFF1A\u8FD9\u53EA\u80FD\u5728\u5F02\u6B65\u51FD\u6570\u6216\u652F\u6301\u9876\u5C42 `await` \u7684\u73AF\u5883\u4E2D\u4F7F\u7528\u3002\u65E0\u6CD5\u7528\u4E8E\u9700\u8981\u540C\u6B65\u8FD4\u56DE\u6A21\u5757\u7684\u573A\u666F\u3002\\n    - **\u524D\u7AEF\u89C6\u89D2**\uFF1A\u52A8\u6001 `import()` \u5728\u524D\u7AEF\u5E38\u7528\u4E8E\u4EE3\u7801\u5206\u5272\uFF08Code Splitting\uFF09\uFF0C\u6309\u9700\u52A0\u8F7D\u8DEF\u7531\u6216\u7EC4\u4EF6\uFF0C\u4EE5\u4F18\u5316\u9996\u5C4F\u52A0\u8F7D\u6027\u80FD\u3002\u8FD9\u91CC\u7684\u7528\u6CD5\u7C7B\u4F3C\uFF0C\u4F46\u76EE\u7684\u662F\u89E3\u51B3 CJS/ESM \u4E92\u64CD\u4F5C\u6027\u95EE\u9898\u3002\\n\\n3.  **\u9501\u5B9A\u65E7\u7248\u672C**\uFF1A\\n\\n    - **\u65B9\u6CD5**\uFF1A\u6682\u65F6\u505C\u7559\u5728\u8BE5 Pure ESM \u5305\u7684\u6700\u540E\u4E00\u4E2A CommonJS \u517C\u5BB9\u7248\u672C\u3002\\n    - **\u98CE\u9669**\uFF1A\u4F60\u5C06\u65E0\u6CD5\u83B7\u5F97\u8BE5\u5305\u540E\u7EED\u7684\u65B0\u529F\u80FD\u3001\u6027\u80FD\u4F18\u5316\u548C\u5B89\u5168\u4FEE\u590D\u3002\u8FD9\u901A\u5E38\u53EA\u662F\u4E00\u4E2A\u77ED\u671F\u7F13\u5175\u4E4B\u8BA1\u3002\\n\\n4.  **\u5C1D\u8BD5 Node.js 22+ \u7684 `require()` ESM \u652F\u6301 (\u4E0D\u63A8\u8350)**\uFF1A\\n    - **\u80CC\u666F**\uFF1ANode.js 22 \u5F00\u59CB\u5B9E\u9A8C\u6027\u5730\u652F\u6301\u901A\u8FC7 `require()` \u52A0\u8F7D _\u540C\u6B65_ ESM \u6A21\u5757\u56FE\u3002\\n    - **\u5F3A\u70C8\u5EFA\u8BAE**\uFF1A**\u5B98\u65B9\u548C\u793E\u533A\u666E\u904D\u4E0D\u63A8\u8350\u4F9D\u8D56\u6B64\u7279\u6027**\u3002\u5B83\u53EF\u80FD\u5B58\u5728\u6027\u80FD\u95EE\u9898\u3001\u517C\u5BB9\u6027\u9677\u9631\uFF0C\u4E14\u8FDD\u80CC\u4E86 ESM \u7684\u8BBE\u8BA1\u54F2\u5B66\u3002**\u8FC1\u79FB\u5230 ESM \u624D\u662F\u6B63\u9014\u3002**\\n\\n**\u6700\u4F4E\u73AF\u5883\u8981\u6C42**\uFF1A\u8BF7\u786E\u4FDD\u4F60\u7684 Node.js \u7248\u672C\u81F3\u5C11\u4E3A v16\uFF0C**\u5F3A\u70C8\u63A8\u8350\u4F7F\u7528 Node.js 18 \u6216\u66F4\u9AD8\u7248\u672C**\uFF0C\u56E0\u4E3A\u8BB8\u591A\u73B0\u4EE3\u5DE5\u5177\u548C\u5E93\u90FD\u5DF2\u5C06\u6B64\u4F5C\u4E3A\u6700\u4F4E\u8981\u6C42\uFF0C\u5E76\u4E14\u5BF9 ESM \u7684\u652F\u6301\u66F4\u4E3A\u5B8C\u5584\u3002\\n\\n**\u6838\u5FC3\u7406\u5FF5**\uFF1AESM \u53EF\u4EE5\u5BFC\u5165 CommonJS \u5305\uFF08\u901A\u5E38\u6CA1\u6709\u95EE\u9898\uFF09\uFF0C\u4F46 CommonJS \u5305\u65E0\u6CD5\u540C\u6B65 `require()` ESM \u5305\u3002\u8FD9\u662F\u5355\u5411\u7684\u517C\u5BB9\u6027\u3002\\n\\n**\u8BF7\u6CE8\u610F**\uFF1A\u4F5C\u8005\u660E\u786E\u8868\u793A\uFF0C\u5176\u4ED3\u5E93**\u4E0D\u662F**\u89E3\u7B54\u901A\u7528 ESM\u3001TypeScript\u3001Webpack\u3001Jest\u3001ts-node\u3001Create React App (CRA) \u7B49\u5DE5\u5177\u652F\u6301\u95EE\u9898\u7684\u573A\u6240\u3002\u8BF7\u67E5\u9605\u76F8\u5E94\u5DE5\u5177\u7684\u5B98\u65B9\u6587\u6863\u6216\u793E\u533A\u3002\\n\\n---\\n\\n## FAQ\uFF1A\u8FC1\u79FB\u4E0E\u5B9E\u8DF5\u8BE6\u89E3\\n\\n### Q1: \u5982\u4F55\u5C06\u6211\u7684 CommonJS \u9879\u76EE\u8FC1\u79FB\u5230 ESM\uFF1F\\n\\n\u4EE5\u4E0B\u662F\u5173\u952E\u6B65\u9AA4\uFF1A\\n\\n1.  **`package.json` \u8BBE\u7F6E**\uFF1A\\n\\n    - \u6DFB\u52A0 `\\"type\\": \\"module\\"`\u3002\u8FD9\u544A\u8BC9 Node.js (\u548C\u8BB8\u591A\u6784\u5EFA\u5DE5\u5177) \u9ED8\u8BA4\u5C06 `.js` \u6587\u4EF6\u89C6\u4E3A ESM\u3002\\n    - \u5C06 `\\"main\\": \\"index.js\\"` \u66FF\u6362\u4E3A `\\"exports\\": \\"./index.js\\"`\u3002`\\"exports\\"` \u5B57\u6BB5\u63D0\u4F9B\u4E86\u66F4\u7CBE\u7EC6\u7684\u5305\u5165\u53E3\u70B9\u63A7\u5236\uFF0C\u662F\u73B0\u4EE3 Node.js \u5305\u7684\u6807\u51C6\u3002\\n    - \u66F4\u65B0 `\\"engines\\"` \u5B57\u6BB5\uFF0C\u5EFA\u8BAE\u81F3\u5C11 `\\"node\\": \\">=18\\"`\u3002\\n\\n2.  **\u4EE3\u7801\u8C03\u6574**\uFF1A\\n\\n    - \u79FB\u9664\u6240\u6709\u6587\u4EF6\u9876\u90E8\u7684 `\'use strict\';` (ESM \u9ED8\u8BA4\u5C31\u662F\u4E25\u683C\u6A21\u5F0F)\u3002\\n    - \u5C06\u6240\u6709 `require()` \u548C `module.exports` / `exports.*` \u66FF\u6362\u4E3A `import` \u548C `export` \u8BED\u6CD5\u3002\\n    - **\u4F7F\u7528\u5B8C\u6574\u7684\u76F8\u5BF9\u6587\u4EF6\u8DEF\u5F84**\uFF1A\u5BFC\u5165\u672C\u5730\u6587\u4EF6\u65F6\u5FC5\u987B\u5305\u542B\u6587\u4EF6\u6269\u5C55\u540D\uFF08\u901A\u5E38\u662F `.js`\uFF0C\u5373\u4F7F\u6E90\u6587\u4EF6\u662F `.ts` \u7F16\u8BD1\u540E\u4E5F\u5E94\u5BFC\u5165 `.js`\uFF09\u3002\u4F8B\u5982\uFF1A`import x from \'./utils\';` \u9700\u6539\u4E3A `import x from \'./utils.js\';`\u3002\\n    - \u5BFC\u5165 Node.js \u5185\u7F6E\u6A21\u5757\u65F6\uFF0C\u4F7F\u7528 `node:` \u534F\u8BAE\u524D\u7F00\uFF0C\u4F8B\u5982\uFF1A`import fs from \'node:fs\';`\u3002\u8FD9\u80FD\u660E\u786E\u533A\u5206\u5185\u7F6E\u6A21\u5757\u548C\u7B2C\u4E09\u65B9\u6A21\u5757\uFF0C\u5E76\u6709\u52A9\u4E8E\u67D0\u4E9B\u573A\u666F\u4E0B\u7684\u89E3\u6790\u3002\\n\\n3.  **TypeScript \u7C7B\u578B\u5B9A\u4E49 (\u5982\u679C\u9002\u7528)**\uFF1A\\n    - \u5982\u679C\u4F60\u7684\u5305\u5305\u542B\u7C7B\u578B\u5B9A\u4E49\u6587\u4EF6 (\u5982 `index.d.ts`)\uFF0C\u786E\u4FDD\u5176\u4E2D\u7684\u5BFC\u5165/\u5BFC\u51FA\u8BED\u6CD5\u4E5F\u66F4\u65B0\u4E3A ESM \u683C\u5F0F\u3002\\n\\n**\u6269\u5C55\u9605\u8BFB**\uFF1A\u5982\u679C\u4F60\u5BF9\u5982\u4F55\u4E3A JavaScript \u5305\u6DFB\u52A0\u7C7B\u578B\u5B9A\u4E49\u611F\u5174\u8DA3\uFF0C\u53EF\u4EE5\u53C2\u8003\u4F5C\u8005\u7684 [TypeScript Definition Style Guide](https://github.com/sindresorhus/typescript-definition-style-guide)\u3002\\n\\n### Q2: \u5982\u4F55\u5728 TypeScript \u9879\u76EE\u4E2D\u4F7F\u7528 (\u6216\u8F93\u51FA) ESM\uFF1F\\n\\n\u662F\u7684\uFF0C\u5B8C\u5168\u53EF\u4EE5\uFF01\u4F60\u9700\u8981\u914D\u7F6E TypeScript \u9879\u76EE\u4EE5\u8F93\u51FA ESM \u683C\u5F0F\u7684\u4EE3\u7801\u3002\\n\\n**\u5173\u952E\u6B65\u9AA4**\uFF1A\\n\\n1.  **TypeScript \u7248\u672C**\uFF1A\u786E\u4FDD\u4F7F\u7528 TypeScript 4.7 \u6216\u66F4\u9AD8\u7248\u672C\u3002\\n2.  **`package.json` \u914D\u7F6E**\uFF1A\\n    - \u6DFB\u52A0 `\\"type\\": \\"module\\"`\u3002\\n    - \u5C06 `\\"main\\"` \u66FF\u6362\u4E3A `\\"exports\\"` (\u540C\u4E0A)\u3002\\n    - \u66F4\u65B0 `\\"engines\\"` \u81F3 Node.js 18+ (\u540C\u4E0A)\u3002\\n3.  **`tsconfig.json` \u914D\u7F6E**\uFF1A\\n    - \u8BBE\u7F6E `\\"module\\": \\"node16\\"` \u6216 `\\"module\\": \\"nodenext\\"`\u3002**\u975E\u5E38\u91CD\u8981**\uFF0C\u8FD9\u6307\u793A TypeScript \u751F\u6210\u4E0E Node.js ESM \u517C\u5BB9\u7684 JavaScript \u4EE3\u7801\u3002\\n    - \u8BBE\u7F6E `\\"moduleResolution\\": \\"node16\\"` \u6216 `\\"moduleResolution\\": \\"nodenext\\"`\u3002**\u540C\u6837\u91CD\u8981**\uFF0C\u8FD9\u544A\u8BC9 TypeScript \u7F16\u8BD1\u5668\u5982\u4F55\u67E5\u627E\u6A21\u5757\uFF0C\u4F7F\u5176\u884C\u4E3A\u4E0E Node.js \u7684 ESM \u89E3\u6790\u89C4\u5219\u4E00\u81F4\u3002**\u7EDD\u5BF9\u4E0D\u80FD\u8BBE\u4E3A `\\"node\\"`\uFF01**\\n    - _\u793A\u4F8B\u914D\u7F6E\u53C2\u8003\uFF1A[sindresorhus/tsconfig](https://github.com/sindresorhus/tsconfig/blob/main/tsconfig.json)_\\n4.  **\u4EE3\u7801\u8C03\u6574**\uFF1A\\n    - **\u5FC5\u987B\u4F7F\u7528 `.js` \u6269\u5C55\u540D\u8FDB\u884C\u76F8\u5BF9\u5BFC\u5165**\uFF0C\u5373\u4F7F\u4F60\u5B9E\u9645\u5BFC\u5165\u7684\u662F `.ts` \u6587\u4EF6\u3002TypeScript \u4F1A\u5728\u7F16\u8BD1\u65F6\u6B63\u786E\u5904\u7406\u5B83\u4EEC\u3002`import util from \'./util\';` -> `import util from \'./util.js\';`\\n    - \u79FB\u9664 `namespace` \u7528\u6CD5\uFF0C\u6539\u7528 `export`\u3002\\n    - \u4F7F\u7528 `node:` \u534F\u8BAE\u5BFC\u5165 Node.js \u5185\u7F6E\u6A21\u5757\u3002\\n\\n**\u5173\u4E8E `ts-node`**\uFF1A\u5982\u679C\u4F7F\u7528 `ts-node` \u76F4\u63A5\u8FD0\u884C TS \u4EE3\u7801\uFF0C\u9700\u8981\u9075\u5FAA [ts-node ESM \u6307\u5357](https://github.com/TypeStrong/ts-node/issues/1007)\u3002\u53C2\u8003\u914D\u7F6E\uFF1A[Example config](https://github.com/sindresorhus/got/blob/5f278d74125608b7abe75941cb6a71e21e0fb892/tsconfig.json#L17-L21)\u3002(\u63A8\u8350\u4F7F\u7528 `tsx` \u4F5C\u4E3A\u66FF\u4EE3\u54C1)\\n\\n### Q3: Electron \u4E2D\u5982\u4F55\u4F7F\u7528 ESM\uFF1F\\n\\nElectron \u4ECE\u7248\u672C 28 \u5F00\u59CB\u652F\u6301 ESM\u3002\u8BF7\u53C2\u8003 [Electron ESM \u5B98\u65B9\u6587\u6863](https://github.com/electron/electron/blob/main/docs/tutorial/esm.md)\u3002\\n\\n### Q4: Webpack \u6784\u5EFA\u9047\u5230 ESM \u95EE\u9898\u600E\u4E48\u529E\uFF1F\\n\\n\u95EE\u9898\u5F88\u53EF\u80FD\u51FA\u5728 Webpack \u672C\u8EAB\u6216\u4F60\u7684 Webpack \u914D\u7F6E\u4E0A\u3002\\n\\n1.  \u786E\u4FDD\u4F60\u4F7F\u7528\u7684\u662F\u6700\u65B0\u7248\u672C\u7684 Webpack\u3002\\n2.  \u68C0\u67E5\u4F60\u7684 `webpack.config.js` \u662F\u5426\u6B63\u786E\u5904\u7406\u4E86 `.js` / `.mjs` \u6587\u4EF6\u4EE5\u53CA `package.json` \u4E2D\u7684 `\\"type\\": \\"module\\"`\u3002\u53EF\u80FD\u9700\u8981\u8C03\u6574 `resolve`\u3001`module.rules` \u7B49\u914D\u7F6E\u3002\\n3.  **\u4E0D\u8981** \u5728\u539F\u4F5C\u8005\u7684\u4ED3\u5E93\u63D0\u95EE\u3002\u5C1D\u8BD5\u5728 Stack Overflow \u63D0\u95EE\u6216\u5728 [Webpack \u7684 GitHub \u4ED3\u5E93](https://github.com/webpack/webpack) \u63D0\u4EA4 issue\u3002\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1AWebpack 5 \u5BF9 ESM \u6709\u4E86\u66F4\u597D\u7684\u539F\u751F\u652F\u6301\uFF0C\u4F46\u4E0E CJS \u6DF7\u7528\u3001\u4F9D\u8D56\u9879\u7684\u6A21\u5757\u683C\u5F0F\u3001\u4EE5\u53CA loader/plugin \u7684\u517C\u5BB9\u6027\u4ECD\u53EF\u80FD\u5F15\u53D1\u95EE\u9898\u3002\u786E\u4FDD `experiments.outputModule` (\u5982\u679C\u9700\u8981\u8F93\u51FA ESM bundle) \u6216 `module.rules` \u4E2D\u5BF9 `.mjs` \u548C `.js` (\u5728 `\\"type\\": \\"module\\"` \u9879\u76EE\u4E2D) \u7684\u5904\u7406\u662F\u6B63\u786E\u7684\u3002Vite \u7B49\u57FA\u4E8E\u539F\u751F ESM \u7684\u6784\u5EFA\u5DE5\u5177\u901A\u5E38\u80FD\u66F4\u987A\u7545\u5730\u5904\u7406 ESM \u4F9D\u8D56\u3002\\n\\n### Q5: Next.js \u6784\u5EFA\u9047\u5230 ESM \u95EE\u9898\u600E\u4E48\u529E\uFF1F\\n\\n\u5347\u7EA7\u5230 **Next.js 12 \u6216\u66F4\u9AD8\u7248\u672C**\u3002Next.js 12 \u5F15\u5165\u4E86\u5BF9 ESM \u7684\u5168\u9762\u652F\u6301\uFF0C\u5305\u62EC npm \u5305\u548C URL Imports\u3002\\n\\n### Q6: Jest \u6D4B\u8BD5\u9047\u5230 ESM \u95EE\u9898\u600E\u4E48\u529E\uFF1F\\n\\nJest \u5BF9 ESM \u7684\u652F\u6301\u4ECD\u5728\u53D1\u5C55\u4E2D\u3002\\n\\n1.  \u9605\u8BFB [Jest \u5B98\u65B9 ESM \u6587\u6863](https://jestjs.io/docs/ecmascript-modules)\u3002\\n2.  \u4F60\u53EF\u80FD\u9700\u8981\uFF1A\\n    - \u5728 Node.js \u8FD0\u884C\u65F6\u6DFB\u52A0 `--experimental-vm-modules` \u6807\u5FD7 (\u901A\u8FC7 `NODE_OPTIONS` \u73AF\u5883\u53D8\u91CF)\u3002\\n    - \u4F7F\u7528 `jest-environment-node` \u6216\u81EA\u5B9A\u4E49\u73AF\u5883\u3002\\n    - \u914D\u7F6E `transform` \u9009\u9879\u6765\u5904\u7406 ESM \u8BED\u6CD5\uFF08\u5982\u679C\u9700\u8981\u8F6C\u8BD1\uFF09\u6216\u8BBE\u7F6E\u4E3A\u7A7A\u5BF9\u8C61 `{}` \u4EE5\u7981\u7528 CommonJS \u8F6C\u6362\u3002\\n    - \u786E\u4FDD\u4F60\u7684 `package.json` \u8BBE\u7F6E\u4E86 `\\"type\\": \\"module\\"`\u3002\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1AVitest \u662F\u4E00\u4E2A\u57FA\u4E8E Vite \u7684\u73B0\u4EE3\u6D4B\u8BD5\u6846\u67B6\uFF0C\u5B83\u539F\u751F\u652F\u6301 ESM\uFF0C\u5E76\u4E14\u914D\u7F6E\u901A\u5E38\u6BD4 Jest \u66F4\u7B80\u5355\uFF0C\u53EF\u4EE5\u4F5C\u4E3A Jest \u7684\u66FF\u4EE3\u65B9\u6848\u3002\\n\\n### Q7: TypeScript + ESM \u9047\u5230\u7684\u5176\u4ED6\u95EE\u9898\uFF1F\\n\\n\u518D\u6B21\u786E\u8BA4\uFF1A\\n\\n1.  `package.json` \u4E2D\u6709 `\\"type\\": \\"module\\"`\u3002\\n2.  `tsconfig.json` \u4E2D\u8BBE\u7F6E\u4E86 `\\"module\\": \\"node16\\"` (\u6216 `nodenext`)\u3002\\n3.  \u6240\u6709**\u672C\u5730\u6587\u4EF6**\u7684\u5BFC\u5165\u8BED\u53E5\u90FD\u4F7F\u7528\u4E86 `.js` \u6269\u5C55\u540D\u3002\\n\\n### Q8: `ts-node` + ESM \u9047\u5230\u7684\u95EE\u9898\uFF1F\\n\\n**\u63A8\u8350\u66FF\u4EE3\u54C1**\uFF1A\u8003\u8651\u4F7F\u7528 [`tsx`](https://github.com/privatenumber/tsx)\uFF0C\u5B83\u63D0\u4F9B\u4E86\u66F4\u597D\u7684 ESM \u652F\u6301\u548C\u6027\u80FD\u3002\\n\\n\u5982\u679C\u4ECD\u8981\u4F7F\u7528 `ts-node`\uFF0C\u8BF7\u786E\u4FDD\u662F\u6700\u65B0\u7248\u672C\uFF0C\u5E76\u9075\u5FAA [\u8FD9\u4E2A\u6307\u5357](https://github.com/TypeStrong/ts-node/issues/1007)\u3002[\u793A\u4F8B\u914D\u7F6E](https://github.com/sindresorhus/got/blob/5f278d74125608b7abe75941cb6a71e21e0fb892/tsconfig.json#L17-L21)\u3002\\n\\n### Q9: Create React App (CRA) \u9047\u5230 ESM \u95EE\u9898\u600E\u4E48\u529E\uFF1F\\n\\nCRA \u5BF9 Pure ESM \u5305\u7684\u652F\u6301\u8FD8\u4E0D\u5B8C\u5584\u3002\u5DF2\u77E5\u95EE\u9898\u5982 [#10933](https://github.com/facebook/create-react-app/issues/10933)\u3002\\n\\n- **\u5EFA\u8BAE**\uFF1A\u5411 CRA \u4ED3\u5E93\u62A5\u544A\u4F60\u9047\u5230\u7684\u5177\u4F53\u95EE\u9898\u3002\\n- **\u524D\u7AEF\u8865\u5145**\uFF1ACRA \u7684\u5E95\u5C42\u6784\u5EFA\u5DE5\u5177 (Webpack) \u548C\u914D\u7F6E\u53EF\u80FD\u6CA1\u6709\u5B8C\u5168\u8DDF\u4E0A ESM \u7684\u6B65\u4F10\u3002\u5BF9\u4E8E\u65B0\u9879\u76EE\u6216\u9700\u8981\u66F4\u597D ESM \u652F\u6301\u7684\u9879\u76EE\uFF0C\u53EF\u4EE5\u8003\u8651\u4F7F\u7528 Vite + React \u6A21\u677F\uFF0CVite \u5BF9 ESM \u7684\u539F\u751F\u652F\u6301\u4F7F\u5176\u5904\u7406\u8FD9\u7C7B\u4F9D\u8D56\u66F4\u52A0\u987A\u7545\u3002\\n\\n### Q10: \u5982\u4F55\u5728 ESM \u9879\u76EE\u4E2D\u4F7F\u7528 TypeScript \u548C AVA \u8FDB\u884C\u6D4B\u8BD5\uFF1F\\n\\n\u9075\u5FAA [AVA \u5B98\u65B9 TypeScript \u6307\u5357 (\u9488\u5BF9 type: module \u5305)](https://github.com/avajs/ava/blob/main/docs/recipes/typescript.md#for-packages-with-type-module)\u3002\\n\\n### Q11: \u5982\u4F55\u786E\u4FDD\u4E0D\u610F\u5916\u4F7F\u7528 CommonJS \u7279\u6709\u7684\u5199\u6CD5\uFF1F\\n\\n\u4F7F\u7528 ESLint \u89C4\u5219\u6765\u5F3A\u5236\u6267\u884C ESM \u6700\u4F73\u5B9E\u8DF5\uFF1A\\n\\n- [`eslint-plugin-unicorn/prefer-module`](https://github.com/sindresorhus/eslint-plugin-unicorn/blob/main/docs/rules/prefer-module.md): \u5F3A\u5236\u4F7F\u7528 ESM \u98CE\u683C\uFF08`import`/`export`\uFF0C`.js` \u6269\u5C55\u540D\u7B49\uFF09\u3002\\n- [`eslint-plugin-unicorn/prefer-node-protocol`](https://github.com/sindresorhus/eslint-plugin-unicorn/blob/main/docs/rules/prefer-node-protocol.md): \u5F3A\u5236\u4F7F\u7528 `node:` \u534F\u8BAE\u5BFC\u5165\u5185\u7F6E\u6A21\u5757\u3002\\n\\n### Q12: ESM \u4E2D\u6CA1\u6709 `__dirname` \u548C `__filename`\uFF0C\u600E\u4E48\u529E\uFF1F\\n\\n\u4F7F\u7528 `import.meta.url` \u6765\u83B7\u53D6\u5F53\u524D\u6A21\u5757\u7684 URL\u3002\\n\\n- **Node.js 20.11+ / 21.2+**:\\n\\n  - \u53EF\u4EE5\u76F4\u63A5\u4F7F\u7528 `import.meta.dirname` \u548C `import.meta.filename`\u3002\\n\\n- **\u65E7\u7248 Node.js**:\\n\\n  ```javascript\\n  import { fileURLToPath } from \\"node:url\\";\\n  import path from \\"node:path\\";\\n\\n  // \u83B7\u53D6\u5F53\u524D\u6587\u4EF6\u7684\u7EDD\u5BF9\u8DEF\u5F84\\n  const __filename = fileURLToPath(import.meta.url);\\n  // \u83B7\u53D6\u5F53\u524D\u6587\u4EF6\u6240\u5728\u76EE\u5F55\u7684\u7EDD\u5BF9\u8DEF\u5F84\\n  const __dirname = path.dirname(__filename); // \u6216\u8005 path.dirname(fileURLToPath(import.meta.url))\\n  ```\\n\\n- **\u66F4\u5E38\u7528\u7684\u6A21\u5F0F (\u6784\u9020\u76F8\u5BF9\u4E8E\u5F53\u524D\u6A21\u5757\u7684\u8DEF\u5F84)**:\\n\\n  ```javascript\\n  import { fileURLToPath } from \\"node:url\\";\\n\\n  // \u83B7\u53D6\u540C\u76EE\u5F55\u4E0B foo.js \u7684\u6587\u4EF6\u7CFB\u7EDF\u8DEF\u5F84\\n  const fooPath = fileURLToPath(new URL(\\"foo.js\\", import.meta.url));\\n  ```\\n\\n- **\u8BB8\u591A Node.js API \u76F4\u63A5\u63A5\u53D7 URL \u5BF9\u8C61**:\\n  ```javascript\\n  // \u76F4\u63A5\u521B\u5EFA URL \u5BF9\u8C61\uFF0C\u53EF\u80FD\u53EF\u4EE5\u76F4\u63A5\u4F20\u9012\u7ED9\u67D0\u4E9B API (\u5982 fs.readFile)\\n  const fooUrl = new URL(\\"foo.js\\", import.meta.url);\\n  // await fs.readFile(fooUrl); // \u793A\u4F8B\\n  ```\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1A\u5728\u6D4F\u89C8\u5668\u73AF\u5883\u4E2D\uFF0C`import.meta.url` \u540C\u6837\u53EF\u7528\uFF0C\u5B83\u8FD4\u56DE\u7684\u662F\u6A21\u5757\u7684 URL\u3002\u4F46\u5728\u524D\u7AEF\u6784\u5EFA\u6253\u5305\u540E\uFF0C\u8FD9\u4E2A\u503C\u53EF\u80FD\u6307\u5411 `blob:` URL \u6216\u6253\u5305\u540E\u7684\u6587\u4EF6\u8DEF\u5F84\uFF0C\u5176\u884C\u4E3A\u53EF\u80FD\u4E0E Node.js \u73AF\u5883\u4E0D\u5B8C\u5168\u4E00\u81F4\u3002\u901A\u5E38\u5728\u524D\u7AEF\u4EE3\u7801\u4E2D\u76F4\u63A5\u64CD\u4F5C\u6587\u4EF6\u7CFB\u7EDF\u7684\u573A\u666F\u8F83\u5C11\uFF0C\u66F4\u591A\u662F\u5904\u7406\u76F8\u5BF9\u8D44\u6E90\u7684 URL\u3002\\n\\n### Q13: \u6D4B\u8BD5\u65F6\u5982\u4F55\u5BFC\u5165\u6A21\u5757\u5E76\u7ED5\u8FC7\u7F13\u5B58\uFF1F\\n\\n\u5728 ESM \u4E2D\uFF0C\u6CA1\u6709\u50CF CommonJS `delete require.cache[modulePath]` \u90A3\u6837\u6807\u51C6\u7684\u3001\u7B80\u5355\u7684\u65B9\u6CD5\u6765\u6E05\u9664\u7F13\u5B58\u3002\\n\\n- **\u4E34\u65F6\u65B9\u6848 (\u4EC5\u9650\u6D4B\u8BD5\uFF0C\u6709\u5185\u5B58\u6CC4\u6F0F\u98CE\u9669\uFF01)**: \u901A\u8FC7\u7ED9\u5BFC\u5165\u8DEF\u5F84\u6DFB\u52A0\u52A8\u6001\u67E5\u8BE2\u53C2\u6570\u6765\u5F3A\u5236\u91CD\u65B0\u52A0\u8F7D\u3002\\n\\n  ```javascript\\n  const importFresh = async (modulePath) => {\\n    // \u6DFB\u52A0\u65F6\u95F4\u6233\u4F5C\u4E3A\u67E5\u8BE2\u53C2\u6570\uFF0C\u6B3A\u9A97\u6A21\u5757\u52A0\u8F7D\u5668\u8BA4\u4E3A\u662F\u4E0D\u540C\u7684\u6A21\u5757\\n    return import(`${modulePath}?t=${Date.now()}`);\\n  };\\n\\n  // \u4F7F\u7528\u793A\u4F8B\\n  const chalk = (await importFresh(\\"chalk\\")).default;\\n  ```\\n\\n  **\u8B66\u544A**:\\n\\n  1.  \u8FD9\u79CD\u65B9\u6CD5\u4F1A**\u5BFC\u81F4\u5185\u5B58\u6CC4\u6F0F**\uFF0C\u56E0\u4E3A\u65E7\u6A21\u5757\u5B9E\u4F8B\u4E0D\u4F1A\u88AB\u5783\u573E\u56DE\u6536\u3002**\u7EDD\u5BF9\u4E0D\u8981\u5728\u751F\u4EA7\u73AF\u5883\u4E2D\u4F7F\u7528**\u3002\\n  2.  \u5B83\u53EA\u4F1A\u91CD\u65B0\u52A0\u8F7D\u4F60\u76F4\u63A5\u5BFC\u5165\u7684\u90A3\u4E2A\u6A21\u5757\uFF0C**\u4E0D\u4F1A**\u91CD\u65B0\u52A0\u8F7D\u5176\u4F9D\u8D56\u9879\u3002\\n\\n- **\u672A\u6765**\uFF1ANode.js \u7684 [ESM Loader Hooks](https://github.com/nodejs/modules/issues/307) \u6210\u719F\u540E\u53EF\u80FD\u4F1A\u63D0\u4F9B\u66F4\u597D\u7684\u89E3\u51B3\u65B9\u6848\u3002\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1A\u5728\u6D4F\u89C8\u5668\u7AEF\uFF0C\u6A21\u5757\u7F13\u5B58\u7531\u6D4F\u89C8\u5668\u7BA1\u7406\u3002\u6D4B\u8BD5\u6846\u67B6\uFF08\u5982 Vitest\uFF09\u901A\u5E38\u6709\u81EA\u5DF1\u7684\u6A21\u5757\u6A21\u62DF\uFF08mocking\uFF09\u548C\u9694\u79BB\u673A\u5236\uFF0C\u4E0D\u4F9D\u8D56\u8FD9\u79CD hacky \u7684\u7F13\u5B58\u6E05\u9664\u65B9\u5F0F\u3002\\n\\n### Q14: \u5982\u4F55\u5BFC\u5165 JSON \u6587\u4EF6\uFF1F\\n\\n- **Node.js 17.5+ (\u9700\u8981 `--experimental-json-modules` \u6807\u5FD7) / Node.js 18.20+ (\u7A33\u5B9A)**:\\n  - \u4F7F\u7528 **Import Assertions** (\u5BFC\u5165\u65AD\u8A00):\\n    ```javascript\\n    import packageJson from \'./package.json\' with { type: \'json\' };\\n    console.log(packageJson.version);\\n    ```\\n- **\u65E7\u7248 Node.js \u6216\u4E0D\u4F7F\u7528\u5B9E\u9A8C\u6027\u7279\u6027**: \\\\* \u4F7F\u7528 `fs` \u6A21\u5757\u8BFB\u53D6\u6587\u4EF6\u5E76\u624B\u52A8\u89E3\u6790\uFF1A\\n\\n  ````javascript\\n  import fs from \'node:fs/promises\';\\n\\n          const packageJsonContent = await fs.readFile(\'./package.json\', \'utf8\');\\n          const packageJson = JSON.parse(packageJsonContent);\\n          console.log(packageJson.version);\\n          ```\\n\\n  **\u524D\u7AEF\u8865\u5145**\uFF1A\u73B0\u4EE3\u524D\u7AEF\u6784\u5EFA\u5DE5\u5177\uFF08Webpack, Vite, Rollup \u7B49\uFF09\u901A\u5E38\u5185\u7F6E\u4E86\u5BF9 JSON \u5BFC\u5165\u7684\u652F\u6301\uFF0C\u4F60\u53EF\u4EE5\u5728\u4EE3\u7801\u4E2D\u76F4\u63A5 `import data from \'./data.json\';`\uFF0C\u6784\u5EFA\u5DE5\u5177\u4F1A\u8D1F\u8D23\u5904\u7406\u3002Import Assertions \u662F\u66F4\u6807\u51C6\u5316\u7684\u65B9\u5F0F\uFF0C\u672A\u6765\u53EF\u80FD\u4F1A\u88AB\u6784\u5EFA\u5DE5\u5177\u66F4\u5E7F\u6CDB\u5730\u539F\u751F\u652F\u6301\u3002\\n  ````\\n\\n### Q15: \u4F55\u65F6\u4F7F\u7528\u9ED8\u8BA4\u5BFC\u51FA (default export) vs \u547D\u540D\u5BFC\u51FA (named exports)\uFF1F\\n\\n\u8FD9\u662F\u4E00\u4E2A\u98CE\u683C\u548C\u5B9E\u8DF5\u95EE\u9898\uFF0C\u4F5C\u8005\u7ED9\u51FA\u4E86\u4ED6\u7684\u5EFA\u8BAE\uFF1A\\n\\n- **\u9ED8\u8BA4\u5BFC\u51FA (`export default`)**:\\n\\n  - \u9002\u7528\u4E8E\u4E00\u4E2A\u6A21\u5757\u4E3B\u8981\u5BFC\u51FA\u4E00\u4E2A**\u6838\u5FC3**\u529F\u80FD\u3001\u7C7B\u6216\u5BF9\u8C61\u65F6\u3002\\n  - \u4F8B\u5982\uFF1A\u4E00\u4E2A `left-pad` \u5E93\u4E3B\u8981\u5C31\u662F\u90A3\u4E2A\u586B\u5145\u51FD\u6570\u3002\\n  - \u53EF\u4EE5\u4E0E\u547D\u540D\u5BFC\u51FA\u7ED3\u5408\u4F7F\u7528\uFF1A\\n\\n    ```javascript\\n    // read-json.js\\n    export default function readJson() {\\n      /* ... */\\n    }\\n    export class JSONError extends Error {\\n      /* ... */\\n    }\\n\\n    // usage.js\\n    import readJson, { JSONError } from \\"read-json\\";\\n    ```\\n\\n- **\u547D\u540D\u5BFC\u51FA (`export { ... }` \u6216 `export const/function/class ...`)**:\\n\\n  - **\u591A\u4E2A\u4E3B\u8981 API**: \u5982\u679C\u4E00\u4E2A\u5305\u63D0\u4F9B\u591A\u4E2A\u540C\u7B49\u91CD\u8981\u7684\u529F\u80FD\uFF0C\u7279\u522B\u662F\u5305\u542B\u540C\u6B65\u548C\u5F02\u6B65\u7248\u672C\u65F6\uFF0C\u4F7F\u7528\u547D\u540D\u5BFC\u51FA\u66F4\u6E05\u6670\u3002\\n\\n    ```javascript\\n    // read-json.js\\n    export function readJson() {\\n      /* async */\\n    }\\n    export function readJsonSync() {\\n      /* sync */\\n    }\\n\\n    // usage.js\\n    import { readJson, readJsonSync } from \\"read-json\\"; // \u6E05\u6670\u533A\u5206\\n    ```\\n\\n  - **\u907F\u514D\u6A21\u7CCA\u547D\u540D**: \u907F\u514D\u4F7F\u7528\u8FC7\u4E8E\u901A\u7528\u7684\u540D\u79F0\u4F5C\u4E3A\u547D\u540D\u5BFC\u51FA\uFF0C\u8FD9\u4F1A\u8FEB\u4F7F\u6D88\u8D39\u8005\u91CD\u547D\u540D\u4EE5\u9632\u51B2\u7A81\u3002\\n\\n    ```javascript\\n    // \u274C \u4E0D\u597D\u7684\u4F8B\u5B50: parse-json.js\\n    // export function parse() { ... }\\n\\n    // \u6D88\u8D39\u8005\u9700\u8981\u91CD\u547D\u540D\\n    // import { parse as parseJson } from \'parse-json\';\\n\\n    // \u2705 \u597D\u7684\u4F8B\u5B50: parse-json.js\\n    export function parseJson() { ... }\\n\\n    // \u6D88\u8D39\u8005\u76F4\u63A5\u4F7F\u7528\\n    import { parseJson } from \'parse-json\';\\n    ```\\n\\n  - **\u53D6\u4EE3\u547D\u540D\u7A7A\u95F4\u6A21\u5F0F**: ESM \u4E2D\uFF0C\u503E\u5411\u4E8E\u4F7F\u7528\u63CF\u8FF0\u6027\u7684\u547D\u540D\u5BFC\u51FA\uFF0C\u800C\u4E0D\u662F\u50CF CommonJS \u90A3\u6837\u5BFC\u51FA\u4E00\u4E2A\u5305\u542B\u591A\u4E2A\u65B9\u6CD5\u7684\u5BF9\u8C61\uFF08\u547D\u540D\u7A7A\u95F4\uFF09\u3002\\n\\n    ```javascript\\n    // CommonJS (\u65E7)\\n    // const isStream = require(\'is-stream\');\\n    // isStream.writable(stream);\\n\\n    // ESM (\u63A8\u8350)\\n    // is-stream.js\\n    // export function isStream() { ... }\\n    // export function isReadableStream() { ... }\\n    // export function isWritableStream() { ... }\\n\\n    // usage.js\\n    import { isWritableStream } from \\"is-stream\\";\\n    isWritableStream(stream);\\n    ```\\n\\n**\u524D\u7AEF\u8865\u5145**\uFF1A\\n\\n- **Tree Shaking**: \u547D\u540D\u5BFC\u51FA\u901A\u5E38\u5BF9 Tree Shaking \u66F4\u53CB\u597D\u3002\u6784\u5EFA\u5DE5\u5177\u80FD\u66F4\u5BB9\u6613\u5730\u9759\u6001\u5206\u6790\u51FA\u54EA\u4E9B\u547D\u540D\u5BFC\u51FA\u88AB\u4F7F\u7528\u4E86\uFF0C\u4ECE\u800C\u79FB\u9664\u672A\u4F7F\u7528\u7684\u4EE3\u7801\u3002\u9ED8\u8BA4\u5BFC\u51FA\u5982\u679C\u662F\u5BF9\u8C61\u6216\u7C7B\uFF0C\u5176\u5185\u90E8\u65B9\u6CD5\u7684\u6447\u6811\u4F18\u5316\u53EF\u80FD\u9700\u8981\u66F4\u590D\u6742\u7684\u5206\u6790\u6216\u7279\u5B9A\u5199\u6CD5\u3002\\n- **\u7EC4\u4EF6\u5E93**: \u5927\u578B\u7EC4\u4EF6\u5E93\u901A\u5E38\u4F7F\u7528\u547D\u540D\u5BFC\u51FA\u6765\u5BFC\u51FA\u5404\u4E2A\u7EC4\u4EF6\uFF0C\u65B9\u4FBF\u7528\u6237\u6309\u9700\u5BFC\u5165\uFF1A`import { Button, Modal } from \'my-ui-library\';`\u3002\\n- **\u53EF\u8BFB\u6027\u4E0E\u53EF\u53D1\u73B0\u6027**: \u547D\u540D\u5BFC\u51FA\u4F7F\u5F97\u6A21\u5757\u63D0\u4F9B\u7684\u529F\u80FD\u66F4\u52A0\u4E00\u76EE\u4E86\u7136\uFF0CIDE \u4E5F\u80FD\u63D0\u4F9B\u66F4\u597D\u7684\u81EA\u52A8\u8865\u5168\u63D0\u793A\u3002\\n\\n---\\n\\n## \u603B\u7ED3\\n\\n\u8F6C\u5411 Pure ESM \u662F JavaScript \u751F\u6001\u7CFB\u7EDF\u53D1\u5C55\u7684\u5FC5\u7136\u8D8B\u52BF\u3002\u867D\u7136\u77ED\u671F\u5185\u4F1A\u7ED9\u4F7F\u7528 CommonJS \u7684\u9879\u76EE\u5E26\u6765\u4E00\u4E9B\u6311\u6218\uFF0C\u4F46\u7406\u89E3 ESM \u7684\u57FA\u672C\u539F\u7406\u3001\u638C\u63E1\u8FC1\u79FB\u6B65\u9AA4\u548C\u89E3\u51B3\u5E38\u89C1\u95EE\u9898\u7684\u7B56\u7565\u81F3\u5173\u91CD\u8981\u3002\u79EF\u6781\u62E5\u62B1 ESM \u4E0D\u4EC5\u80FD\u8BA9\u4F60\u4F7F\u7528\u6700\u65B0\u7684\u5E93\u548C\u5DE5\u5177\uFF0C\u8FD8\u80FD\u4EAB\u53D7\u5230\u6A21\u5757\u6807\u51C6\u5316\u3001\u6027\u80FD\u4F18\u5316\uFF08\u5982\u66F4\u597D\u7684 Tree Shaking\uFF09\u548C\u4E0E\u6D4F\u89C8\u5668\u73AF\u5883\u66F4\u4E00\u81F4\u7684\u5F00\u53D1\u4F53\u9A8C\u3002\u5BF9\u4E8E\u524D\u7AEF\u5F00\u53D1\u8005\u800C\u8A00\uFF0C\u719F\u6089 ESM \u66F4\u662F\u73B0\u4EE3 Web \u5F00\u53D1\u7684\u57FA\u7840\u3002"}]}}')}}]);